/** Koszty portfela — ile już poszło na opłaty i ile kosztowałoby wyjście z pozycji.
 *
 *  Dwie sekcje są rozdzielone celowo:
 *   - ZAPŁACONE liczymy z historii (spread przewalutowania = kurs brokera kontra kurs
 *     NBP z tego dnia). Te pieniądze już wyszły z konta, więc siedzą w wycenie —
 *     pokazujemy je tylko po to, żeby było wiadomo, ile kosztowało dojście tutaj.
 *   - WYJŚCIA to jedyny koszt, którego w danych nie ma: sprzedaż pozycji i zamiana
 *     walut na złotówki. Dopiero po jego odjęciu widać, ile zostałoby w kieszeni.
 */
import React, { useState } from "react";
import { ActivityIndicator, StyleSheet, Text, TextInput, View } from "react-native";
import { BrokerOption, Costs as CostsData, FeeProfile, saveAccountFees } from "../api";
import { C, fmtPLN, T } from "../theme";
import { Card, LiquidButton, MetalButton, Press, Row, SectionTitle } from "../ui";

const FIELDS: { key: keyof FeeProfile; label: string; hint: string; suffix: string }[] = [
  { key: "stock_pct", label: "Prowizja od transakcji", hint: "procent wartości zlecenia", suffix: "%" },
  { key: "stock_min", label: "Minimalna prowizja", hint: "za jedno zlecenie", suffix: "" },
  { key: "free_turnover_eur", label: "Darmowy obrót", hint: "miesięcznie, w EUR", suffix: "EUR" },
  { key: "fx_pct", label: "Przewalutowanie", hint: "marża brokera na kursie", suffix: "%" },
  { key: "spread_pct", label: "Spread", hint: "opcjonalnie, koszt kupna/sprzedaży", suffix: "%" },
];

export default function Costs({ data, onSaved }: { data: CostsData; onSaved: () => void }) {
  const [open, setOpen] = useState<string | null>(null);

  const paid = data.paid;
  const exit = data.exit;

  return (
    <>
      <SectionTitle hint="Opłaty i spready policzone z Twojej historii — te pieniądze już wyszły z konta">
        Zapłacone koszty
      </SectionTitle>
      <Card style={s.card}>
        <Row k="Przewalutowania" v={fmtPLN(paid.fx_spread_pln)} />
        <Row k="Marża na kursie"
             v={`${paid.fx_spread_pct.toLocaleString("pl-PL", { maximumFractionDigits: 2 })}%`} />
        <Row k="Zamieniono walut" v={fmtPLN(paid.fx_volume_pln)} />
        <Row k="Opłaty brokera" v={fmtPLN(paid.fees_pln)} />
        <Row k="Podatki" v={fmtPLN(paid.taxes_pln)} last />
      </Card>
      <Text style={s.note}>
        Marżę liczymy porównując kurs z operacji przewalutowania z kursem NBP z tego samego
        dnia — to realnie zatrzymana różnica, a nie stawka z cennika.
      </Text>

      <SectionTitle hint="Czego jeszcze nie widać w wycenie: sprzedaż pozycji i zamiana walut na złotówki">
        Koszt wyjścia
      </SectionTitle>
      <Card style={s.card}>
        <Row k="Prowizje od sprzedaży" v={fmtPLN(exit.sell_pln)} />
        <Row k="Zamiana walut na PLN" v={fmtPLN(exit.fx_pln)} />
        {exit.spread_pln > 0 && <Row k="Spread" v={fmtPLN(exit.spread_pln)} />}
        <Row k="Razem" v={fmtPLN(exit.total_pln)} color={C.amber} />
        <Row k="Wartość po kosztach" v={fmtPLN(data.value_net)} color={C.text} last />
      </Card>

      <SectionTitle hint="Broker rozpoznany z raportu. Stawki możesz nadpisać — liczymy nimi koszt wyjścia">
        Prowizje kont
      </SectionTitle>

      {data.accounts.map((a) => (
        <AccountFees
          key={a.account}
          account={a.account}
          currency={a.currency}
          broker={a.broker}
          profile={a.profile}
          catalog={data.catalog}
          expanded={open === a.account}
          onToggle={() => setOpen(open === a.account ? null : a.account)}
          onSaved={onSaved}
        />
      ))}
    </>
  );
}

function AccountFees({
  account, currency, broker, profile, catalog, expanded, onToggle, onSaved,
}: {
  account: string; currency: string; broker: string; profile: FeeProfile;
  catalog: BrokerOption[]; expanded: boolean; onToggle: () => void; onSaved: () => void;
}) {
  const [pick, setPick] = useState(broker || "OTHER");
  const [vals, setVals] = useState<Record<string, string>>(() => initial(profile));
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");

  function initial(p: FeeProfile): Record<string, string> {
    return {
      stock_pct: String(p.stock_pct ?? 0),
      stock_min: String(p.stock_min ?? 0),
      min_currency: p.min_currency || "PLN",
      free_turnover_eur: String(p.free_turnover_eur ?? 0),
      fx_pct: String(p.fx_pct ?? 0),
      spread_pct: String(p.spread_pct ?? 0),
      label: p.label || "",
    };
  }

  /** Wybór brokera z listy podstawia jego stawki — dalej można je ręcznie poprawić. */
  function choose(id: string) {
    setPick(id);
    const found = catalog.find((c) => c.id === id);
    if (found) setVals(initial(found));
    setMsg("");
  }

  async function save() {
    setBusy(true);
    setMsg("");
    try {
      const num = (k: string) => {
        const v = parseFloat((vals[k] || "0").replace(",", "."));
        return Number.isFinite(v) ? v : 0;
      };
      const r = await saveAccountFees(account, pick, {
        stock_pct: num("stock_pct"), stock_min: num("stock_min"),
        min_currency: (vals.min_currency || "PLN").toUpperCase().slice(0, 3),
        free_turnover_eur: num("free_turnover_eur"), fx_pct: num("fx_pct"),
        spread_pct: num("spread_pct"), label: vals.label,
      });
      if (r?.ok) { setMsg("Zapisano"); onSaved(); }
      else setMsg(r?.error || "Nie udało się zapisać");
    } catch (e: any) {
      setMsg(e?.message || "Błąd zapisu");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Card style={{ marginBottom: 9, padding: 0 }}>
      <Press style={s.head} onPress={onToggle} scaleTo={0.99}>
        <View style={{ flex: 1 }}>
          <Text style={s.acct}>{account}</Text>
          <Text style={s.acctMeta}>
            {profile.label}
            {profile.custom ? " · własne stawki" : profile.verified ? " · stawki potwierdzone" : " · stawki domyślne"}
          </Text>
        </View>
        <View style={s.badge}><Text style={s.badgeTxt}>{currency}</Text></View>
        <Text style={s.chev}>{expanded ? "▾" : "▸"}</Text>
      </Press>

      {expanded && (
        <View style={s.body}>
          <Text style={s.label}>Broker</Text>
          <View style={s.chips}>
            {catalog.map((c) => (
              <MetalButton key={c.id} label={c.label} size="sm" tone="green" round
                           active={pick === c.id} onPress={() => choose(c.id)} />
            ))}
          </View>

          {!!catalog.find((c) => c.id === pick)?.note && (
            <Text style={s.hint}>{catalog.find((c) => c.id === pick)!.note}</Text>
          )}
          {catalog.find((c) => c.id === pick)?.verified === false && (
            <Text style={[s.hint, { color: C.amber }]}>
              To wartości domyślne — sprawdź je w tabeli opłat brokera i popraw poniżej.
            </Text>
          )}

          {pick === "OTHER" && (
            <>
              <Text style={s.label}>Nazwa brokera</Text>
              <TextInput
                style={s.input} value={vals.label} placeholderTextColor={C.dim}
                placeholder="np. Dom Maklerski XYZ"
                onChangeText={(t) => setVals({ ...vals, label: t })}
              />
            </>
          )}

          {FIELDS.map((f) => (
            <View key={f.key as string}>
              <Text style={s.label}>{f.label}</Text>
              <View style={s.inputRow}>
                <TextInput
                  style={[s.input, { flex: 1 }]}
                  value={vals[f.key as string]}
                  keyboardType="decimal-pad"
                  placeholderTextColor={C.dim}
                  onChangeText={(t) => setVals({ ...vals, [f.key as string]: t })}
                />
                <Text style={s.suffix}>
                  {f.key === "stock_min" ? vals.min_currency : f.suffix}
                </Text>
              </View>
              <Text style={s.hint}>{f.hint}</Text>
            </View>
          ))}

          <Text style={s.label}>Waluta minimalnej prowizji</Text>
          <TextInput
            style={s.input} value={vals.min_currency} autoCapitalize="characters" maxLength={3}
            onChangeText={(t) => setVals({ ...vals, min_currency: t })}
          />

          <LiquidButton label={busy ? "Zapisuję…" : "Zapisz stawki"} disabled={busy}
                        onPress={save} style={{ marginTop: 18 }} />
          {!!msg && <Text style={s.msg}>{msg}</Text>}
        </View>
      )}
    </Card>
  );
}

const s = StyleSheet.create({
  card: { paddingHorizontal: 16, paddingVertical: 4 },
  note: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 9 },

  head: { flexDirection: "row", alignItems: "center", padding: 14, gap: 10 },
  acct: { color: C.text, fontSize: 15, fontWeight: "800", letterSpacing: -0.2 },
  acctMeta: { color: C.dim, fontSize: 11.5, marginTop: 3 },
  badge: { backgroundColor: C.greenDim, borderRadius: 8, paddingHorizontal: 10, paddingVertical: 5 },
  badgeTxt: { color: C.green, fontWeight: "800", fontSize: 12 },
  chev: { color: C.muted, fontSize: 15, width: 14, textAlign: "center" },

  body: { paddingHorizontal: 14, paddingBottom: 16, gap: 2 },
  label: {
    color: C.muted, fontSize: 10.5, fontWeight: "700", letterSpacing: 0.6,
    textTransform: "uppercase", marginTop: 13, marginBottom: 6,
  },
  chips: { flexDirection: "row", flexWrap: "wrap", gap: 6 },
  chip: {
    borderWidth: 1, borderColor: C.border2, borderRadius: 999,
    paddingHorizontal: 11, paddingVertical: 6,
  },
  chipOn: { backgroundColor: C.greenDim, borderColor: "rgba(47,212,138,.45)" },
  chipTxt: { color: C.muted, fontSize: 11.5, fontWeight: "700" },
  chipTxtOn: { color: C.green },

  inputRow: { flexDirection: "row", alignItems: "center", gap: 8 },
  input: {
    backgroundColor: C.bg, borderColor: C.border2, borderWidth: 1, borderRadius: 11,
    paddingHorizontal: 12, paddingVertical: 10, color: C.text, fontSize: 15,
  },
  suffix: { color: C.muted, fontSize: 12.5, fontWeight: "700", width: 38 },
  hint: { color: C.dim, fontSize: 11, marginTop: 4, lineHeight: 16 },

  save: {
    backgroundColor: C.green, borderRadius: 12, paddingVertical: 13,
    alignItems: "center", marginTop: 18,
  },
  saveTxt: { color: "#04140c", fontWeight: "800", fontSize: 14.5 },
  msg: { color: C.muted, fontSize: 12.5, textAlign: "center", marginTop: 9 },

  dim: { color: C.muted, ...T.small },
});
