/** Okno „Insajderów" zawieszone nad całą aplikacją.
 *
 *  Mieszka w powłoce (`App.tsx` → `AccountLayer`), a nie w zakładce Narzędzia,
 *  bo otwiera się z trzech miejsc: karta w Narzędziach, twarz na wykresie
 *  spółki (konto bez premium) i powiadomienie o transakcji obserwowanej osoby.
 *
 *  Okno sprzedaży i logowania też są na samej górze — i na iPhonie otwarte
 *  obok tego okna po prostu by się nie pokazały (zasłania je). Dlatego gdy
 *  któreś z nich jest proszone, panel chowa się na chwilę, a po ich zamknięciu
 *  wraca w to samo miejsce. Kto właśnie kupił premium, wraca prosto do
 *  odblokowanego panelu.
 */
import React, { useEffect, useRef, useState } from "react";
import { Platform } from "react-native";
import { useAuth } from "../../../auth/AuthContext";
import { InsidersRequest, setInsidersOpener } from "../../../insiderRouter";
import InsidersModal from "./index";

/** Adres, pod którym panel otwiera się na stronie: portevo.pl/insajderzy */
export const SCIEZKA_WEB = "/insajderzy";

export default function InsidersLayer() {
  const { paywall, loginOpen } = useAuth();
  const [open, setOpen] = useState(false);
  const [person, setPerson] = useState<string | null>(null);
  const schowany = useRef(false);

  useEffect(() => {
    setInsidersOpener((req?: InsidersRequest) => {
      setPerson(req?.person || null);
      setOpen(true);
    });
    // wejście wprost na adres narzędzia — tylko w przeglądarce
    if (Platform.OS === "web") {
      try {
        if (window.location.pathname.replace(/\/+$/, "") === SCIEZKA_WEB) {
          // „/insajderzy?osoba=nancy-pelosi" z podstrony pozycjonowanej — od razu profil
          const osoba = new URLSearchParams(window.location.search).get("osoba");
          if (osoba && /^[a-z0-9-]{2,80}$/.test(osoba)) setPerson(osoba);
          setOpen(true);
        }
      } catch { /* bez dostępu do adresu nic nie otwieramy */ }
    }
    return () => setInsidersOpener(null);
  }, []);

  useEffect(() => {
    const zasloniete = paywall !== null || loginOpen;
    if (zasloniete && open) {
      schowany.current = true;
      setOpen(false);
    } else if (!zasloniete && schowany.current) {
      schowany.current = false;
      // chwila na zjazd okna sprzedaży — na iPhonie dwa okna naraz w ruchu
      // potrafią zgubić to drugie
      setTimeout(() => setOpen(true), 380);
    }
  }, [paywall, loginOpen]);

  return (
    <InsidersModal visible={open} startPerson={person}
                   onClose={() => { schowany.current = false; setOpen(false); setPerson(null); }} />
  );
}
