type AiStan = {
  loading: boolean; text: string | null; at?: number; againIn?: number;
  asking?: boolean; note?: string;
};

function zOdpowiedzi(r: PodsumowanieAI): AiStan {
  return { loading: false, text: r.text, at: r.at, againIn: r.again_in, asking: false };
}

function temuOd(at: number): string {
  const min = Math.max(0, Math.round((Date.now() / 1000 - at) / 60));
  if (min < 1) return "przed chwilą";
  if (min < 60) return `${min} min temu`;
  const h = Math.round(min / 60);
  return `${h} ${plural(h, "godzinę", "godziny", "godzin")} temu`;
}
