/** Sesje na żywo — transkrypcja i to, co model z niej wyłapał.
 *
 *  Dane dociągamy kursorami (`transcript_after` / `analyses_after`), więc co
 *  trzy sekundy lecą przez sieć wyłącznie NOWE zdania, a nie cała historia
 *  wystąpienia. Przy dwugodzinnej konferencji to różnica między kilobajtem
 *  a megabajtami na każde odpytanie.
 */
import React, { useCallback, useEffect, useRef, useState } from "react";
import { ScrollView, StyleSheet, Text, View } from "react-native";
import { getLiveSession, liveSessionStop, LiveState } from "../../../api";
import { C, T } from "../../../theme";
import { Card, FadeIn, MetalButton, Press } from "../../../ui";

/** Etapy przechwytywania, tak jak raportuje je komputer. */
const STAGE: Record<string, string> = {
  starting: "startuję", resolving_url: "szukam streamu",
  loading_whisper: "ładuję rozpoznawanie mowy", capturing: "nagrywam",
  ended: "zakończone", error: "błąd", idle: "bezczynna",
};

type Cursor = { t: number; a: number };

export default function SessionsTab({
  st, busy, act,
}: {
  st: LiveState; busy: string;
  act: (label: string, fn: () => Promise<any>) => Promise<any>;
}) {
  const sessions = st.sessions || [];
  const [data, setData] = useState<Record<string, {
    transcript: { t: string; text: string }[]; analyses: any[];
  }>>({});
  const cursors = useRef<Record<string, Cursor>>({});
  const [expanded, setExpanded] = useState<string | null>(null);

  const poll = useCallback(async () => {
    for (const sess of sessions) {
      const cur = cursors.current[sess.id] || { t: 0, a: 0 };
      // nic nowego — nie zawracamy głowy serwerowi
      if (sess.transcript_len === cur.t && sess.analyses_len === cur.a) continue;
      try {
        const d = await getLiveSession(sess.id, cur.t, cur.a);
        if ((d as any).error) continue;
        setData((prev) => {
          const old = prev[sess.id] || { transcript: [], analyses: [] };
          return {
            ...prev,
            [sess.id]: {
              transcript: [...old.transcript, ...(d.transcript || [])].slice(-600),
              analyses: [...(d.analyses || []).slice().reverse(), ...old.analyses].slice(0, 80),
            },
          };
        });
        cursors.current[sess.id] = { t: d.transcript_len, a: d.analyses_len };
      } catch { /* jedna nieudana próba nie psuje pętli */ }
    }
  }, [sessions]);

  useEffect(() => { poll(); }, [poll]);
  useEffect(() => {
    const t = setInterval(poll, 3000);
    return () => clearInterval(t);
  }, [poll]);

  if (sessions.length === 0) {
    return (
      <Card style={s.empty}>
        <Text style={s.emptyTitle}>Nic teraz nie leci</Text>
        <Text style={s.emptyTxt}>
          Wejdź w Kalendarz i kliknij „▶ Słuchaj" przy wydarzeniu, albo włącz dozór
          w Ustawieniach — wtedy śledzone wydarzenia wystartują same, gdy wejdą na antenę.
        </Text>
      </Card>
    );
  }

  return (
    <View>
      {sessions.map((sess, i) => {
        const cap = sess.capture || {};
        const stage = STAGE[cap.stage] || cap.stage || "—";
        const secs = Math.round(Number(cap.seconds_captured) || 0);
        const d = data[sess.id] || { transcript: [], analyses: [] };
        const open = expanded === sess.id || sessions.length === 1;

        return (
          <FadeIn key={sess.id} delay={Math.min(i * 30, 200)} offset={8}>
            <Card style={s.card}>
              <View style={s.head}>
                {sess.running && <View style={s.recDot} />}
                <Text style={s.title} numberOfLines={2}>
                  {sess.event?.title || sess.id}
                </Text>
              </View>

              <View style={s.metaRow}>
                <Text style={[s.stage, cap.stage === "error" && { color: C.red }]}>{stage}</Text>
                <Text style={s.meta}>
                  {secs > 0 ? `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, "0")} audio` : "—"}
                  {`  ·  ${sess.transcript_len} fragm.  ·  ${sess.analyses_len} analiz`}
                </Text>
              </View>
              {!!cap.error && <Text style={s.err} numberOfLines={2}>{cap.error}</Text>}

              <View style={s.btns}>
                <MetalButton size="sm" tone="red"
                             label={busy === sess.id ? "…" : "■ Zatrzymaj"}
                             onPress={() => act(sess.id, () => liveSessionStop(sess.id))} />
                {sessions.length > 1 && (
                  <MetalButton size="sm" label={open ? "Zwiń" : "Rozwiń"}
                               onPress={() => setExpanded(open ? null : sess.id)} />
                )}
              </View>

              {open && (
                <>
                  <Text style={s.section}>Co model wyłapał</Text>
                  {d.analyses.length === 0 ? (
                    <Text style={s.dim}>Jeszcze nic — model analizuje co kilkanaście sekund.</Text>
                  ) : (
                    d.analyses.slice(0, 25).map((a, k) => {
                      const hit = a.signal_detected;
                      const conf = Number(a.confidence) || 0;
                      const strong = conf >= Number(st.params?.live_confidence_threshold ?? 0.85);
                      return (
                        <View key={k} style={[s.an, hit && (strong ? s.anStrong : s.anWeak)]}>
                          <View style={s.anMeta}>
                            <Text style={s.anTs}>{a.ts || ""}</Text>
                            {!!a.event_type && <Text style={s.anType}>{a.event_type}</Text>}
                            {hit && (
                              <Text style={[s.anConf, { color: strong ? C.green : C.amber }]}>
                                {a.ticker || "—"} · {Math.round(conf * 100)}%
                              </Text>
                            )}
                          </View>
                          <Text style={hit ? s.anText : s.dim}>
                            {a.reasoning || a.context_note || "analizuję…"}
                          </Text>
                          {!!a.quote && <Text style={s.quote}>„{a.quote}"</Text>}
                        </View>
                      );
                    })
                  )}

                  <Text style={s.section}>Transkrypcja</Text>
                  <ScrollView style={s.transcript} nestedScrollEnabled
                              showsVerticalScrollIndicator={false}>
                    {d.transcript.length === 0 ? (
                      <Text style={s.dim}>
                        {sess.running ? "Czekam na pierwszy fragment dźwięku…" : "Brak zapisu."}
                      </Text>
                    ) : (
                      d.transcript.slice().reverse().map((c, k) => (
                        <View key={k} style={s.line}>
                          <Text style={s.lineT}>{c.t}</Text>
                          <Text style={s.lineTxt}>{c.text}</Text>
                        </View>
                      ))
                    )}
                  </ScrollView>
                  <Text style={s.dimSmall}>
                    Najnowsze na górze. Tekst rozpoznaje komputer — literówki w nazwiskach
                    i tickerach są normalne.
                  </Text>
                </>
              )}
            </Card>
          </FadeIn>
        );
      })}
    </View>
  );
}

const s = StyleSheet.create({
  card: { padding: 14, marginBottom: 12 },
  head: { flexDirection: "row", alignItems: "center", gap: 8 },
  recDot: { width: 8, height: 8, borderRadius: 4, backgroundColor: C.red },
  title: { color: C.text, fontSize: 14, fontWeight: "800", flex: 1, lineHeight: 19 },

  metaRow: { flexDirection: "row", alignItems: "center", gap: 8, marginTop: 8 },
  stage: { color: C.green, fontSize: 11.5, fontWeight: "700" },
  meta: { color: C.dim, fontSize: 10.5, marginLeft: "auto" },
  err: { color: C.red, fontSize: 11, marginTop: 6, lineHeight: 15 },
  btns: { flexDirection: "row", gap: 8, marginTop: 12 },

  section: {
    color: C.muted, ...T.micro, textTransform: "uppercase",
    marginTop: 18, marginBottom: 8,
  },
  dim: { color: C.dim, fontSize: 12, lineHeight: 17 },
  dimSmall: { color: C.dim, fontSize: 10, lineHeight: 14, marginTop: 8 },

  an: {
    padding: 10, borderRadius: 11, marginBottom: 7,
    backgroundColor: C.elev, borderLeftWidth: 3, borderLeftColor: "transparent",
  },
  anStrong: { borderLeftColor: C.green },
  anWeak: { borderLeftColor: C.amber },
  anMeta: { flexDirection: "row", alignItems: "center", gap: 8, marginBottom: 5 },
  anTs: { color: C.dim, fontSize: 10 },
  anType: { color: C.muted, fontSize: 10 },
  anConf: { fontSize: 11, fontWeight: "800", marginLeft: "auto" },
  anText: { color: C.text, fontSize: 12.5, lineHeight: 18 },
  quote: { color: C.muted, fontSize: 11.5, lineHeight: 17, marginTop: 6, fontStyle: "italic" },

  transcript: {
    maxHeight: 320, backgroundColor: C.elev, borderRadius: 12, padding: 11,
  },
  line: { flexDirection: "row", gap: 9, paddingVertical: 4 },
  lineT: { color: C.dim, fontSize: 10, width: 54 },
  lineTxt: { color: C.muted, fontSize: 12, lineHeight: 17, flex: 1 },

  empty: { padding: 22 },
  emptyTitle: { color: C.text, fontSize: 14, fontWeight: "800", marginBottom: 8 },
  emptyTxt: { color: C.muted, fontSize: 12.5, lineHeight: 18.5 },
});
