/** Panel „Insajderzy" — kogo śledzić, kto się liczy i co właśnie ujawniono.
 *
 *  Układ odpowiada trzem pytaniom, z którymi się tu wchodzi:
 *  1. **Kogo w ogóle śledzę?** — klasy (politycy, prezydent, prezesi…), na starcie
 *     wszystkie włączone. Wybór obowiązuje też na wykresach spółek.
 *  2. **Kto jest ważny i komu wychodzi?** — ranking person: pierwsza trójka
 *     w medalowych ramkach, przy każdej wynik zakupów z 12 miesięcy.
 *  3. **Co nowego?** — zgłoszenia z ostatnich tygodni, od najświeższego ujawnienia.
 *
 *  Bez premium panel jest CAŁY widoczny — to wizytówka narzędzia — ale każde
 *  dotknięcie prowadzi do strony sprzedażowej. Okno samo się wtedy zamyka
 *  i otwiera ponownie po zamknięciu paywalla (patrz `Layer.tsx`), bo na
 *  iPhonie okno sprzedaży otwarte POD tym oknem byłoby niewidoczne.
 *
 *  Profil persony i karta spółki otwierają się jako okna WEWNĄTRZ tego okna —
 *  z tego samego powodu.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator, Animated, Easing, Modal, Platform, Pressable, SafeAreaView, ScrollView,
  StatusBar, StyleSheet, Text, View,
} from "react-native";
import {
  getPanelInsiderow, obserwujInsidera, panelInsiderowZPamieci, PanelInsiderow, PersonaInsidera,
  PremiumRequired, TransakcjaInsidera,
} from "../../../api";
import { useAuth } from "../../../auth/AuthContext";
import { useLayout } from "../../../layout";
import { C, plural, T } from "../../../theme";
import { Card, ErrorBoundary, FadeIn, MetalButton, Press, Segmented } from "../../../ui";
import Icon from "../../../ui/Icon";
import * as powiadomienia from "../../../notifications";
import CompanyScreen from "../../CompanyScreen";
import Profile from "./Profile";
import {
  Avatar, dzien, FEATURE, ileTemu, KLASY_IKONY, kwota, opis, procent, Przelacznik,
  kasa, ramkaMiejsca, useInsiderPrefs, WEJSCIE, WSZYSTKIE_KLASY,
} from "./shared";

const SORTY = [
  { id: "waga", label: "Najważniejsi" },
  { id: "wynik", label: "Wynik 12M" },
  { id: "aktywni", label: "Aktywni" },
  { id: "zakupy", label: "Zakupy" },
];

export default function InsidersModal({
  visible, onClose, startPerson,
}: {
  visible: boolean;
  onClose: () => void;
  /** profil do otwarcia od razu (np. z powiadomienia) */
  startPerson?: string | null;
}) {
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}
           transparent={false} presentationStyle="fullScreen">
      <SafeAreaView style={[s.root,
                            Platform.OS === "android" && { paddingTop: StatusBar.currentHeight || 0 }]}>
        <View style={s.head}>
          <View style={s.headIcon}>
            <Icon name="insajder" size={21} color={C.green} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={s.headTitle} numberOfLines={1}>Insajderzy</Text>
            <Text style={s.headSub} numberOfLines={1}>Narzędzia · Portevo</Text>
          </View>
          <Pressable onPress={onClose} hitSlop={12} style={s.close}
                     accessibilityRole="button" accessibilityLabel="Zamknij insajderów">
            <Icon name="zamknij" size={17} color={C.muted} />
          </Pressable>
        </View>
        <ErrorBoundary name="Insajderzy">
          {visible && <Panel startPerson={startPerson} />}
        </ErrorBoundary>
      </SafeAreaView>
    </Modal>
  );
}

function Panel({ startPerson }: { startPerson?: string | null }) {
  const { wide } = useLayout();
  const { locked, showPaywall, previewOnly, openLogin } = useAuth();
  const zablokowane = locked(FEATURE);
  const prefs = useInsiderPrefs();
  const [data, setData] = useState<PanelInsiderow | null>(null);
  const [err, setErr] = useState("");
  const [sort, setSort] = useState("waga");
  const [ile, setIle] = useState(12);
  const [ileFeed, setIleFeed] = useState(18);
  const [profil, setProfil] = useState<string | null>(null);
  const [spolka, setSpolka] = useState<string | null>(null);
  const zadanie = useRef(0);

  const wczytaj = useCallback(() => {
    const nr = ++zadanie.current;
    setErr("");
    getPanelInsiderow()
      .then((d) => { if (nr === zadanie.current) setData(d); })
      .catch((e) => { if (nr === zadanie.current) setErr(e?.message || "Nie udało się pobrać danych"); });
  }, []);

  useEffect(() => {
    // ostatnia wersja z urządzenia od razu, świeża z serwera zaraz po niej
    // (gdy serwer zdążył pierwszy, zostaje jego wersja)
    panelInsiderowZPamieci().then((d) => { if (d) setData((teraz) => teraz ?? d); });
    wczytaj();
  }, [wczytaj]);
  useEffect(() => {
    if (startPerson && !zablokowane) setProfil(startPerson);
  }, [startPerson]);

  const [followBusy, setFollowBusy] = useState<string | null>(null);
  const odswiez = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (odswiez.current) clearTimeout(odswiez.current); }, []);

  /** Zapisuje zmianę obserwowania w danych panelu — natychmiast, bez pytania
   *  serwera. Wołają to i dzwonek w wierszu, i profil osoby: bez tego lista
   *  „Obserwujesz" odświeżała się dopiero po zamknięciu i otwarciu narzędzia. */
  const zapiszObserwowanie = useCallback((pid: string, on: boolean, persona?: PersonaInsidera) => {
    setData((d) => d && ({
      ...d,
      follows: on ? [...d.follows.filter((x) => x !== pid), pid] : d.follows.filter((x) => x !== pid),
      // osoba obserwowana z karty spółki może nie być w rankingu — bez tego
      // wiersz „Obserwujesz" nie miałby czego pokazać
      persons: persona && !d.persons[pid] ? { ...d.persons, [pid]: persona } : d.persons,
    }));
    // ...i dla pewności ściągamy stan z serwera (to on jest prawdą — ta sama
    // lista może się zmienić na drugim urządzeniu). Z opóźnieniem, żeby seria
    // szybkich dotknięć dzwonka nie wysłała serii zapytań.
    if (odswiez.current) clearTimeout(odswiez.current);
    odswiez.current = setTimeout(() => {
      getPanelInsiderow()
        .then((d) => setData((teraz) => (teraz ? { ...d } : d)))
        .catch(() => {});
    }, 900) as unknown as ReturnType<typeof setTimeout>;
  }, []);

  /** Dzwonek w wierszu rankingu: obserwowanie bez wchodzenia w profil. Zmiana
   *  od razu na ekranie, a przy błędzie wraca do stanu sprzed dotknięcia. */
  const przelaczObserwowanie = useCallback(async (pid: string) => {
    if (zablokowane) { showPaywall(FEATURE); return; }
    if (!data || followBusy) return;
    if (!data.logged_in) { openLogin(); return; }
    const nowy = !data.follows.includes(pid);
    zapiszObserwowanie(pid, nowy);
    setFollowBusy(pid);
    try {
      await obserwujInsidera(pid, nowy);
      // obserwowanie to prośba o powiadomienia — pierwszy raz pytamy tu o zgodę
      if (nowy && powiadomienia.obslugiwane) {
        const zgoda = await powiadomienia.stanZgody().catch(() => "nie");
        if (zgoda === "nie-pytano") powiadomienia.wlacz().catch(() => {});
      }
    } catch (e: any) {
      zapiszObserwowanie(pid, !nowy);
      if (e instanceof PremiumRequired) showPaywall(FEATURE);
    } finally { setFollowBusy(null); }
  }, [zablokowane, data, followBusy, openLogin, showPaywall, zapiszObserwowanie]);

  /** Każda interakcja bez premium kończy się tu. */
  const bramka = useCallback((akcja: () => void) => {
    if (zablokowane) { showPaywall(FEATURE); return; }
    akcja();
  }, [zablokowane, showPaywall]);

  const liderzy = useMemo(() => {
    if (!data) return [];
    const wKlasach = data.leaders.filter((p) => prefs.cats.includes(p.cat));
    const akt = (p: PersonaInsidera) => (p.activity?.buys || 0) + (p.activity?.sells || 0);
    const kopia = [...wKlasach];
    if (sort === "wynik") {
      kopia.sort((a, b) => (b.stats?.ret_12m ?? -1e9) - (a.stats?.ret_12m ?? -1e9));
    } else if (sort === "aktywni") {
      kopia.sort((a, b) => akt(b) - akt(a));
    } else if (sort === "zakupy") {
      // złotówki GPW z grubsza na dolary — inaczej polski prezes wygrywałby
      // z Buffettem samą walutą
      const wUsd = (p: PersonaInsidera) => (p.activity?.bought || 0) / (p.cur === "PLN" ? 3.7 : 1);
      kopia.sort((a, b) => wUsd(b) - wUsd(a));
    } else {
      // Kolejność ważności, ale osoby bez żadnej transakcji w roku schodzą na
      // koniec — pusty wiersz „—" na szóstym miejscu tylko zabiera miejsce.
      kopia.sort((a, b) => Number(!akt(a)) - Number(!akt(b))
        || (a.rank || 9999) - (b.rank || 9999) || akt(b) - akt(a));
    }
    return kopia;
  }, [data, prefs.cats, sort]);

  const feed = useMemo(() => {
    if (!data) return [];
    return data.feed.filter((t) => prefs.cats.includes(data.persons[t.person]?.cat || ""));
  }, [data, prefs.cats]);

  const obserwowani = useMemo(() => {
    if (!data?.follows?.length) return [];
    const wszyscy: Record<string, PersonaInsidera> = { ...data.persons };
    for (const p of data.leaders) wszyscy[p.id] = p;
    return data.follows.map((id) => wszyscy[id]).filter(Boolean) as PersonaInsidera[];
  }, [data]);

  if (err && !data) {
    return (
      <View style={s.center}>
        <Text style={s.errTitle}>{err}</Text>
        <MetalButton label="Spróbuj ponownie" tone="green" onPress={wczytaj} style={{ marginTop: 14 }} />
      </View>
    );
  }
  if (!data) return <Szkielet />;

  const kolumnaLewa = (
    <>
      <FadeIn delay={120}>
        <View style={s.sectionHead}>
          <Text style={s.sectionTitle}>Najważniejsze persony</Text>
          <Text style={s.sectionHint}>{liderzy.length} w wybranych klasach</Text>
        </View>
        <Segmented options={SORTY} value={sort} liquid tone="green"
                   onChange={(x) => bramka(() => { setSort(x); setIle(12); })} />
      </FadeIn>

      {!data.ready ? (
        <Card style={{ marginTop: 12 }}>
          <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
            <ActivityIndicator color={C.green} />
            <Text style={s.dim}>Zbieramy zgłoszenia z rejestrów — pierwsze wypełnienie trwa kilka minut.</Text>
          </View>
        </Card>
      ) : liderzy.length === 0 ? (
        <Card style={{ marginTop: 12 }}>
          <Text style={s.dim}>Żadna z zaznaczonych klas nie ma jeszcze person. Włącz więcej klas powyżej.</Text>
        </Card>
      ) : (
        <View style={{ marginTop: 12, gap: 8 }}>
          {liderzy.slice(0, ile).map((p, i) => (
            <FadeIn key={`${sort}-${p.id}`} delay={Math.min(i, 10) * 45} offset={10}>
              <Lider p={p} i={i} obserwowany={data.follows.includes(p.id)} zablokowany={zablokowane}
                     onPress={() => bramka(() => setProfil(p.id))}
                     busy={followBusy === p.id} onFollow={() => przelaczObserwowanie(p.id)} />
            </FadeIn>
          ))}
          {liderzy.length > ile && (
            <MetalButton label={`Pokaż więcej (${liderzy.length - ile})`} full
                         onPress={() => bramka(() => setIle((x) => x + 15))} />
          )}
        </View>
      )}
    </>
  );

  const kolumnaPrawa = (
    <>
      {obserwowani.length > 0 && (
        <FadeIn delay={140}>
          <View style={s.sectionHead}>
            <Text style={s.sectionTitle}>Obserwujesz</Text>
            <Text style={s.sectionHint}>powiadomimy o każdej ich transakcji</Text>
          </View>
          <ScrollView horizontal showsHorizontalScrollIndicator={false}
                      contentContainerStyle={{ gap: 14, paddingVertical: 4, paddingRight: 8 }}>
            {obserwowani.map((p) => (
              <Press key={p.id} onPress={() => bramka(() => setProfil(p.id))} style={s.followItem}>
                <Avatar person={p} size={54} ring="follow" />
                <Text style={s.followName} numberOfLines={1}>{p.name}</Text>
              </Press>
            ))}
          </ScrollView>
        </FadeIn>
      )}

      <FadeIn delay={160}>
        <View style={s.sectionHead}>
          <Text style={s.sectionTitle}>Świeżo ujawnione</Text>
          <Text style={s.sectionHint}>od najnowszego zgłoszenia</Text>
        </View>
        {feed.length === 0 ? (
          <Card><Text style={s.dim}>W wybranych klasach nie ma świeżych zgłoszeń.</Text></Card>
        ) : (
          <Card padded={false} style={{ paddingHorizontal: 12, paddingVertical: 2 }}>
            {feed.slice(0, ileFeed).map((t, i, arr) => (
              <Zgloszenie key={t.uid} t={t} p={data.persons[t.person]} last={i === arr.length - 1}
                          onPress={() => bramka(() => setSpolka(t.ticker))}
                          onPerson={() => bramka(() => setProfil(t.person))} />
            ))}
          </Card>
        )}
        {feed.length > ileFeed && (
          <MetalButton label={`Starsze zgłoszenia (${feed.length - ileFeed})`} full
                       style={{ marginTop: 8 }}
                       onPress={() => bramka(() => setIleFeed((x) => x + 25))} />
        )}
      </FadeIn>
    </>
  );

  return (
    <>
      <ScrollView contentContainerStyle={s.body} showsVerticalScrollIndicator={false}
                  keyboardShouldPersistTaps="handled">
        <View style={s.column}>
          <Naglowek data={data} />

          {zablokowane && (
            <FadeIn delay={60}>
              <Pressable onPress={() => showPaywall(FEATURE)} style={s.lockCard}>
                <View style={s.lockIcon}><Icon name="klodka" size={18} color={C.amber} /></View>
                <View style={{ flex: 1 }}>
                  <Text style={s.lockTitle}>
                    {previewOnly(FEATURE) ? "Podgląd bez premium" : "Oglądasz podgląd"}
                  </Text>
                  <Text style={s.lockTxt}>
                    Ranking i świeże zgłoszenia widzisz za darmo. Profile, twarze na wykresach
                    spółek i powiadomienia o obserwowanych są w premium.
                  </Text>
                </View>
                <Text style={s.lockCta}>Odblokuj ›</Text>
              </Pressable>
            </FadeIn>
          )}

          <Klasy data={data} prefs={prefs} bramka={bramka} />

          {wide ? (
            <View style={s.twoCols}>
              <View style={{ flex: 1.15 }}>{kolumnaLewa}</View>
              <View style={{ flex: 1 }}>{kolumnaPrawa}</View>
            </View>
          ) : (
            <>
              {kolumnaLewa}
              {kolumnaPrawa}
            </>
          )}

          <Text style={s.foot}>
            Źródła: SEC — Form 4 (prezesi, rady, udziałowcy powyżej 10%) i 13F (kwartalne
            portfele funduszy, dzień = koniec kwartału); Izba Reprezentantów USA (raporty
            transakcji kongresmenów, do 45 dni po transakcji); urząd etyki OGE (prezydent
            i gabinet, przez otwarte repozytorium open-cabinet); GPW — powiadomienia MAR
            z raportów ESPI w zestawieniu Bankier.pl. Portrety kongresmenów: oficjalne zdjęcia
            Kongresu (domena publiczna). Kwoty Kongresu i OGE to przedziały z formularzy.
            To informacja, nie rekomendacja.
          </Text>
        </View>
      </ScrollView>

      <Profile personId={profil} onClose={() => setProfil(null)}
               onFollowChange={zapiszObserwowanie}
               onOpenCompany={(t) => { setProfil(null); setTimeout(() => setSpolka(t), 320); }} />
      {spolka && <CompanyScreen symbol={spolka} onClose={() => setSpolka(null)} />}
    </>
  );
}

// ---------------------------------------------------------------- nagłówek

function Naglowek({ data }: { data: PanelInsiderow }) {
  return (
    <FadeIn>
      <View style={s.hero}>
        <Text style={s.h1}>Kto z wewnątrz kupuje</Text>
        <Text style={s.sub}>
          Transakcje prezesów, Kongresu, prezydenta i rządu USA — prosto z oficjalnych
          rejestrów, na wykresach spółek i w profilach person.
        </Text>
        <View style={s.stats}>
          <Licznik value={data.sources.house + (data.sources.senat || 0)} label="transakcji Kongresu" delay={0} />
          <Licznik value={data.sources.oge} label="prezydenta i rządu" delay={100} />
          <Licznik value={data.sources.sec + (data.sources.f13 || 0)}
                   label="prezesów i funduszy z USA" delay={200} />
          <Licznik value={data.sources.gpw || 0} label="insiderów z GPW" delay={300} />
        </View>
        {!!data.updated && (
          <View style={s.updated}>
            <Puls />
            <Text style={s.updatedTxt}>Najnowsze zgłoszenie: {dzien(data.updated, true)} · {ileTemu(data.updated)}</Text>
          </View>
        )}
      </View>
    </FadeIn>
  );
}

/** Liczba, która dobiega do celu — jednorazowo, przy wejściu. */
function Licznik({ value, label, delay }: { value: number; label: string; delay: number }) {
  const a = useRef(new Animated.Value(0)).current;
  const [v, setV] = useState(0);
  useEffect(() => {
    const id = a.addListener(({ value: x }) => setV(Math.round(x)));
    Animated.timing(a, { toValue: value, duration: 1100, delay, easing: WEJSCIE,
                         useNativeDriver: false }).start();
    return () => a.removeListener(id);
  }, [value]);
  return (
    <View style={s.stat}>
      <Text style={s.statV}>{v.toLocaleString("pl-PL")}</Text>
      <Text style={s.statL}>{label}</Text>
    </View>
  );
}

function Puls() {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    // trzy uderzenia i koniec — sygnał „to jest na żywo", nie wieczne mruganie
    Animated.loop(Animated.timing(a, { toValue: 1, duration: 1300, easing: Easing.out(Easing.quad),
                                       useNativeDriver: true }), { iterations: 3 }).start();
  }, []);
  return (
    <View style={{ width: 10, height: 10, alignItems: "center", justifyContent: "center" }}>
      <Animated.View style={[s.pulseRing, {
        opacity: a.interpolate({ inputRange: [0, 1], outputRange: [0.6, 0] }),
        transform: [{ scale: a.interpolate({ inputRange: [0, 1], outputRange: [0.6, 2.2] }) }],
      }]} />
      <View style={s.pulseDot} />
    </View>
  );
}

// ------------------------------------------------------------------- klasy

function Klasy({ data, prefs, bramka }: {
  data: PanelInsiderow; prefs: ReturnType<typeof useInsiderPrefs>;
  bramka: (f: () => void) => void;
}) {
  const { wide } = useLayout();
  const wszystkie = WSZYSTKIE_KLASY.every((k) => prefs.cats.includes(k));
  return (
    <FadeIn delay={90}>
      <View style={s.sectionHead}>
        <Text style={s.sectionTitle}>Kogo śledzisz</Text>
        <Pressable hitSlop={8} onPress={() => bramka(() => prefs.setAll(!wszystkie))}>
          <Text style={s.link}>{wszystkie ? "Odznacz wszystkie" : "Zaznacz wszystkie"}</Text>
        </Pressable>
      </View>
      <View style={s.chipsWrap}>
        {data.klasy.map((k) => {
          const on = prefs.cats.includes(k.id);
          // Szerokość dostaje komórka siatki, a nie sam przycisk: `Press` owija
          // treść w dodatkowy widok, więc rozmiar podany mu wprost rozciągał
          // kafelek w pionie zamiast układać go w rzędzie.
          return (
            <View key={k.id} style={[s.klasaSlot, { flexBasis: wide ? "22%" : "46%" }]}>
            <Press scaleTo={0.94} onPress={() => bramka(() => prefs.toggleCat(k.id))}
                   style={[s.klasa, on && s.klasaOn]}>
              <View style={[s.klasaIcon, on && s.klasaIconOn]}>
                <Icon name={KLASY_IKONY[k.id] || "insajder"} size={17} color={on ? C.green : C.dim} />
              </View>
              <View style={{ flexShrink: 1 }}>
                <Text style={[s.klasaTxt, on && { color: C.text }]} numberOfLines={2}>{k.label}</Text>
                <Text style={s.klasaCount}>{k.count ? `${k.count} w rankingu` : k.short}</Text>
              </View>
              <View style={[s.check, on && s.checkOn]}>
                {on && <Icon name="ptaszek" size={11} color="#06130c" />}
              </View>
            </Press>
            </View>
          );
        })}
      </View>
      <View style={s.toggles}>
        <Przelacznik on={prefs.chart} label="Twarze na wykresach spółek"
                     sub="w miejscu, w którym ktoś kupił"
                     onPress={() => bramka(() => prefs.setChart(!prefs.chart))} />
        <Przelacznik on={prefs.sells} label="Pokazuj też sprzedaże"
                     sub="prezesi sprzedają często — domyślnie tylko zakupy"
                     onPress={() => bramka(() => prefs.setSells(!prefs.sells))} />
      </View>
    </FadeIn>
  );
}

// ------------------------------------------------------------------ ranking

function Lider({ p, i, obserwowany, zablokowany, onPress, onFollow, busy }: {
  p: PersonaInsidera; i: number; obserwowany: boolean; zablokowany: boolean; onPress: () => void;
  onFollow: () => void; busy?: boolean;
}) {
  const ring = ramkaMiejsca(i);
  const wynik = p.stats?.ret_12m;
  const akt = (p.activity?.buys || 0) + (p.activity?.sells || 0);
  const medal = i < 3;
  return (
    <Press onPress={onPress} scaleTo={0.985}
           style={[s.lider, medal && s.liderMedal, i === 0 && s.liderGold]}>
      <Text style={[s.miejsce, medal && { color: i === 0 ? C.gold : i === 1 ? "#dfe4ee" : "#e7a36b" }]}>
        {i + 1}
      </Text>
      <View>
        <Avatar person={p} size={50} ring={ring} />
        {obserwowany && (
          <View style={s.bell}><Icon name="dzwonek" size={10} color="#fff" /></View>
        )}
      </View>
      <View style={{ flex: 1, minWidth: 0 }}>
        <Text style={s.liderName} numberOfLines={1}>{p.name}</Text>
        <Text style={s.liderRole} numberOfLines={1}>{opis(p, true) || " "}</Text>
        <View style={s.liderMeta}>
          <Icon name={KLASY_IKONY[p.cat] || "insajder"} size={11} color={C.dim} />
          <Text style={s.liderMetaTxt} numberOfLines={1}>
            {akt ? `${akt.toLocaleString("pl-PL")} ${plural(akt, "transakcja", "transakcje", "transakcji")} w roku`
                 : "bez transakcji w roku"}
            {p.activity?.last ? ` · ostatnia ${ileTemu(p.activity.last)}` : ""}
          </Text>
        </View>
      </View>
      <View style={{ alignItems: "flex-end", minWidth: 74 }}>
        {wynik != null ? (
          <>
            <View style={[s.ret, { backgroundColor: wynik >= 0 ? C.greenDim : C.redDim }]}>
              <Text style={[s.retTxt, { color: wynik >= 0 ? C.green : C.red }]}>{procent(wynik)}</Text>
            </View>
            <Text style={s.retSub}>zakupy · 12M</Text>
          </>
        ) : p.activity?.bought ? (
          <>
            <Text style={s.boughtTxt}>≈ {kasa(p.activity.bought, p.cur)}</Text>
            <Text style={s.retSub}>kupione w roku</Text>
          </>
        ) : p.activity?.sold ? (
          // Musk, Bezos, Huang: w roku same sprzedaże — wyniku zakupów nie ma
          // z czego policzyć, ale skala sprzedaży to też informacja
          <>
            <Text style={[s.boughtTxt, { color: C.red }]}>≈ {kasa(p.activity.sold, p.cur)}</Text>
            <Text style={s.retSub}>sprzedane w roku</Text>
          </>
        ) : (
          <Text style={s.retSub}>—</Text>
        )}
      </View>
      <Pressable onPress={onFollow} hitSlop={8} disabled={busy}
                 style={({ pressed }) => [s.follow, obserwowany && s.followOn,
                                          (pressed || busy) && { opacity: 0.6 }]}
                 accessibilityRole="button"
                 accessibilityLabel={obserwowany ? `Przestań obserwować: ${p.name}` : `Obserwuj: ${p.name}`}>
        <Icon name="dzwonek" size={17} color={obserwowany ? "#06120c" : C.green} />
        {/* bez premium kłódka siedzi na dzwonku — to on prowadzi do zakupu */}
        {zablokowany && <View style={s.lockDot}><Icon name="klodka" size={9} color={C.amber} /></View>}
      </Pressable>
    </Press>
  );
}

// ---------------------------------------------------------------- zgłoszenia

function Zgloszenie({ t, p, last, onPress, onPerson }: {
  t: TransakcjaInsidera; p?: PersonaInsidera; last: boolean;
  onPress: () => void; onPerson: () => void;
}) {
  const kupno = t.side === "buy";
  const szczegol = [t.options ? "opcje" : "", t.owner].filter(Boolean).join(" · ");
  return (
    <Press onPress={onPress} scaleTo={0.99} style={[s.zgl, last && { borderBottomWidth: 0 }]}>
      <Pressable onPress={onPerson} hitSlop={6}>
        <Avatar person={p} size={40} ring={kupno ? "buy" : "sell"} />
      </Pressable>
      <View style={{ flex: 1, minWidth: 0, marginLeft: 11 }}>
        <Text style={s.zglName} numberOfLines={1}>{p?.name || "Insider"}</Text>
        <Text style={s.zglWhat} numberOfLines={1}>
          <Text style={{ color: kupno ? C.green : C.red, fontWeight: "800" }}>
            {kupno ? "kupno" : "sprzedaż"}
          </Text>
          <Text style={{ color: C.text, fontWeight: "800" }}> {t.ticker}</Text>
          {szczegol ? <Text style={{ color: C.dim }}> · {szczegol}</Text> : null}
        </Text>
      </View>
      <View style={{ alignItems: "flex-end", marginLeft: 8 }}>
        <Text style={s.zglAmt}>{kwota(t)}</Text>
        <Text style={s.zglDate}>ujawnione {ileTemu(t.filed || t.date)}</Text>
      </View>
    </Press>
  );
}

function Szkielet() {
  const a = useRef(new Animated.Value(0.4)).current;
  useEffect(() => {
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(a, { toValue: 0.85, duration: 700, useNativeDriver: true }),
      Animated.timing(a, { toValue: 0.4, duration: 700, useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);
  return (
    <Animated.View style={[s.body, { opacity: a }]}>
      <View style={s.column}>
        <View style={[s.bone, { width: "60%", height: 26, marginTop: 8 }]} />
        <View style={[s.bone, { width: "90%", height: 12, marginTop: 12 }]} />
        <View style={{ flexDirection: "row", gap: 10, marginTop: 18 }}>
          {[0, 1, 2].map((k) => <View key={k} style={[s.bone, { flex: 1, height: 64, borderRadius: 14 }]} />)}
        </View>
        {[0, 1, 2, 3, 4, 5].map((k) => (
          <View key={k} style={[s.bone, { height: 74, borderRadius: 16, marginTop: 10 }]} />
        ))}
      </View>
    </Animated.View>
  );
}

