/** Premium — katalog funkcji premium i przyciski cenowe.
 *
 *  Treść wzięta z web-only „Aplikacja" (AppPromoScreen), ale bez sekcji o instalacji
 *  na telefon (QR, PWA, screenshoty) — bo na telefonie to bez sensu.
 *
 *  Karty cenowe (Miesięcznie / Rocznie) są tu PRZYCISKAMI otwierającymi PaywallScreen,
 *  nie statycznymi kartami — celem jest dać użytkownikowi szybki dostęp do zakupu.
 */
import React, { useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator, Animated, Easing, Pressable, ScrollView,
  StyleSheet, Text, View,
} from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { getPremiumCatalog, PremiumCatalog, PremiumFeature, PremiumPlan, trackPremium } from "../api";
import { useAuth } from "../auth/AuthContext";
import AboutStudio from "../components/AboutStudio";
import { C, T } from "../theme";
import { IkonaZSerwera } from "../ui/Icon";
import { Card, FadeIn, MetalButton } from "../ui";

import Icon from "../ui/Icon";
import { TAB_SPACE } from "../layout";
/** Kwota z groszami po polsku: 5,99 zł */
function kwota(v: number, currency = "PLN") {
  const n = v.toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return currency === "PLN" ? `${n} zł` : `${n} ${currency}`;
}

export default function PremiumScreen() {
  const { premium, showPaywall } = useAuth();
  const [katalog, setKatalog] = useState<PremiumCatalog | null>(null);

  useEffect(() => {
    getPremiumCatalog().then(setKatalog).catch(() => setKatalog(null));
  }, []);

  const funkcje = katalog?.features || [];
  const pierwsza = funkcje[0]?.id || "tools.etf";
  const plans = katalog?.plans || [];

  return (
    <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>

      {/* --------------------------------------------------------- hero */}
      <FadeIn>
        <View style={s.hero}>
          <LinearGradient
            colors={["rgba(255,210,74,.14)", "rgba(200,137,32,.06)", "rgba(8,11,17,0)"]}
            start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
            style={StyleSheet.absoluteFill as any}
          />
          <View style={s.heroIn}>
            <Text style={s.nad}>PORTEVO PREMIUM</Text>
            <Text style={s.heroH1}>
              {katalog?.headline || "Portevo widzi więcej,\nniż pokazuje"}
            </Text>
            {!!katalog?.subheadline && (
              <Text style={s.heroSub}>{katalog.subheadline}</Text>
            )}
            {premium && (
              <View style={s.masz}>
                <Text style={s.maszTxt}>Masz premium — wszystko jest odblokowane</Text>
              </View>
            )}
          </View>
        </View>
      </FadeIn>

      {/* ------------------------------------------------- funkcje + cennik */}
      {!katalog ? (
        <View style={s.center}><ActivityIndicator color={C.gold} /></View>
      ) : (
        <>
          {/* Cennik od razu pod hero — miejsce zakupu ma być pierwszą rzeczą,
              którą widać po wejściu, a nie czymś, czego trzeba szukać na dole
              po przewinięciu funkcji i sekcji „o nas". */}
          <Text style={s.sekcja}>Wybierz plan</Text>
          <Text style={s.sekcjaHint}>
            Jedno konto obsługuje telefon i przeglądarkę. Trzon aplikacji zostaje darmowy.
          </Text>

          <View style={{ gap: 10, marginTop: 14 }}>
            {plans.map((p, i) => (
              <FadeIn key={p.id} delay={i * 70} offset={10}>
                <PlanButton plan={p} onPress={() => {
                  trackPremium("premium_plan_tap", p.id);
                  showPaywall(pierwsza);
                }} />
              </FadeIn>
            ))}
          </View>

          {/* ---------------------------------------------- funkcje */}
          <Text style={s.sekcja}>Co dostajesz</Text>
          <View style={s.funkcjeRzad}>
            {funkcje.map((f, i) => (
              <FadeIn key={f.id} delay={Math.min(i * 40, 300)} offset={9}
                      style={[s.funkcjaKom, { width: "100%" }]}>
                <FunkcjaKarta f={f} onPress={() => showPaywall(f.id)} />
              </FadeIn>
            ))}
          </View>

          {/* ---------------------------------------- główny CTA */}
          {!premium && (
            <FadeIn delay={200}>
              <ShimmerCTA
                label="Odblokuj Portevo Premium"
                onPress={() => {
                  trackPremium("premium_cta", pierwsza);
                  showPaywall(pierwsza);
                }}
              />
            </FadeIn>
          )}
        </>
      )}

      {/* ------------------------------------------------------- o nas */}
      <AboutStudio premium={premium} />

      <Text style={s.stopka}>
        Portevo nie jest doradcą inwestycyjnym. Dane mają charakter informacyjny
        i nie stanowią rekomendacji ani oferty kupna lub sprzedaży instrumentów
        finansowych.
      </Text>
    </ScrollView>
  );
}

/* ---------------------------------------------------------- karta funkcji */

function FunkcjaKarta({ f, onPress }: { f: PremiumFeature; onPress: () => void }) {
  return (
    <Card style={s.funkcja}>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
        <IkonaZSerwera name={f.icon} size={19} color={C.amber} />
        <Text style={s.funkcjaTytul} numberOfLines={1}>{f.title}</Text>
        {f.status === "soon" && <Text style={s.wkrotce}>WKRÓTCE</Text>}
      </View>
      <Text style={s.funkcjaTag}>{f.tagline}</Text>
      {!!f.bullets?.length && (
        <View style={{ marginTop: 9, gap: 5 }}>
          {f.bullets.slice(0, 3).map((b) => (
            <View key={b} style={{ flexDirection: "row", gap: 8 }}>
              <View style={s.ptaszek}><Icon name="ptaszek" size={12} color={C.amber} /></View>
              <Text style={s.punkt}>{b}</Text>
            </View>
          ))}
        </View>
      )}
      <MetalButton label="Zobacz szczegóły" tone="amber" size="sm" full
                   style={{ marginTop: 12 }} onPress={onPress} />
    </Card>
  );
}

/* ---------------------------------------------------------- przycisk planu */

function PlanButton({ plan, onPress }: { plan: PremiumPlan; onPress: () => void }) {
  const hot = Boolean(plan.highlight);
  const scale = React.useRef(new Animated.Value(1)).current;

  return (
    <Pressable
      onPress={onPress}
      onPressIn={() => Animated.spring(scale, { toValue: 0.97, useNativeDriver: true, speed: 50, bounciness: 6 }).start()}
      onPressOut={() => Animated.spring(scale, { toValue: 1, useNativeDriver: true, speed: 50, bounciness: 6 }).start()}
    >
      <Animated.View style={{ transform: [{ scale }] }}>
        <LinearGradient
          colors={hot
            ? ["rgba(255,210,74,.20)", "rgba(200,137,32,.05)"]
            : [C.border2, C.border]}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={[s.planEdge, hot && s.planEdgeHot]}
        >
          <View style={[s.planFace, hot && { backgroundColor: "rgba(255,210,74,.04)" }]}>
            {!!plan.badge && (
              <View style={s.planBadge}>
                <Text style={s.planBadgeTxt}>{plan.badge}</Text>
              </View>
            )}
            <View style={s.planRow}>
              <View style={{ flex: 1 }}>
                <Text style={s.planNazwa}>{plan.label}</Text>
                {!!plan.note && <Text style={s.planNota}>{plan.note}</Text>}
              </View>
              <View style={{ alignItems: "flex-end" }}>
                <View style={{ flexDirection: "row", alignItems: "baseline", gap: 4 }}>
                  {!!plan.price_original && plan.price_original > plan.price && (
                    <Text style={s.planStara}>{kwota(plan.price_original, plan.currency)}</Text>
                  )}
                  <Text style={[s.planCena, hot && { color: C.gold }]}>
                    {kwota(plan.price, plan.currency)}
                  </Text>
                  <Text style={s.planZa}>/ {plan.period}</Text>
                </View>
                {!!plan.save_label && (
                  <View style={s.planOszcz}>
                    <Text style={s.planOszczTxt}>{plan.save_label}</Text>
                  </View>
                )}
              </View>
            </View>
            {/* strzałka wskazująca, że to przycisk */}
            <Text style={s.planArrow}>›</Text>
          </View>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

/* ---------------------------------------------------------- shimmer CTA */

function ShimmerCTA({ label, onPress }: { label: string; onPress: () => void }) {
  const shimmer = React.useRef(new Animated.Value(0)).current;
  const scale = React.useRef(new Animated.Value(1)).current;

  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(shimmer, { toValue: 1, duration: 2400, easing: Easing.inOut(Easing.quad), useNativeDriver: true }),
        Animated.delay(1800),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, []);

  return (
    <Pressable
      onPress={onPress}
      onPressIn={() => Animated.spring(scale, { toValue: 0.97, useNativeDriver: true, speed: 50, bounciness: 6 }).start()}
      onPressOut={() => Animated.spring(scale, { toValue: 1, useNativeDriver: true, speed: 50, bounciness: 6 }).start()}
    >
      <Animated.View style={[s.cta, { transform: [{ scale }] }]}>
        <LinearGradient
          colors={["#c8891a", "#ffd24a", "#c8891a"]}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={s.ctaGrad}
        >
          <Animated.View
            pointerEvents="none"
            style={[
              s.ctaShine,
              {
                opacity: shimmer.interpolate({ inputRange: [0, 0.15, 1], outputRange: [0, 0.6, 0] }),
                transform: [
                  { translateX: shimmer.interpolate({ inputRange: [0, 1], outputRange: [-200, 400] }) },
                  { rotate: "18deg" },
                ],
              },
            ]}
          />
          <Text style={s.ctaTxt}>{label}</Text>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

/* ---------------------------------------------------------------- style */

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: TAB_SPACE },
  center: { paddingVertical: 30, alignItems: "center" },

  hero: {
    borderRadius: 22, borderWidth: 1, borderColor: "rgba(255,210,74,.28)",
    overflow: "hidden", marginTop: 8,
  },
  heroIn: { padding: 22 },
  nad: { color: C.gold, ...T.micro },
  heroH1: { color: C.text, ...T.h1, marginTop: 10 },
  heroSub: { color: C.muted, ...T.body, lineHeight: 22, marginTop: 10 },
  masz: {
    marginTop: 14, borderRadius: 12, paddingVertical: 9, paddingHorizontal: 12,
    backgroundColor: "rgba(47,212,138,.10)", borderWidth: 1, borderColor: "rgba(47,212,138,.35)",
  },
  maszTxt: { color: C.green, ...T.small, fontWeight: "700", textAlign: "center" },

  sekcja: { color: C.text, ...T.h2, marginTop: 28 },
  sekcjaHint: { color: C.dim, ...T.small, marginTop: 4, lineHeight: 17 },

  funkcjeRzad: { marginTop: 12, gap: 10 },
  funkcjaKom: { marginBottom: 0 },
  funkcja: { padding: 15 },
  funkcjaTytul: { flex: 1, color: C.text, fontSize: 14.5, fontWeight: "800" },
  funkcjaTag: { color: C.muted, fontSize: 12.3, lineHeight: 17, marginTop: 8 },
  ptaszek: { color: C.gold, fontSize: 12, fontWeight: "800", marginTop: 2 },
  punkt: { flex: 1, color: C.text, fontSize: 12, lineHeight: 17 },
  wkrotce: {
    color: C.violet, fontSize: 9, fontWeight: "800", letterSpacing: 0.7,
    backgroundColor: "rgba(167,139,250,.14)", borderRadius: 999,
    paddingHorizontal: 7, paddingVertical: 2, overflow: "hidden",
  },

  /* karty cenowe → przyciski */
  planEdge: {
    borderRadius: 16, padding: 1.5,
  },
  planEdgeHot: {
    // Miękka, rozproszona poświata zamiast ostrego złotego halo: niższa krycie
    // przy większym promieniu czyta się jak naturalne światło, a nie jak obwódka.
    shadowColor: C.goldDeep, shadowOpacity: 0.13, shadowRadius: 18, shadowOffset: { width: 0, height: 5 },
  },
  planFace: {
    borderRadius: 14.5, backgroundColor: C.elev, padding: 16,
    overflow: "hidden",
  },
  planRow: {
    flexDirection: "row", alignItems: "center", gap: 12,
  },
  planBadge: {
    position: "absolute", top: -1, right: 16,
    backgroundColor: C.gold, borderBottomLeftRadius: 8, borderBottomRightRadius: 8,
    paddingHorizontal: 10, paddingVertical: 3,
  },
  planBadgeTxt: { color: "#1b1204", fontSize: 9, fontWeight: "800", letterSpacing: 0.6 },
  planNazwa: { color: C.text, fontSize: 15, fontWeight: "800" },
  planCena: { color: C.text, fontSize: 22, fontWeight: "800", letterSpacing: -0.5 },
  planZa: { color: C.dim, fontSize: 13, fontWeight: "600" },
  planStara: {
    color: C.red, fontSize: 13, fontWeight: "700", textDecorationLine: "line-through",
  },
  planNota: { color: C.dim, fontSize: 11.5, marginTop: 2, lineHeight: 16 },
  planOszcz: {
    backgroundColor: "rgba(47,212,138,.14)", borderRadius: 999,
    paddingHorizontal: 8, paddingVertical: 2, marginTop: 4,
  },
  planOszczTxt: { color: C.green, fontSize: 10, fontWeight: "800" },
  planArrow: {
    position: "absolute", right: 16, top: "50%" as any,
    color: C.dim, fontSize: 22, fontWeight: "300",
    marginTop: -11,
  },

  /* CTA shimmer button */
  cta: { marginTop: 22, borderRadius: 16, overflow: "hidden" },
  ctaGrad: {
    paddingVertical: 16, alignItems: "center", justifyContent: "center",
    overflow: "hidden",
  },
  ctaShine: {
    position: "absolute", width: 80, top: -20, bottom: -20,
    backgroundColor: "rgba(255,255,255,.35)",
  },
  ctaTxt: {
    color: "#1b1204", fontSize: 16, fontWeight: "800", letterSpacing: -0.3,
  },

  stopka: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 30, textAlign: "center" },
});
