/** Zasłona funkcji premium — złota ramka, zanikająca zawartość, zachęta.
 *
 *  Trzy decyzje projektowe, z których wynika reszta:
 *
 *  1. **Funkcji nie chowamy.** Pod spodem zostaje prawdziwy interfejs z prawdziwym
 *     układem. Góra karty jest czytelna, dół zanika w złotą mgłę — użytkownik widzi,
 *     że coś tam jest, i widzi dokładnie ile mu brakuje.
 *  2. **Zachęta mówi konkretami.** Zamiast „wykup premium" pokazujemy trzy rzeczy,
 *     które ta konkretna funkcja robi — biorąc je z katalogu na serwerze, więc
 *     treść da się zmieniać bez wydawania nowej wersji aplikacji.
 *  3. **Właściciel widzi obie warstwy.** W trybie podglądu kłódka pojawia się także
 *     na koncie z premium, ale da się przez nią przejść jednym dotknięciem.
 *
 *  React Native nie ma taniego rozmycia bez dodatkowej paczki (a projekt celowo nie
 *  dokłada zależności pod Expo Go), więc „zamglenie" robimy gradientem i przygaszeniem.
 *  Efekt jest ten sam: kształt widać, liczb nie da się odczytać.
 */
import { LinearGradient } from "expo-linear-gradient";
import React, { useEffect, useRef, useState } from "react";
import {
  Animated, Easing, Pressable, StyleSheet, Text, View, ViewStyle,
} from "react-native";
import { trackPremium } from "../api";
import { useAuth } from "../auth/AuthContext";
import { C, T } from "../theme";
import Icon from "../ui/Icon";

const GOLD = "#ffc45c";
const GOLD_DIM = "#a9741f";

export default function PremiumGate({
  id, children, style, minHeight = 260, bullets = 3, title, tagline,
}: {
  id: string;
  children: React.ReactNode;
  style?: ViewStyle;
  /** ile miejsca zajmuje zasłona, gdy dzieci jeszcze się nie wczytały */
  minHeight?: number;
  /** ile korzyści wypisać pod nagłówkiem */
  bullets?: number;
  /** nadpisanie treści z katalogu — przydatne dla sekcji, których nie ma na liście */
  title?: string;
  tagline?: string;
}) {
  const { locked, feature, showPaywall, previewOnly } = useAuth();
  const isLocked = locked(id);
  const f = feature(id);
  const preview = previewOnly(id);

  const counted = useRef(false);
  useEffect(() => {
    if (isLocked && !counted.current) { counted.current = true; trackPremium("lock_seen", id); }
  }, [isLocked, id]);

  if (!isLocked) return <>{children}</>;

  return (
    <GoldFrame style={style} onPress={() => showPaywall(id)} preview={preview}>
      <View style={{ minHeight }}>
        {/* prawdziwa zawartość: góra czytelna, dół gaśnie */}
        <View style={s.under} pointerEvents="none">{children}</View>
        <FadeOut />

        <View style={s.panel} pointerEvents="none">
          <View style={s.badgeRow}>
            <View style={s.lockChip}>
              <Icon name="klodka" size={10} color={GOLD} />
              <Text style={s.lockChipTxt}>PREMIUM</Text>
            </View>
            {preview && (
              <View style={s.devChip}><Text style={s.devChipTxt}>PODGLĄD</Text></View>
            )}
          </View>

          <Text style={s.title} numberOfLines={2}>
            {title || f?.title || "Funkcja premium"}
          </Text>
          {!!(tagline || f?.tagline) && (
            <Text style={s.tagline} numberOfLines={2}>{tagline || f?.tagline}</Text>
          )}

          {!!f?.bullets?.length && (
            <View style={s.bullets}>
              {f.bullets.slice(0, bullets).map((b) => (
                <View key={b} style={s.bulletRow}>
                  <View style={s.tick}><Icon name="ptaszek" size={11} color={GOLD} /></View>
                  <Text style={s.bulletTxt} numberOfLines={2}>{b}</Text>
                </View>
              ))}
            </View>
          )}

          <ShimmerButton label={preview ? "Zobacz warstwę sprzedażową" : "Odblokuj tę funkcję"} />
        </View>
      </View>
    </GoldFrame>
  );
}

/* ------------------------------------------------------------------ ramka */

/** Złota obwódka z przebiegającym połyskiem. Nacisk lekko wciska całość. */
function GoldFrame({
  children, onPress, style, preview,
}: {
  children: React.ReactNode; onPress: () => void; style?: ViewStyle; preview?: boolean;
}) {
  const scale = useRef(new Animated.Value(1)).current;
  const sweep = useRef(new Animated.Value(0)).current;
  const [w, setW] = useState(0);

  useEffect(() => {
    // połysk przelatuje raz na sześć sekund — wystarczy, żeby przyciągnąć wzrok,
    // za rzadko, żeby przeszkadzać przy przewijaniu listy
    const loop = Animated.loop(Animated.sequence([
      Animated.delay(2600),
      Animated.timing(sweep, {
        toValue: 1, duration: 1500, easing: Easing.inOut(Easing.quad), useNativeDriver: true,
      }),
      Animated.timing(sweep, { toValue: 0, duration: 0, useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);

  const spring = (to: number) =>
    Animated.spring(scale, { toValue: to, useNativeDriver: true, speed: 45, bounciness: 5 }).start();

  return (
    <Pressable onPressIn={() => spring(0.985)} onPressOut={() => spring(1)} onPress={onPress}
               style={style}>
      <Animated.View onLayout={(e) => setW(e.nativeEvent.layout.width)}
                     style={{ transform: [{ scale }] }}>
        <LinearGradient
          colors={preview
            ? ["rgba(167,139,250,.85)", "rgba(255,196,92,.55)", "rgba(167,139,250,.35)"]
            : [GOLD, "rgba(255,196,92,.35)", GOLD_DIM]}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={s.edge}
        >
          <View style={s.face}>
            {children}
            {w > 0 && (
              <Animated.View
                pointerEvents="none"
                style={[
                  s.sheen,
                  {
                    opacity: sweep.interpolate({ inputRange: [0, 0.2, 0.8, 1], outputRange: [0, 0.5, 0.5, 0] }),
                    transform: [
                      { translateX: sweep.interpolate({ inputRange: [0, 1], outputRange: [-140, w + 140] }) },
                      { rotate: "14deg" },
                    ],
                  },
                ]}
              >
                <LinearGradient
                  colors={["rgba(255,255,255,0)", "rgba(255,214,140,.5)", "rgba(255,255,255,0)"]}
                  start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }}
                  style={StyleSheet.absoluteFill as any}
                />
              </Animated.View>
            )}
          </View>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

/** Przejście od czytelnej góry do nieczytelnego dołu. */
function FadeOut() {
  return (
    <LinearGradient
      pointerEvents="none"
      colors={["rgba(10,13,19,.10)", "rgba(10,13,19,.72)", "rgba(12,10,6,.97)"]}
      locations={[0, 0.34, 0.68]}
      style={StyleSheet.absoluteFill as any}
    />
  );
}

/** Przycisk z falą światła — sygnał „tu się klika", bez krzyku. */
function ShimmerButton({ label }: { label: string }) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(a, { toValue: 1, duration: 1700, easing: Easing.linear, useNativeDriver: true }),
      Animated.delay(1400),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);
  return (
    <View style={s.cta}>
      <Animated.View
        pointerEvents="none"
        style={[
          s.ctaSheen,
          {
            opacity: a.interpolate({ inputRange: [0, 0.15, 0.85, 1], outputRange: [0, 0.85, 0.85, 0] }),
            transform: [{ translateX: a.interpolate({ inputRange: [0, 1], outputRange: [-60, 240] }) }],
          },
        ]}
      />
      <Text style={s.ctaTxt}>{label}</Text>
      <Text style={s.ctaArrow}>→</Text>
    </View>
  );
}

/* -------------------------------------------------------------- drobiazgi */

/** Mała kłódka przy nagłówku — gdy zasłonięcie całej karty rozwaliłoby układ. */
export function PremiumChip({ id, label }: { id: string; label?: string }) {
  const { locked, showPaywall } = useAuth();
  if (!locked(id)) return null;
  return (
    <Pressable onPress={() => showPaywall(id)} style={s.chip} hitSlop={8}>
      <Icon name="klodka" size={10} color={GOLD} />
      <Text style={s.chipTxt}>{label || "PREMIUM"}</Text>
    </Pressable>
  );
}

/** Przełącznik trybu podglądu — stoi na każdym ekranie z funkcjami premium.
 *
 *  Wcześniej siedział tylko w „Więcej" i trzeba było o nim wiedzieć. Teraz jest
 *  dokładnie tam, gdzie się go potrzebuje: nad kłódkami, w obie strony.
 */
export function PreviewBanner() {
  const { previewFree, isDev, setPreviewFree } = useAuth();
  if (!isDev) return null;

  if (previewFree) {
    return (
      <Pressable onPress={() => setPreviewFree(false)} style={s.banner}>
        <Icon name="oko" size={14} color={C.violet} />
        <Text style={s.bannerTxt}>Widok „bez premium" — dotknij, aby odblokować wszystko</Text>
      </Pressable>
    );
  }
  return (
    <Pressable onPress={() => setPreviewFree(true)} style={s.bannerOff}>
      <Icon name="narzedzia" size={14} color={C.muted} />
      <Text style={s.bannerOffTxt}>Masz pełny dostęp — dotknij, aby zobaczyć widok bez premium
      </Text>
    </Pressable>
  );
}

/** Ostrzeżenie, gdy panel na komputerze nie zna jeszcze nowych funkcji.
 *
 *  Aplikacja aktualizuje się sama, panel trzeba uruchomić ponownie ręcznie — bez
 *  tego paska rozjazd objawia się serią pustych ekranów i nie wiadomo dlaczego.
 */
export function StalePanelBanner() {
  const { panelStale } = useAuth();
  if (!panelStale) return null;
  return (
    <View style={s.stale}>
      <Text style={s.staleTitle}>Panel na komputerze jest w starszej wersji</Text>
      <Text style={s.staleTxt}>
        Nowe funkcje nie mają skąd wziąć danych. Uruchom panel ponownie skrótem
        „Portevo (telefon)" na pulpicie i wróć tutaj.
      </Text>
    </View>
  );
}

