/** Artykuły — spis wszystkich podstron pozycjonowanych, do klikania i oglądania.
 *
 *  Po co to jest: warstwa SEO (`bot/seo/`) to ponad trzysta stron, których nie
 *  widać z wnętrza aplikacji — stoją pod własnymi adresami i istnieją głównie
 *  dla wyszukiwarek. Bez takiego spisu jedynym sposobem, żeby sprawdzić, jak
 *  wygląda którakolwiek z nich, było wpisanie adresu z pamięci.
 *
 *  Spis pobieramy z serwera (`/api/seo/strony`), a nie trzymamy w kodzie
 *  aplikacji. To celowe: lista powstaje z tych samych modułów, z których
 *  powstają same strony, więc nowa podstrona pojawia się tutaj sama. Kopia
 *  w kodzie rozjechałaby się przy pierwszej zmianie po stronie serwera.
 *
 *  Ekran jest WYŁĄCZNIE dla przeglądarki — na telefonie zakładka w ogóle się
 *  nie pojawia, bo otwieranie stron pozycjonowanych w aplikacji mobilnej nie ma
 *  sensu (to treść dla Google, nie dla użytkownika apki).
 */
import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator, Platform, ScrollView, StyleSheet, Text, TextInput, View,
} from "react-native";
import { getSeoSpis, SeoGrupa, SeoSpis, SeoStrona } from "../api";
import { useLayout, TAB_SPACE } from "../layout";
import { C, T } from "../theme";
import { Card, FadeIn, MetalButton, Press, RefreshButton, SectionTitle } from "../ui";

/** Otwarcie podstrony w nowej karcie — po to, żeby aplikacja została otwarta obok. */
function otworz(adres: string, baza: string) {
  if (Platform.OS !== "web") return;
  try {
    // Adres względny wystarczy: aplikacja i podstrony stoją na tym samym
    // serwerze. `baza` przydaje się tylko w podglądzie z `expo start --web`,
    // gdzie na localhoście żadnych podstron nie ma.
    const cel = typeof window !== "undefined" && window.location?.origin
      && !/localhost|127\.0\.0\.1/.test(window.location.hostname)
      ? adres : baza.replace(/\/$/, "") + adres;
    window.open(cel, "_blank", "noopener,noreferrer");
  } catch {
    // Zablokowane wyskakujące okna nie mogą wywalić ekranu.
  }
}

/** Znaki łączące (ogonki, kreski, kropki) odcięte od liter przez rozkład NFD.
 *
 *  Zapisane przez konstruktor `RegExp`, a nie literałem `/[...]/`: w literale
 *  stałyby w pliku jako niewidoczne znaki doklejone do nawiasu, więc każdy
 *  edytor i każde narzędzie tekstowe miałoby okazję je po cichu uszkodzić.
 */
const ZNAKI_LACZACE = new RegExp("[\\u0300-\\u036f]", "g");

/** Napis sprowadzony do postaci porównywalnej: bez wielkości liter i bez ogonków.
 *
 *  Bez tego „zaskoczenie" nie znajdowałoby „zaskoczenie wynikami" wpisanego jako
 *  „zaskoczenie", a „lotos" nie trafiałby na „Lotos". Rozkład NFD odcina znaki
 *  diakrytyczne od liter bazowych, ale „ł" nie ma postaci złożonej i musi
 *  zostać podmienione osobno.
 */
function uprosc(t: string): string {
  return (t || "").toLowerCase()
    .normalize("NFD").replace(ZNAKI_LACZACE, "")
    .replace(/ł/g, "l");
}

export default function PagesScreen() {
  const { wide } = useLayout();
  const [spis, setSpis] = useState<SeoSpis | null>(null);
  const [blad, setBlad] = useState("");
  const [busy, setBusy] = useState(false);
  const [grupa, setGrupa] = useState("funkcje");
  const [szukaj, setSzukaj] = useState("");
  const [rynek, setRynek] = useState("wszystkie");
  const [limit, setLimit] = useState(40);

  const load = useCallback(async () => {
    try {
      setBlad("");
      setSpis(await getSeoSpis());
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się pobrać spisu podstron.");
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => { load(); }, []);

  // Nowe kryterium = nowy początek listy. Bez tego po wpisaniu szukanej frazy
  // zostawał limit przewinięty z poprzedniej grupy i wyniki wyglądały na ucięte.
  useEffect(() => { setLimit(40); }, [grupa, szukaj, rynek]);

  const grupy: SeoGrupa[] = spis?.grupy || [];
  const aktywna = grupy.find((g) => g.id === grupa) || null;

  const widoczne = useMemo(() => {
    let strony: SeoStrona[] =
      grupa === "pliki" ? (spis?.pliki || [])
      : grupa === "pozostale" ? (spis?.pozostale || [])
      : (aktywna?.strony || []);

    if (grupa === "spolki" && rynek !== "wszystkie") {
      strony = strony.filter((s) => s.rynek === rynek);
    }
    const q = uprosc(szukaj.trim());
    if (!q) return strony;
    return strony.filter((s) =>
      uprosc(s.tytul).includes(q) || uprosc(s.opis).includes(q)
      || uprosc(s.tag).includes(q) || uprosc(s.adres).includes(q));
  }, [spis, grupa, aktywna, szukaj, rynek]);

  if (!spis && !blad) {
    return <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>;
  }

  const zakladki = [
    ...grupy.map((g) => ({ id: g.id, label: g.tytul, ile: g.strony.length })),
    { id: "pozostale", label: "Informacje", ile: (spis?.pozostale || []).length },
    { id: "pliki", label: "Pliki", ile: (spis?.pliki || []).length },
  ];

  const baza = spis?.baza || "";

  return (
    <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
      <FadeIn>
        <View style={s.titleRow}>
          <View style={{ flex: 1 }}>
            <Text style={s.h1}>Artykuły i dane</Text>
            <Text style={s.sub}>
              {spis ? `${spis.razem} podstron widocznych dla Google — kliknij, żeby otworzyć` : ""}
            </Text>
          </View>
          <RefreshButton busy={busy} onPress={() => { setBusy(true); load(); }} />
        </View>
      </FadeIn>

      {!!blad && (
        <Card style={s.blad}>
          <Text style={s.bladTxt}>{blad}</Text>
        </Card>
      )}

      {!!spis && (
        <>
          <FadeIn delay={60}>
            <TextInput
              value={szukaj}
              onChangeText={setSzukaj}
              placeholder="Szukaj po nazwie, tickerze albo adresie…"
              placeholderTextColor={C.dim}
              style={s.szukaj}
            />
          </FadeIn>

          <View style={s.chipy}>
            {zakladki.map((z) => (
              <MetalButton
                key={z.id} size="sm" tone="green" liquid
                active={grupa === z.id}
                label={`${z.label} · ${z.ile}`}
                onPress={() => setGrupa(z.id)}
              />
            ))}
          </View>

          {grupa === "spolki" && (
            <View style={[s.chipy, { marginTop: 8 }]}>
              {[
                { id: "wszystkie", label: "Wszystkie" },
                { id: "GPW", label: "GPW" },
                { id: "USA", label: "USA" },
              ].map((r) => (
                <MetalButton key={r.id} size="sm" tone="blue" active={rynek === r.id}
                             label={r.label} onPress={() => setRynek(r.id)} />
              ))}
            </View>
          )}

          {!!aktywna && (
            <SectionTitle hint={aktywna.opis}>{aktywna.tytul}</SectionTitle>
          )}
          {grupa === "pliki" && (
            <SectionTitle hint="Pliki techniczne, którymi karmimy wyszukiwarki i modele językowe">
              Pliki
            </SectionTitle>
          )}
          {grupa === "pozostale" && (
            <SectionTitle hint="Strony poza warstwą SEO, ale też publiczne">
              Informacje
            </SectionTitle>
          )}

          {!!aktywna && (
            <MetalButton
              label={`Otwórz spis: ${aktywna.spis}`} tone="steel" full
              style={{ marginBottom: 12 }}
              onPress={() => otworz(aktywna.spis, baza)}
            />
          )}

          {widoczne.length === 0 && (
            <Text style={s.pusto}>Nic nie pasuje do „{szukaj}".</Text>
          )}

          {/* Na szerokim ekranie dwie kolumny — 266 spółek w jednej kolumnie to
              kilometr przewijania, a miejsca w poziomie jest aż nadto. */}
          <View style={wide ? s.siatka : undefined}>
            {widoczne.slice(0, limit).map((p, i) => (
              <View key={p.adres} style={wide ? s.komorka : undefined}>
                <FadeIn delay={Math.min(i * 10, 180)} offset={8}>
                  <Press onPress={() => otworz(p.adres, baza)}>
                    <Card style={s.pozycja}>
                      <View style={s.pozGora}>
                        <Text style={s.pozTytul} numberOfLines={1}>{p.tytul}</Text>
                        {!!p.tag && (
                          <View style={s.tag}><Text style={s.tagTxt}>{p.tag}</Text></View>
                        )}
                      </View>
                      <Text style={s.pozOpis} numberOfLines={2}>{p.opis}</Text>
                      <Text style={s.pozAdres} numberOfLines={1}>{p.adres}</Text>
                    </Card>
                  </Press>
                </FadeIn>
              </View>
            ))}
          </View>

          {widoczne.length > limit && (
            <MetalButton
              full style={{ marginTop: 14 }}
              label={`Pokaż więcej (${widoczne.length - limit})`}
              onPress={() => setLimit((l) => l + 60)}
            />
          )}

          <Text style={s.stopka}>
            Podstrony otwierają się w nowej karcie — aplikacja zostaje tam, gdzie była.
            Spis buduje serwer z tych samych modułów, z których powstają same strony,
            więc każda nowa podstrona pojawi się tu bez zmian w aplikacji.
          </Text>
        </>
      )}
    </ScrollView>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: TAB_SPACE },
  center: { flex: 1, alignItems: "center", justifyContent: "center" },
  titleRow: { flexDirection: "row", alignItems: "flex-start", gap: 10 },
  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginTop: 3 },

  blad: { padding: 15, marginTop: 16, borderColor: "rgba(255,92,108,.35)" },
  bladTxt: { color: C.red, ...T.small, lineHeight: 19 },

  szukaj: {
    marginTop: 16, backgroundColor: C.elev, borderWidth: 1, borderColor: C.border,
    borderRadius: 13, paddingHorizontal: 14, paddingVertical: 11,
    color: C.text, fontSize: 14,
    // `outlineStyle` istnieje tylko na webie; na telefonie React Native je ignoruje
    ...(Platform.OS === "web" ? ({ outlineStyle: "none" } as any) : null),
  },

  chipy: { flexDirection: "row", flexWrap: "wrap", gap: 7, marginTop: 12 },

  siatka: { flexDirection: "row", flexWrap: "wrap", marginHorizontal: -5 },
  komorka: { width: "50%", paddingHorizontal: 5 },

  pozycja: { padding: 13, marginBottom: 9 },
  pozGora: { flexDirection: "row", alignItems: "center", gap: 8 },
  pozTytul: { flex: 1, color: C.text, fontSize: 14, fontWeight: "800", letterSpacing: -0.2 },
  tag: {
    backgroundColor: C.greenDim, borderRadius: 7, paddingHorizontal: 7, paddingVertical: 3,
  },
  tagTxt: { color: C.green, fontSize: 10, fontWeight: "800", letterSpacing: 0.3 },
  pozOpis: { color: C.muted, fontSize: 12.3, lineHeight: 17, marginTop: 5 },
  pozAdres: { color: C.dim, fontSize: 11, marginTop: 6 },

  pusto: { color: C.muted, ...T.body, textAlign: "center", paddingVertical: 26 },
  stopka: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 26 },
});
