/** Kod polecający czekający na konto.
 *
 *  Kod da się wpisać, zanim konto w ogóle istnieje: w oknie logowania (także przed
 *  „Kontynuuj z Google", gdzie nie ma formularza) albo wchodząc z linku twórcy
 *  `portevo.pl/k/KASIA`. Serwer przypisuje kod do KONTA, więc do chwili zalogowania
 *  trzymamy go na urządzeniu, a `AuthContext` wysyła go przy pierwszym `/api/me`
 *  z zalogowanym użytkownikiem.
 *
 *  Dlaczego pamięć urządzenia, a nie stan Reacta: logowanie Google na webie
 *  PRZEŁADOWUJE stronę (powrót z Google z tokenem w adresie), a na telefonie
 *  aplikacja potrafi zostać ubita w tle, gdy użytkownik jest w przeglądarce.
 *  Stan w pamięci nie przeżyłby ani jednego, ani drugiego.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Platform } from "react-native";
import { applyReferral, ReferralApply, ReferralSource } from "./api";

const K_PENDING = "portfel.referral.pending";
/** Znacznik „ten użytkownik ma już sprawę kodu załatwioną" — żeby kod z metadanych
 *  konta nie leciał do serwera przy każdym uruchomieniu. */
const K_DONE = "portfel.referral.done.";

/** Platforma w rozumieniu serwera. Darmowe premium z puli twórcy wydaje on tylko
 *  dla "web" — w aplikacji ze sklepu kod wyłącznie przypisuje konto (Apple 3.1.1). */
export const referralPlatform = (): "ios" | "android" | "web" =>
  Platform.OS === "ios" ? "ios" : Platform.OS === "android" ? "android" : "web";

/** Czy na tym urządzeniu wolno mówić o darmowym premium za kod. */
export const REWARD_HERE = Platform.OS === "web";

type Pending = { code: string; source: ReferralSource };

/** Wstępne oczyszczenie wpisu — ostatecznie normalizuje serwer. */
export const cleanCode = (t: string) =>
  (t || "").replace(/[\s@#.]/g, "").toUpperCase().slice(0, 24);

export async function setPendingReferral(code: string, source: ReferralSource) {
  const c = cleanCode(code);
  try {
    if (c) await AsyncStorage.setItem(K_PENDING, JSON.stringify({ code: c, source }));
    else await AsyncStorage.removeItem(K_PENDING);
  } catch { /* bez pamięci kod po prostu trzeba będzie wpisać w „Więcej" */ }
  emit();
}

export async function getPendingReferral(): Promise<Pending | null> {
  try {
    const raw = await AsyncStorage.getItem(K_PENDING);
    const p = raw ? JSON.parse(raw) : null;
    return p?.code ? p : null;
  } catch {
    return null;
  }
}

async function clearPending() {
  try { await AsyncStorage.removeItem(K_PENDING); } catch { /* nic */ }
  emit();
}

/** Kod z adresu strony: `/?kod=KASIA` (tu odsyła krótki link `/k/KASIA`).
 *  Wołane raz przy starcie aplikacji — poza przeglądarką nic nie robi. */
export async function captureReferralFromUrl() {
  if (Platform.OS !== "web") return;
  try {
    const adres = new URLSearchParams(window.location.search);
    const kod = adres.get("kod") || adres.get("ref");
    if (!kod) return;
    // Kod z linku NIE nadpisuje kodu, który ktoś wpisał sam — ręczny wpis
    // jest świadomą decyzją, a link mógł zostać w starej karcie przeglądarki.
    const juz = await getPendingReferral();
    if (!juz || juz.source === "link") await setPendingReferral(kod, "link");
    // Zdejmujemy parametr z paska adresu: odświeżenie strony albo skopiowany
    // link nie powinny nieść cudzego kodu dalej.
    adres.delete("kod"); adres.delete("ref");
    const reszta = adres.toString();
    window.history.replaceState(null, "", window.location.pathname + (reszta ? `?${reszta}` : "") + window.location.hash);
  } catch { /* zły adres nie może zablokować startu */ }
}

/* ------------------------------------------------------ komunikat po przypisaniu */

type Listener = () => void;
const listeners = new Set<Listener>();
let notice: ReferralApply | null = null;

function emit() { listeners.forEach((l) => l()); }

export function subscribeReferral(fn: Listener) {
  listeners.add(fn);
  return () => { listeners.delete(fn); };
}

/** Ostatni wynik przypisania z tła — pokazuje go `ReferralNotice`. */
export const referralNotice = () => notice;
export function dismissReferralNotice() { notice = null; emit(); }

let wLocie: Promise<ReferralApply | null> | null = null;

/** Wysyła czekający kod dla świeżo zalogowanego konta.
 *
 *  `metaCode` to kod zapisany w metadanych konta przy rejestracji e-mailem. Ratuje
 *  sytuację, w której ktoś założył konto na telefonie, a link potwierdzający
 *  otworzył na komputerze — na tym drugim urządzeniu nic nie czeka w pamięci.
 *
 *  Kod zdejmujemy dopiero po ROZSTRZYGNIĘCIU (przypisany albo odrzucony).
 *  Brak sieci zostawia go na następny raz.
 */
export function flushPendingReferral(userId: string, metaCode?: string) {
  if (!userId) return Promise.resolve(null);
  if (!wLocie) {
    wLocie = (async () => {
      const czeka = await getPendingReferral();
      let doWyslania = czeka;
      if (!doWyslania && metaCode) {
        const zalatwione = await AsyncStorage.getItem(K_DONE + userId).catch(() => null);
        if (!zalatwione) doWyslania = { code: metaCode, source: "signup" };
      }
      if (!doWyslania) return null;

      let wynik: ReferralApply;
      try {
        wynik = await applyReferral(doWyslania.code, doWyslania.source, referralPlatform());
      } catch {
        return null;                            // spróbujemy przy następnym starcie
      }
      if (!wynik.ok && (wynik.error === "off" || wynik.error === "login")) return wynik;

      await clearPending();
      AsyncStorage.setItem(K_DONE + userId, "1").catch(() => {});
      // Kod z metadanych, który już był przypisany, nie zasługuje na komunikat —
      // to ten sam kod co zawsze, a nie coś, co użytkownik właśnie zrobił.
      const cichy = !czeka && (wynik.ok ? !wynik.reward_days : wynik.error === "other");
      if (!cichy) { notice = wynik; emit(); }
      return wynik;
    })().finally(() => { wLocie = null; });
  }
  return wLocie;
}
