/** Prośba o zgodę na powiadomienia — pokazywana zaraz po uruchomieniu aplikacji.
 *
 *  Dlaczego WŁASNE okno, a nie od razu systemowe: na iOS o zgodę wolno spytać
 *  RAZ. Drugie „nie" system zapamiętuje na stałe i odblokować to można już
 *  tylko w Ustawieniach telefonu. Własne okno pozwala wytłumaczyć, po co ta
 *  zgoda, ZANIM padnie pytanie, którego nie da się powtórzyć — a „nie teraz"
 *  nic nie psuje, bo systemowego pytania wtedy w ogóle nie zadajemy.
 *
 *  Kiedy się pokazuje: przy starcie zalogowanego, gdy urządzenie nie ma zgody.
 *  Odmowa („nie teraz") chowa je do końca tej sesji, ale wróci przy następnym
 *  uruchomieniu — bez zgody powiadomienia po prostu nie działają.
 *
 *  Dwa tryby, bo „brak zgody" ma dwie różne przyczyny:
 *  * `zgoda` — aplikacja umie powiadomienia (1.0.2+), trzeba tylko pozwolić;
 *  * `aktualizacja` — binarka jest sprzed powiadomień (1.0.1). Zapytać się nie
 *    da, więc prowadzimy do App Store. Bez tego taki telefon po cichu nie
 *    dostawał niczego, a test mówił „wysłane" (11.09.2026).
 */
import React, { useEffect, useState } from "react";
import { Linking, Modal, Platform, Pressable, StyleSheet, Text, View } from "react-native";
import { useAuth } from "../auth/AuthContext";
import * as powiadomienia from "../notifications";
import { C, T } from "../theme";
import { Card } from "../ui";
import Icon from "../ui/Icon";

/** Odmowa w tej sesji — świadomie w pamięci, nie na dysku (patrz nagłówek). */
let odrzuconoWTejSesji = false;

type Tryb = "zgoda" | "aktualizacja" | null;

export default function PushPrompt() {
  const { ready, user } = useAuth();
  const [tryb, setTryb] = useState<Tryb>(null);
  const [busy, setBusy] = useState(false);
  const [blad, setBlad] = useState("");

  useEffect(() => {
    if (!ready || !user || odrzuconoWTejSesji) return;

    if (powiadomienia.trzebaZaktualizowac) {
      // Sklep jest tylko dla iPhone'a — innej drogi aktualizacji nie mamy do pokazania.
      if (Platform.OS !== "ios") return;
      const t = setTimeout(() => setTryb("aktualizacja"), 1200);
      return () => clearTimeout(t);
    }
    if (!powiadomienia.obslugiwane) return;

    let aktualne = true;
    const t = setTimeout(async () => {
      // Zgoda już jest? Wtedy nie pytamy o nic — tylko po cichu odświeżamy token.
      // Token zmienia się po reinstalacji, a stary w bazie prowadzi donikąd.
      if (await powiadomienia.zarejestrujCiche()) return;
      if (aktualne && !(await powiadomienia.zgodaJest())) setTryb("zgoda");
    }, 1200);

    return () => { aktualne = false; clearTimeout(t); };
  }, [ready, user]);

  async function wlacz() {
    setBusy(true);
    setBlad("");
    try {
      const w = await powiadomienia.wlacz();
      if (w.ok) {
        setTryb(null);
        return;
      }
      if (w.powod === "odmowa") {
        // iOS pyta tylko raz. Po wcześniejszym „nie pozwalaj" jedyna droga to
        // Ustawienia — otwieramy je od razu, zamiast kazać ich szukać.
        setTryb(null);
        Linking.openSettings().catch(() => { /* brak Ustawień = nic nie zrobimy */ });
        return;
      }
      setBlad(w.komunikat || "Nie udało się włączyć powiadomień — spróbuj za chwilę.");
    } finally {
      setBusy(false);
    }
  }

  function aktualizuj() {
    odrzuconoWTejSesji = true;
    setTryb(null);
    Linking.openURL(powiadomienia.ADRES_SKLEPU).catch(() => { /* bez sklepu nic nie zrobimy */ });
  }

  function odrzuc() {
    odrzuconoWTejSesji = true;
    setTryb(null);
  }

  if (!tryb) return null;
  const aktualizacja = tryb === "aktualizacja";

  return (
    <Modal transparent animationType="fade" visible onRequestClose={odrzuc}>
      <View style={s.tlo}>
        {/* Dotknięcie tła zamyka okno — modal bez drugiego wyjścia blokuje całą apkę,
            gdy przyciski z jakiegoś powodu nie zadziałają. */}
        <Pressable style={StyleSheet.absoluteFill} onPress={odrzuc} accessibilityLabel="Zamknij" />
        <Card style={s.karta}>
          <View style={s.ikona}>
            <Icon name="dzwonek" size={20} color={C.green} />
          </View>

          <Text style={s.tytul}>
            {aktualizacja ? "Zaktualizuj Portevo, żeby dostawać powiadomienia"
                          : "Włączyć powiadomienia?"}
          </Text>
          <Text style={s.tresc}>
            {aktualizacja
              ? "Ta wersja aplikacji jest starsza niż powiadomienia i nie umie ich odebrać. "
                + "Nowa wersja w App Store da znać o newsach ze spółek z Twojego portfela "
                + "i o dniu publikacji ich wyników."
              : "Odezwiemy się, gdy pojawi się news o spółce z Twojego portfela albo "
                + "z listy obserwowanych — i rano w dniu, w którym któraś z nich publikuje "
                + "wyniki. Bez tego trzeba samemu zaglądać do aplikacji."}
          </Text>
          {!aktualizacja && (
            <Text style={s.drobne}>
              Sam decydujesz, jak głośno: wszystkie newsy albo tylko te o dużej sile.
              Wyłączysz to jednym dotknięciem w zakładce Bot newsów.
            </Text>
          )}
          {!!blad && <Text style={s.blad}>{blad}</Text>}

          {/* Zwykłe przyciski z prymitywów, nie MetalButton: w wersji 1.0.2 metalowe
              przyciski zapadały się tu do kreski i okno blokowało całą aplikację.
              Okno, które zasłania wszystko, musi mieć wyjście, które nie może zawieść. */}
          <View style={s.przyciski}>
            <Pressable onPress={odrzuc} disabled={busy}
                       style={({ pressed }) => [s.btn, pressed && s.wcisniety]}>
              <Text style={s.btnTxt}>Nie teraz</Text>
            </Pressable>
            <Pressable onPress={aktualizacja ? aktualizuj : wlacz} disabled={busy}
                       style={({ pressed }) => [s.btn, s.btnGlowny, pressed && s.wcisniety]}>
              <Text style={s.btnGlownyTxt} numberOfLines={1}>
                {aktualizacja ? "Otwórz App Store" : busy ? "Włączam…" : "Włącz powiadomienia"}
              </Text>
            </Pressable>
          </View>
        </Card>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  tlo: {
    flex: 1, backgroundColor: "rgba(4,6,11,.82)",
    alignItems: "center", justifyContent: "center", padding: 22,
  },
  karta: { padding: 20, width: "100%", maxWidth: 420 },
  ikona: {
    width: 38, height: 38, borderRadius: 13, backgroundColor: C.greenDim,
    borderWidth: 1, borderColor: "rgba(47,212,138,.32)",
    alignItems: "center", justifyContent: "center", marginBottom: 14,
  },
  tytul: { color: C.text, ...T.h2, marginBottom: 8 },
  tresc: { color: C.muted, ...T.small, lineHeight: 19.5 },
  drobne: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 10 },
  blad: { color: C.red, fontSize: 12, lineHeight: 17, marginTop: 10 },
  przyciski: { flexDirection: "row", gap: 9, marginTop: 18 },
  btn: {
    flex: 1, minHeight: 46, borderRadius: 13, paddingVertical: 12, paddingHorizontal: 10,
    borderWidth: 1, borderColor: C.border2, backgroundColor: C.card,
    alignItems: "center", justifyContent: "center",
  },
  btnGlowny: { flex: 1.35, backgroundColor: C.green, borderColor: C.green },
  btnTxt: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  btnGlownyTxt: { color: "#04140c", fontSize: 13.5, fontWeight: "800" },
  wcisniety: { opacity: 0.7 },
});
