/** Otwieranie panelu „Insajderzy" z dowolnego miejsca aplikacji.
 *
 *  Ten sam wzorzec, co `companyRouter`: powłoka (App.tsx) rejestruje jedną
 *  funkcję, ekrany proszą o otwarcie. Potrzebne, bo do panelu prowadzą trzy
 *  drogi — karta w Narzędziach, twarz na wykresie spółki (dla konta bez
 *  premium) i powiadomienie o transakcji obserwowanej osoby — a żadna z nich
 *  nie powinna importować powłoki.
 */

export type InsidersRequest = { person?: string };
type Opener = (req?: InsidersRequest) => void;

let opener: Opener | null = null;

export function setInsidersOpener(fn: Opener | null) {
  opener = fn;
}

/** Zwraca false, gdy nie ma kto obsłużyć. */
export function openInsiders(req?: InsidersRequest): boolean {
  if (!opener) return false;
  opener(req);
  return true;
}
