/** Proste wykresy liniowe wielokrotnego użytku — iskierka w wierszu listy i
 *  pełny wykres w karcie funduszu.
 *
 *  Świadomie osobno od `PortfolioChart`: tamten umie świece, benchmarki, znaczniki
 *  transakcji i przewijanie osi. Tutaj potrzebna jest jedna linia i wypełnienie pod
 *  nią, a ciągnięcie za sobą sześciuset linii cudzej logiki tylko po to, żeby
 *  narysować kreskę, kosztowałoby wydajność listy przy każdym przewinięciu.
 */
import React, { useEffect, useRef } from "react";
import { Animated, Easing, StyleSheet, Text, View } from "react-native";
import Svg, { Defs, LinearGradient as SvgGradient, Path, Stop } from "react-native-svg";
import { useSvgId } from "../svgIds";
import { C, T } from "../theme";

const AnimatedPath = Animated.createAnimatedComponent(Path);

/** Buduje ścieżkę linii i ścieżkę wypełnienia dla serii wartości. */
function build(values: number[], w: number, h: number, pad = 2) {
  const clean = values.filter((v) => typeof v === "number" && isFinite(v));
  if (clean.length < 2) return { line: "", area: "", min: 0, max: 0 };
  const min = Math.min(...clean);
  const max = Math.max(...clean);
  const span = max - min || 1;
  const stepX = (w - pad * 2) / (clean.length - 1);
  const y = (v: number) => pad + (1 - (v - min) / span) * (h - pad * 2);

  let line = `M${pad},${y(clean[0])}`;
  for (let i = 1; i < clean.length; i++) {
    line += `L${pad + i * stepX},${y(clean[i])}`;
  }
  const area = `${line}L${pad + (clean.length - 1) * stepX},${h}L${pad},${h}Z`;
  return { line, area, min, max };
}

/** Iskierka do wiersza listy — bez osi, bez podpisów, sam kształt. */
export function Sparkline({
  values, width = 74, height = 26, color,
}: { values: number[]; width?: number; height?: number; color?: string }) {
  if (!values || values.length < 2) {
    return <View style={{ width, height }} />;
  }
  const up = values[values.length - 1] >= values[0];
  const stroke = color || (up ? C.green : C.red);
  const { line, area } = build(values, width, height);
  const id = `sp${Math.round(width)}${up ? "u" : "d"}`;

  return (
    <Svg width={width} height={height}>
      <Defs>
        <SvgGradient id={id} x1="0" y1="0" x2="0" y2="1">
          <Stop offset="0" stopColor={stroke} stopOpacity="0.28" />
          <Stop offset="1" stopColor={stroke} stopOpacity="0" />
        </SvgGradient>
      </Defs>
      <Path d={area} fill={`url(#${id})`} />
      <Path d={line} stroke={stroke} strokeWidth={1.6} fill="none"
            strokeLinejoin="round" strokeLinecap="round" />
    </Svg>
  );
}

/** Wykres z podpisami zakresu i miękkim wjazdem linii przy pierwszym pokazaniu. */
export function LineChart({
  values, labels, height = 170, color, fmt, footer,
}: {
  values: number[];
  /** podpisy skrajnych punktów osi X (np. daty) */
  labels?: [string, string];
  height?: number;
  color?: string;
  fmt?: (v: number) => string;
  footer?: string;
}) {
  const [w, setW] = React.useState(0);
  const grow = useRef(new Animated.Value(0)).current;
  // własna nazwa gradientu: na jednym ekranie potrafi stać kilka takich wykresów,
  // a wspólne `id` sprawiało, że wszystkie brały wypełnienie tego pierwszego
  const fill = useSvgId("lc");

  useEffect(() => {
    grow.setValue(0);
    Animated.timing(grow, {
      toValue: 1, duration: 700, easing: Easing.out(Easing.cubic), useNativeDriver: true,
    }).start();
  }, [values.length, w]);

  const clean = (values || []).filter((v) => typeof v === "number" && isFinite(v));
  if (clean.length < 2) {
    return (
      <View style={[s.empty, { height }]}>
        <Text style={s.emptyTxt}>Brak danych do wykresu</Text>
      </View>
    );
  }

  const up = clean[clean.length - 1] >= clean[0];
  const stroke = color || (up ? C.green : C.red);
  const { line, area, min, max } = build(clean, w || 1, height - 22, 4);
  const show = fmt || ((v: number) => v.toLocaleString("pl-PL", { maximumFractionDigits: 2 }));

  return (
    <View onLayout={(e) => setW(e.nativeEvent.layout.width)}>
      <View style={{ height: height - 22 }}>
        {w > 0 && (
          <Svg width={w} height={height - 22}>
            <Defs>
              <SvgGradient id={fill} x1="0" y1="0" x2="0" y2="1">
                <Stop offset="0" stopColor={stroke} stopOpacity="0.24" />
                <Stop offset="1" stopColor={stroke} stopOpacity="0" />
              </SvgGradient>
            </Defs>
            <AnimatedPath d={area} fill={`url(#${fill})`} opacity={grow as any} />
            <Path d={line} stroke={stroke} strokeWidth={2} fill="none"
                  strokeLinejoin="round" strokeLinecap="round" />
          </Svg>
        )}
        {/* skrajne wartości w rogach — tanio zastępują pełną oś Y */}
        <Text style={[s.axis, { top: 0 }]}>{show(max)}</Text>
        <Text style={[s.axis, { bottom: 0 }]}>{show(min)}</Text>
      </View>
      <View style={s.labels}>
        <Text style={s.label}>{labels?.[0] || ""}</Text>
        <Text style={s.label}>{footer || ""}</Text>
        <Text style={s.label}>{labels?.[1] || ""}</Text>
      </View>
    </View>
  );
}

/** Kilka serii na jednej osi, każda znormalizowana do 100 — do porównywarki. */
export function MultiLineChart({
  series, colors, height = 190, labels,
}: {
  series: Record<string, number[]>;
  colors: Record<string, string>;
  height?: number;
  labels?: [string, string];
}) {
  const [w, setW] = React.useState(0);
  const keys = Object.keys(series).filter((k) => (series[k] || []).length > 1);
  if (!keys.length) {
    return <View style={[s.empty, { height }]}><Text style={s.emptyTxt}>Brak wspólnej historii</Text></View>;
  }

  const all = keys.flatMap((k) => series[k]);
  const min = Math.min(...all);
  const max = Math.max(...all);
  const span = max - min || 1;
  const h = height - 22;

  const path = (vals: number[]) => {
    const step = (w - 8) / (vals.length - 1);
    return vals.map((v, i) =>
      `${i ? "L" : "M"}${4 + i * step},${4 + (1 - (v - min) / span) * (h - 8)}`).join("");
  };

  return (
    <View onLayout={(e) => setW(e.nativeEvent.layout.width)}>
      <View style={{ height: h }}>
        {w > 0 && (
          <Svg width={w} height={h}>
            {keys.map((k) => (
              <Path key={k} d={path(series[k])} stroke={colors[k] || C.accent} strokeWidth={1.9}
                    fill="none" strokeLinejoin="round" strokeLinecap="round" />
            ))}
          </Svg>
        )}
        <Text style={[s.axis, { top: 0 }]}>{Math.round(max)}</Text>
        <Text style={[s.axis, { bottom: 0 }]}>{Math.round(min)}</Text>
      </View>
      <View style={s.labels}>
        <Text style={s.label}>{labels?.[0] || ""}</Text>
        <Text style={s.label}>wszystko od 100 w punkcie startu</Text>
        <Text style={s.label}>{labels?.[1] || ""}</Text>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  empty: { alignItems: "center", justifyContent: "center" },
  emptyTxt: { color: C.dim, ...T.small },
  axis: {
    position: "absolute", right: 2, color: C.dim, fontSize: 10, fontWeight: "700",
    backgroundColor: "rgba(20,25,38,.75)", paddingHorizontal: 4, borderRadius: 4,
    overflow: "hidden",
  },
  labels: {
    flexDirection: "row", justifyContent: "space-between", alignItems: "center",
    marginTop: 6, gap: 8,
  },
  label: { color: C.dim, fontSize: 10.5, flexShrink: 1 },
});
