/** Sterowanie botem — START/STOP, parametry analizy i źródła newsów. */
import React, { useState } from "react";
import { ActivityIndicator, StyleSheet, Switch, Text, View } from "react-native";
import { BotState, setParams, startBot, stopBot } from "../../api";
import { useAuth } from "../../auth/AuthContext";
import { C, plural, T } from "../../theme";
import { Card, FadeIn, MetalButton, Press, SectionTitle } from "../../ui";

/** Suwaki liczbowe — zmieniamy przyciskami +/−, bo na telefonie to najpewniejsze. */
const NUMBERS: { key: string; label: string; desc: string; min: number; max: number; step: number; unit?: string }[] = [
  { key: "min_signal_strength", label: "Próg siły wydźwięku", min: 0, max: 100, step: 5,
    desc: "Poniżej tej wartości news jest pomijany. Wyżej = mniej, ale wyraźniejszych analiz." },
];

const TOGGLES: { key: string; label: string; desc: string }[] = [
  { key: "verify_enabled", label: "Druga opinia",
    desc: "Mocniejszy (płatny) model sprawdza rzetelność analizy." },
  { key: "thematic_enabled", label: "Analizy tematyczne",
    desc: "Newsy o całej branży, nie o jednej spółce." },
  { key: "macro_enabled", label: "Analizy makro",
    desc: "Decyzje banków centralnych, dane makro, wojny handlowe." },
];

export default function ControlTab({
  st, reload,
}: { st: BotState; reload: () => Promise<void> }) {
  const { me } = useAuth();
  /** Nasłuch jest JEDEN na cały serwer, więc jego włącznik należy do właściciela —
   *  serwer i tak odpowie 403 komuś innemu (`require_owner`). Pokazywanie przycisku,
   *  który zawsze kończy się błędem, byłoby gorsze niż jego brak, więc reszta widzi
   *  sam stan: informację, a nie martwy guzik. */
  const wlasciciel = Boolean(me?.owner);

  const [busy, setBusy] = useState("");
  const p = st.params || {};
  const running = st.bot_alive;

  async function act(name: string, fn: () => Promise<any>) {
    setBusy(name);
    try { await fn(); await reload(); } finally { setBusy(""); }
  }

  const patch = (updates: Record<string, any>) => act("param", () => setParams(updates));

  /* Parametry są WSPÓLNE dla całego serwera — jeden plik, jeden nasłuch dla
     wszystkich. Serwer pilnuje tego od teraz na serio (`require_owner` przy
     `/api/params`), więc komuś innemu każdy suwak kończyłby się błędem 403.
     Zamiast dawać martwe kontrolki, pokazujemy sam stan: informację, nie guzik. */

  return (
    <View>
      {/* ---- główny włącznik ---- */}
      <FadeIn>
        <Card style={s.powerCard}>
          <Text style={s.powerLabel}>Nasłuch newsów</Text>
          {wlasciciel ? (
            <Press
              style={[s.power, running ? s.powerStop : s.powerStart]}
              disabled={Boolean(busy)}
              onPress={() => act("power", () => (running ? stopBot() : startBot()))}
            >
              {busy === "power"
                ? <ActivityIndicator color={running ? "#fff" : "#04140c"} />
                : <Text style={[s.powerTxt, { color: running ? "#fff" : "#04140c" }]}>
                    {running ? "■  ZATRZYMAJ" : "▶  START"}
                  </Text>}
            </Press>
          ) : (
            <Text style={s.powerInfo}>
              Nasłuch działa po stronie serwera i jest wspólny dla wszystkich —
              włącza go i zatrzymuje wyłącznie właściciel usługi.
            </Text>
          )}

          <View style={s.ledRow}>
            <View style={[s.led, { backgroundColor: running ? C.green : C.dim }]} />
            <Text style={s.ledTxt}>
              {running ? "Bot nasłuchuje" : "Bot zatrzymany"}
              {st.bot_status?.cycles ? `  ·  ${st.bot_status.cycles} cykli` : ""}
            </Text>
          </View>
          {!!st.bot_status?.last_error && (
            <Text style={s.err} numberOfLines={2}>Ostatni błąd: {st.bot_status.last_error}</Text>
          )}
        </Card>
      </FadeIn>

      {/* ---- parametry liczbowe ---- */}
      <SectionTitle hint={wlasciciel
        ? "Zmiany zapisują się natychmiast i działają od następnej analizy"
        : "Te ustawienia są wspólne dla całego serwera — zmienia je właściciel usługi"}>
        Parametry analizy
      </SectionTitle>
      {NUMBERS.map((n, i) => {
        const val = Number(p[n.key] ?? 0);
        return (
          <FadeIn key={n.key} delay={Math.min(i * 22, 200)} offset={8}>
            <Card style={s.numCard}>
              <View style={s.rowBetween}>
                <Text style={s.rowLabel}>{n.label}</Text>
                <View style={s.stepper}>
                  {wlasciciel && (
                    <MetalButton size="sm" round label="−" textStyle={{ fontSize: 17 }}
                                 onPress={() => patch({ [n.key]: Math.max(n.min, +(val - n.step).toFixed(2)) })} />
                  )}
                  <Text style={s.numVal}>
                    {val.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}{n.unit || ""}
                  </Text>
                  {wlasciciel && (
                    <MetalButton size="sm" round label="+" textStyle={{ fontSize: 17 }}
                                 onPress={() => patch({ [n.key]: Math.min(n.max, +(val + n.step).toFixed(2)) })} />
                  )}
                </View>
              </View>
              <Text style={s.rowDesc}>{n.desc}</Text>
            </Card>
          </FadeIn>
        );
      })}

      {/* ---- przełączniki strategii ---- */}
      <SectionTitle>Strategia</SectionTitle>
      {TOGGLES.map((t, i) => (
        <FadeIn key={t.key} delay={Math.min(i * 22, 180)} offset={8}>
          <Card style={s.numCard}>
            <View style={s.rowBetween}>
              <View style={{ flex: 1, paddingRight: 12 }}>
                <Text style={s.rowLabel}>{t.label}</Text>
                <Text style={s.rowDesc}>{t.desc}</Text>
              </View>
              <Switch
                value={Boolean(p[t.key])}
                disabled={!wlasciciel}
                onValueChange={(v) => patch({ [t.key]: v })}
                trackColor={{ false: "#2a3247", true: "rgba(47,212,138,.45)" }}
                thumbColor={p[t.key] ? C.green : "#fff"}
              />
            </View>
          </Card>
        </FadeIn>
      ))}

    </View>
  );
}

const s = StyleSheet.create({
  powerCard: { padding: 16 },
  powerLabel: { color: C.muted, ...T.micro, textTransform: "uppercase", marginBottom: 12 },
  power: { borderRadius: 15, paddingVertical: 19, alignItems: "center" },
  powerStart: { backgroundColor: C.green },
  powerStop: { backgroundColor: C.red },
  powerTxt: { fontSize: 17, fontWeight: "800", letterSpacing: 0.6 },
  powerInfo: { color: C.muted, fontSize: 12.5, lineHeight: 18.5 },
  ledRow: { flexDirection: "row", alignItems: "center", gap: 9, marginTop: 14 },
  led: { width: 9, height: 9, borderRadius: 5 },
  ledTxt: { color: C.muted, fontSize: 12.5, fontWeight: "600" },
  err: { color: C.red, fontSize: 11.5, marginTop: 8 },

  rowBetween: { flexDirection: "row", alignItems: "center", justifyContent: "space-between" },
  rowLabel: { color: C.text, fontSize: 14, fontWeight: "700" },
  rowDesc: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 4 },

  numCard: { padding: 14, marginBottom: 8 },
  stepper: { flexDirection: "row", alignItems: "center", gap: 4 },
  stepBtn: {
    width: 34, height: 34, borderRadius: 10, backgroundColor: C.elev,
    borderWidth: 1, borderColor: C.border2, alignItems: "center", justifyContent: "center",
  },
  stepTxt: { color: C.text, fontSize: 18, fontWeight: "800", lineHeight: 21 },
  numVal: {
    color: C.text, fontSize: 14, fontWeight: "800", minWidth: 58, textAlign: "center",
  },
});
