/** Kalkulator dochodu z dywidend — ile realnie wpłynie na konto i po ilu latach.
 *
 *  Liczy na koszyku wybranym w skanerze albo na ręcznie wpisanej stopie, więc
 *  działa też dla kogoś, kto dopiero się rozgląda i nie ma jeszcze żadnej spółki.
 *
 *  Model **jawnie zakłada stały kurs akcji** i jest to napisane na ekranie, a nie
 *  schowane w gwiazdce. Dorzucenie wzrostu kursu robi ładniejsze liczby, ale
 *  wtedy wynik zależy głównie od zmyślonego założenia o rynku, a nie od
 *  dywidendy — a to jest kalkulator dywidendy, nie prognoza portfela.
 */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, Text, TextInput, View,
} from "react-native";
import { DywProjekcja, DywRow, liczDyw } from "../../../api";
import { C, T } from "../../../theme";
import { Card } from "../../../ui";
import { Akapit, Kafel, kwota2, pln, proc, Wyjasnienie } from "./shared";

import Icon from "../../../ui/Icon";
export default function Kalkulator({ koszyk, usunZKoszyka }: {
  koszyk: DywRow[];
  usunZKoszyka: (symbol: string) => void;
}) {
  const [kwota, setKwota] = useState("50000");
  const [doplata, setDoplata] = useState("0");
  const [lat, setLat] = useState(15);
  const [reinwestycja, setReinwestycja] = useState(true);
  const [w8ben, setW8ben] = useState(true);
  const [recznaStopa, setRecznaStopa] = useState("5");
  const [recznyWzrost, setRecznyWzrost] = useState("5");
  const [wynik, setWynik] = useState<DywProjekcja | null>(null);
  const [laduje, setLaduje] = useState(false);
  const [blad, setBlad] = useState("");

  const licz = useCallback(async () => {
    setLaduje(true);
    setBlad("");
    try {
      const body: any = {
        kwota: Number(kwota.replace(/\s/g, "").replace(",", ".")) || 0,
        doplata_roczna: Number(doplata.replace(/\s/g, "").replace(",", ".")) || 0,
        lat, reinwestycja, w8ben,
      };
      if (koszyk.length) {
        // Równy podział między wybrane aktywa. Suwaki udziałów byłyby ładne,
        // ale przy czterech pozycjach to cztery kolejne decyzje przed
        // zobaczeniem pierwszej liczby — a chodzi o to, żeby wynik pojawił się
        // od razu i dopiero potem dało się go dopieszczać.
        body.koszyk = koszyk.map((k) => ({ symbol: k.symbol, udzial: 1 }));
      } else {
        body.stopa = Number(recznaStopa.replace(",", ".")) || 0;
        body.wzrost = Number(recznyWzrost.replace(",", ".")) || 0;
        body.rynek = "GPW";
      }
      setWynik(await liczDyw(body));
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się policzyć");
    } finally {
      setLaduje(false);
    }
  }, [kwota, doplata, lat, reinwestycja, w8ben, koszyk, recznaStopa, recznyWzrost]);

  useEffect(() => { const t = setTimeout(licz, 300); return () => clearTimeout(t); }, [licz]);

  return (
    <View style={{ gap: 12 }}>
      <Card>
        <Text style={st.tytul}>Na czym liczymy</Text>
        {koszyk.length > 0 ? (
          <>
            <Text style={st.podtytul}>
              {koszyk.length} {koszyk.length === 1 ? "aktywo" : "aktywa"} ze skanera,
              podzielone po równo
            </Text>
            <View style={{ gap: 7, marginTop: 9 }}>
              {koszyk.map((k) => (
                <View key={k.symbol} style={st.koszykWiersz}>
                  <Text style={st.koszykNazwa} numberOfLines={1}>{k.nazwa}</Text>
                  <Text style={st.koszykStopa}>{proc(k.stopa)}</Text>
                  <Pressable onPress={() => usunZKoszyka(k.symbol)} hitSlop={8}>
                    <Icon name="zamknij" size={13} color={C.dim} />
                  </Pressable>
                </View>
              ))}
            </View>
          </>
        ) : (
          <>
            <Text style={st.podtytul}>
              Nie wybrałeś jeszcze aktywów — licz na własnych założeniach albo
              dodaj spółki plusem w skanerze
            </Text>
            <View style={st.dwaPola}>
              <Pole etykieta="Stopa dywidendy" wartosc={recznaStopa}
                    zmien={setRecznaStopa} sufiks="%" />
              <Pole etykieta="Roczny wzrost wypłaty" wartosc={recznyWzrost}
                    zmien={setRecznyWzrost} sufiks="%" />
            </View>
          </>
        )}
      </Card>

      <Card>
        <View style={st.dwaPola}>
          <Pole etykieta="Wpłata na start" wartosc={kwota} zmien={setKwota} sufiks="zł" />
          <Pole etykieta="Dopłata co roku" wartosc={doplata} zmien={setDoplata} sufiks="zł" />
        </View>

        <Text style={st.grupa}>Na ile lat</Text>
        <ScrollView horizontal showsHorizontalScrollIndicator={false}
                    contentContainerStyle={{ gap: 7 }}>
          {[5, 10, 15, 20, 30].map((v) => (
            <Pressable key={v} onPress={() => setLat(v)}
                       style={[st.lataBtn, lat === v && st.lataBtnOn]}>
              <Text style={[st.lataTxt, lat === v && { color: C.green }]}>{v} lat</Text>
            </Pressable>
          ))}
        </ScrollView>

        <View style={st.przelacznik}>
          <View style={{ flex: 1 }}>
            <Text style={st.przTytul}>Reinwestuję dywidendy</Text>
            <Text style={st.przOpis}>Wypłaty wracają na rynek i same zaczynają pracować</Text>
          </View>
          <Switch value={reinwestycja} onValueChange={setReinwestycja}
                  trackColor={{ true: C.green, false: C.border2 }} />
        </View>

        <View style={st.przelacznik}>
          <View style={{ flex: 1 }}>
            <Text style={st.przTytul}>Mam złożony formularz W-8BEN</Text>
            <Text style={st.przOpis}>
              Bez niego z dywidend z USA schodzi 30% zamiast 15% i nadwyżki się nie odzyska
            </Text>
          </View>
          <Switch value={w8ben} onValueChange={setW8ben}
                  trackColor={{ true: C.green, false: C.border2 }} />
        </View>
      </Card>

      {laduje && <ActivityIndicator color={C.green} />}
      {!!blad && <Text style={st.blad}>{blad}</Text>}

      {wynik && (
        <>
          <View style={st.kafle}>
            <Kafel etykieta="Miesięcznie w ostatnim roku"
                   wartosc={pln(wynik.miesiecznie_ostatni_rok)}
                   nota="po podatku" kolor={C.green} />
            <Kafel etykieta="Suma dywidend netto" wartosc={pln(wynik.suma_netto)}
                   nota={`przez ${wynik.zalozenia.lat} lat`} />
            <Kafel etykieta="Yield on cost na końcu"
                   wartosc={proc(wynik.yield_on_cost_koncowy)}
                   nota="względem własnych wpłat" kolor={C.accent} />
            <Kafel etykieta="Podatek zapłacony" wartosc={pln(wynik.suma_podatku)}
                   nota="Belka i podatek u źródła" kolor={C.amber} />
          </View>

          <Card>
            <Text style={st.tytul}>Rok po roku</Text>
            <Text style={st.podtytul}>
              Stopa startowa {proc(wynik.stopa_koszyka)}, wzrost wypłaty{" "}
              {proc(wynik.wzrost_koszyka)} rocznie
            </Text>
            <View style={st.wykres}>
              {(() => {
                const maks = Math.max(...wynik.wiersze.map((w) => w.netto), 1);
                const krok = Math.max(1, Math.ceil(wynik.wiersze.length / 16));
                return wynik.wiersze.filter((_, i) => i % krok === 0 || i === wynik.wiersze.length - 1)
                  .map((w) => (
                    <View key={w.rok} style={st.slupekWrap}>
                      <View style={[st.slupek, { height: Math.max(3, (w.netto / maks) * 100) }]} />
                      <Text style={st.slupekEt}>{w.rok}</Text>
                    </View>
                  ));
              })()}
            </View>

            <View style={st.tabelaGlowa}>
              <Text style={[st.kom, st.komRok]}>Rok</Text>
              <Text style={[st.kom, st.komLicz]}>Kapitał</Text>
              <Text style={[st.kom, st.komLicz]}>Netto</Text>
              <Text style={[st.kom, st.komLicz]}>YoC</Text>
            </View>
            {wynik.wiersze.map((w) => (
              <View key={w.rok} style={st.tabelaWiersz}>
                <Text style={[st.kom, st.komRok, { color: C.muted }]}>{w.rok}</Text>
                <Text style={[st.kom, st.komLicz]}>{pln(w.kapital)}</Text>
                <Text style={[st.kom, st.komLicz, { color: C.green }]}>{pln(w.netto)}</Text>
                <Text style={[st.kom, st.komLicz, { color: C.accent }]}>{proc(w.yield_on_cost)}</Text>
              </View>
            ))}
          </Card>

          <Card>
            <View style={st.uwaga}>
              <Text style={st.uwagaTxt}>
                Rachunek zakłada, że <Text style={st.mocny}>kurs akcji się nie zmienia</Text>.
                To celowe uproszczenie: gdyby doliczyć wzrost kursu, wynik zależałby
                głównie od zgadywania, co zrobi rynek, a nie od samej dywidendy.
              </Text>
            </View>

            <Wyjasnienie tytul="Czym jest yield on cost i dlaczego to najważniejsza liczba tutaj">
              <Akapit>
                Stopa dywidendy w tabelach liczy się od dzisiejszego kursu. Yield
                on cost liczy się od tego, co Ty realnie wydałeś. Jeśli kupiłeś
                spółkę dziesięć lat temu przy stopie 3%, a od tego czasu podnosiła
                wypłatę o 7% rocznie, to dziś dostajesz około 6% swojego wkładu —
                choć w każdej tabeli widnieje przy niej wciąż skromne 3%.
              </Akapit>
              <Akapit>
                To jest właśnie mechanizm, dla którego inwestowanie dywidendowe
                ma sens w długim terminie: rośnie nie kurs w Twojej głowie, tylko
                strumień gotówki względem raz wydanych pieniędzy.
              </Akapit>
            </Wyjasnienie>

            <Wyjasnienie tytul="Ile realnie zabiera podatek">
              <Akapit>
                Od dywidend ze spółek z GPW płacisz 19% podatku Belki i to koniec
                sprawy. Przy spółkach amerykańskich broker oddaje najpierw 15%
                fiskusowi w USA (o ile masz podpisany formularz W-8BEN),
                a w Polsce dopłacasz różnicę do 19% — łącznie tyle samo, tylko
                rozbite na dwa kraje.
              </Akapit>
              <Akapit>
                Bez W-8BEN u źródła schodzi 30% i tej nadwyżki nie odzyskasz
                zwykłym rozliczeniem. Formularz podpisuje się raz, u brokera,
                i to jest jedna z niewielu rzeczy w inwestowaniu, gdzie pięć
                minut papierkowej roboty daje pewne kilkanaście procent więcej.
              </Akapit>
              <Akapit>
                To wyliczenie orientacyjne, a nie porada podatkowa — Portevo nie
                jest doradcą podatkowym ani inwestycyjnym.
              </Akapit>
            </Wyjasnienie>

            <Wyjasnienie tytul="Dlaczego reinwestycja zmienia tak dużo">
              <Akapit>
                Wypłacona dywidenda, która leży na rachunku, jest jednorazowym
                zastrzykiem. Ta sama dywidenda zamieniona z powrotem na akcje
                zaczyna sama płacić dywidendę w kolejnym roku — i tak dalej.
                Przy piętnastu latach różnica między tymi dwoma trybami bywa
                większa niż całość pierwszej wpłaty.
              </Akapit>
              <Akapit>
                Przełącz reinwestycję i porównaj sumę netto — to jest chyba
                najbardziej przekonujący argument, jaki ten kalkulator ma
                do zaoferowania.
              </Akapit>
            </Wyjasnienie>
          </Card>
        </>
      )}
    </View>
  );
}

function Pole({ etykieta, wartosc, zmien, sufiks }: {
  etykieta: string; wartosc: string; zmien: (v: string) => void; sufiks?: string;
}) {
  return (
    <View style={{ flex: 1, minWidth: 130 }}>
      <Text style={st.poleEt}>{etykieta}</Text>
      <View style={st.poleWrap}>
        <TextInput value={wartosc} onChangeText={zmien} keyboardType="numeric"
                   style={st.pole} placeholderTextColor={C.dim} />
        {!!sufiks && <Text style={st.poleSufiks}>{sufiks}</Text>}
      </View>
    </View>
  );
}

const st = StyleSheet.create({
  tytul: { ...T.body, color: C.text, fontWeight: "700" },
  podtytul: { ...T.micro, color: C.dim, marginTop: 3 },
  grupa: { ...T.micro, color: C.dim, textTransform: "uppercase",
           letterSpacing: 0.5, marginTop: 14, marginBottom: 7 },
  dwaPola: { flexDirection: "row", flexWrap: "wrap", gap: 10, marginTop: 10 },
  poleEt: { ...T.micro, color: C.dim, marginBottom: 5 },
  poleWrap: {
    flexDirection: "row", alignItems: "center", backgroundColor: C.elev,
    borderWidth: 1, borderColor: C.border, borderRadius: 10, paddingHorizontal: 11,
  },
  pole: { flex: 1, ...T.body, color: C.text, fontSize: 17, paddingVertical: 10 },
  poleSufiks: { ...T.small, color: C.dim },
  lataBtn: {
    paddingHorizontal: 13, paddingVertical: 8, borderRadius: 999,
    borderWidth: 1, borderColor: C.border2, backgroundColor: C.card,
  },
  lataBtnOn: { borderColor: C.green, backgroundColor: C.greenDim },
  lataTxt: { ...T.small, color: C.muted, fontWeight: "600" },
  przelacznik: {
    flexDirection: "row", alignItems: "center", gap: 12, marginTop: 15,
    borderTopWidth: 1, borderTopColor: C.border, paddingTop: 13,
  },
  przTytul: { ...T.small, color: C.text, fontWeight: "700" },
  przOpis: { ...T.micro, color: C.dim, marginTop: 2, lineHeight: 15 },
  koszykWiersz: { flexDirection: "row", alignItems: "center", gap: 10 },
  koszykNazwa: { ...T.small, color: C.text, flex: 1 },
  koszykStopa: { ...T.body, color: C.green, fontWeight: "700" },
  usun: { ...T.body, color: C.dim, paddingHorizontal: 4 },
  kafle: { flexDirection: "row", flexWrap: "wrap", gap: 9 },
  blad: { ...T.small, color: C.red },
  wykres: { flexDirection: "row", alignItems: "flex-end", gap: 3,
            height: 118, marginTop: 14, marginBottom: 8 },
  slupekWrap: { flex: 1, alignItems: "center", gap: 4 },
  slupek: { width: "76%", backgroundColor: C.green, borderRadius: 3, opacity: 0.85 },
  slupekEt: { ...T.micro, color: C.dim, fontSize: 9 },
  tabelaGlowa: {
    flexDirection: "row", borderBottomWidth: 1, borderBottomColor: C.border2,
    paddingBottom: 6, marginTop: 8,
  },
  tabelaWiersz: {
    flexDirection: "row", borderBottomWidth: 1, borderBottomColor: C.border,
    paddingVertical: 7,
  },
  kom: { ...T.micro, color: C.text },
  komRok: { width: 34 },
  komLicz: { flex: 1, textAlign: "right", ...T.body, fontSize: 12 },
  uwaga: {
    backgroundColor: "rgba(255,180,84,.09)", borderLeftWidth: 3,
    borderLeftColor: C.amber, borderRadius: 8, padding: 11,
  },
  uwagaTxt: { ...T.small, color: C.muted, lineHeight: 19 },
  mocny: { color: C.text, fontWeight: "700" },
});
