/** Alokacja — jak portfel dzieli się na klasy aktywów, rynki, sektory, waluty i spółki. */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, RefreshControl, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { Allocation, getAllocation } from "../api";
import { BrandFooter } from "../components/Brand";
import Donut from "../components/Donut";
import { PreviewBanner, StalePanelBanner } from "../components/PremiumGate";
import { usePortfolioVersion } from "../refresh";
import { C, chartColor, fmtPLN, plColor, plural, sgnPLN, T } from "../theme";
import {
  Bar, Card, FadeIn, LiquidButton, MetalButton, Press, RefreshButton, SectionTitle, Segmented,
} from "../ui";
import AllocationPro from "./allocation/ProSections";
import { TAB_SPACE } from "../layout";

const BY = [
  { id: "asset_class", label: "Klasa", hint: "Akcje, ETF-y, gotówka — najważniejszy podział dla ryzyka portfela." },
  { id: "market", label: "Rynek", hint: "Gdzie notowane są Twoje spółki. Duża przewaga jednego rynku to ryzyko walutowe i regulacyjne." },
  { id: "sector", label: "Sektor", hint: "Branże, w które inwestujesz. Skupienie w jednym sektorze zwiększa wahania portfela." },
  { id: "currency", label: "Waluta", hint: "W jakich walutach trzymasz kapitał — stąd wynika Twoja ekspozycja na kurs złotego." },
  { id: "position", label: "Spółka", hint: "Udział pojedynczych pozycji. Zdrowy portfel rzadko ma jedną pozycję ponad 20%." },
];

export default function AllocationScreen() {
  const [by, setBy] = useState("asset_class");
  const [data, setData] = useState<Allocation | null>(null);
  const [sel, setSel] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const load = useCallback(async (b: string) => {
    setErr("");
    try {
      setData(await getAllocation(b));
    } catch (e: any) {
      setErr(e?.message || "Błąd połączenia");
    } finally {
      setLoading(false);
      setBusy(false);
    }
  }, []);

  // `wersja` rośnie po wgraniu raportu i po zmianie zalogowanego konta. Ten ekran
  // liczył alokację raz i zostawał z wynikiem — po wgraniu pierwszego raportu dalej
  // pokazywał „Brak danych portfela", bo policzył ją, gdy portfel był jeszcze pusty.
  const wersja = usePortfolioVersion();
  useEffect(() => { setSel(null); load(by); }, [by, wersja]);

  if (loading) {
    return <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>;
  }
  if (err) {
    return (
      <View style={s.center}>
        <Text style={s.errTitle}>{err}</Text>
        <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 220 }}
                      onPress={() => { setLoading(true); load(by); }} />
      </View>
    );
  }
  // Pusto = najczęściej „raport jeszcze nie wgrany" albo „wgrany przed chwilą,
  // a ten ekran policzył się wcześniej". Sam napis bez wyjścia był ślepą uliczką:
  // gestu „pociągnij, żeby odświeżyć" w przeglądarce nie ma jak wykonać.
  if (data?.empty) {
    return (
      <View style={s.center}>
        <Text style={s.dim}>Brak danych portfela.</Text>
        <Text style={s.dimSmall}>
          Wgraj raport w zakładce Przegląd albo w „Więcej". Jeśli właśnie to zrobiłeś —
          odśwież.
        </Text>
        <LiquidButton label="Odśwież" full={false} style={{ minWidth: 200 }}
                      onPress={() => { setLoading(true); load(by); }} />
      </View>
    );
  }

  const groups = data!.groups;
  const meta = BY.find((b) => b.id === by)!;
  const top = groups[0];
  const conc = groups.slice(0, 3).reduce((a, g) => a + g.pct, 0);
  // ostrzeżenie o koncentracji ma sens dopiero, gdy grup jest więcej niż trzy —
  // przy trzech „100% w trzech grupach" jest prawdą trywialną
  const showConc = groups.length > 3;

  return (
    <ScrollView
      contentContainerStyle={s.wrap}
      showsVerticalScrollIndicator={false}
      refreshControl={
        <RefreshControl refreshing={busy} tintColor={C.green}
                        onRefresh={() => { setBusy(true); load(by); }} />
      }
    >
      <FadeIn>
        <View style={s.titleRow}>
          <View style={{ flex: 1 }}>
            <Text style={s.h1}>Alokacja</Text>
            <Text style={s.sub}>Z czego naprawdę składa się Twój portfel</Text>
          </View>
          <RefreshButton busy={busy} onPress={() => { setBusy(true); load(by); }} />
        </View>
      </FadeIn>

      <FadeIn delay={70}>
        <View style={{ marginTop: 16 }}>
          <Segmented options={BY} value={by} onChange={setBy} />
        </View>
        <Text style={s.hint}>{meta.hint}</Text>
      </FadeIn>

      <FadeIn delay={130}>
        <Card style={{ marginTop: 14, paddingVertical: 22 }}>
          <Donut
            slices={groups.map((g) => ({ label: g.label, value: g.value, pct: g.pct }))}
            selected={sel} onSelect={setSel}
            centerLabel="Wartość portfela" centerValue={fmtPLN(data!.total)}
          />
          <Text style={s.donutHint}>
            {sel == null ? "Dotknij wycinka, aby zobaczyć szczegóły" : "Dotknij ponownie, aby odznaczyć"}
          </Text>
        </Card>
      </FadeIn>

      <FadeIn delay={190}>
        <View style={s.insight}>
          <Text style={s.insightTxt}>
            Największa część to <Text style={s.b}>{top.label}</Text> —{" "}
            <Text style={s.b}>{top.pct.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}%</Text>
            {" "}portfela.
            {showConc && (
              <>
                {" "}Trzy największe grupy to razem{" "}
                <Text style={s.b}>{conc.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}%</Text>.
                {conc > 75 ? " To spora koncentracja — warto rozważyć szersze rozłożenie kapitału." : ""}
              </>
            )}
            {groups.length <= 3 && ` Portfel dzieli się na ${groups.length} ${plural(groups.length, "grupę", "grupy", "grup")}.`}
          </Text>
        </View>
      </FadeIn>

      <FadeIn delay={220}>
        <Card style={{ marginTop: 14 }}>
          <Text style={s.paskiTytul}>Wszystkie grupy naraz</Text>
          <Text style={s.paskiOpis}>
            Pierścień pokazuje proporcje, ale porównanie dwóch podobnych wycinków
            wymaga mrużenia oczu. Tu każda grupa ma własną linię, więc różnice
            widać od razu — i nie trzeba przewijać kart poniżej, żeby zobaczyć całość.
          </Text>
          <View style={{ marginTop: 12, gap: 8 }}>
            {groups.map((g, i) => (
              <Press key={g.label} onPress={() => setSel(sel === i ? null : i)} scaleTo={0.99}>
                <View style={[s.paskiRzad, sel === i && s.paskiRzadOn]}>
                  <Text style={s.paskiNazwa} numberOfLines={1}>{g.label}</Text>
                  <View style={s.paskiTor}>
                    {/* Skala jest względem NAJWIĘKSZEJ grupy, nie względem 100% —
                        przy portfelu rozbitym na kilkanaście pozycji wszystkie
                        paski liczone do stu byłyby ledwo widocznymi kreskami
                        i wykres nie mówiłby nic. */}
                    <View style={[s.paskiWypelnienie, {
                      width: `${Math.max(1.5, (g.pct / Math.max(...groups.map((x) => x.pct))) * 100)}%`,
                      backgroundColor: chartColor(i),
                    }]} />
                  </View>
                  <Text style={s.paskiProc}>
                    {g.pct.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}%
                  </Text>
                </View>
              </Press>
            ))}
          </View>
        </Card>
      </FadeIn>

      <SectionTitle hint="Wynik pokazuje zysk lub stratę na otwartych pozycjach w danej grupie">
        Szczegóły
      </SectionTitle>

      {groups.map((g, i) => (
        <FadeIn key={g.label} delay={Math.min(i * 26, 300)} offset={10}>
          <Press onPress={() => setSel(sel === i ? null : i)} scaleTo={0.985}>
            <Card style={[s.rowCard, sel === i && s.rowCardOn]}>
              <View style={s.rowTop}>
                <View style={[s.dot, { backgroundColor: chartColor(i) }]} />
                <Text style={s.rowLabel} numberOfLines={1}>{g.label}</Text>
                <Text style={s.rowPct}>
                  {g.pct.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}%
                </Text>
              </View>
              <View style={{ marginTop: 9 }}>
                <Bar pct={g.pct} color={chartColor(i)} delay={i * 40} />
              </View>
              <View style={s.rowBottom}>
                <Text style={s.rowValue}>{fmtPLN(g.value)}</Text>
                <Text style={s.rowMeta}>
                  {g.count > 0
                    ? `${g.count} ${plural(g.count, "pozycja", "pozycje", "pozycji")}`
                    : "wolne środki"}
                  {g.pl !== 0 && (
                    <Text style={{ color: plColor(g.pl) }}>   {sgnPLN(g.pl)}</Text>
                  )}
                </Text>
              </View>
              {sel === i && g.tickers.length > 0 && (
                <Text style={s.tickers}>{g.tickers.join("  ·  ")}</Text>
              )}
            </Card>
          </Press>
        </FadeIn>
      ))}

      <View style={{ marginTop: 22 }}>
        <StalePanelBanner />
        <PreviewBanner />
      </View>

      <AllocationPro />

      <BrandFooter />
    </ScrollView>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: TAB_SPACE },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 30, gap: 12 },
  dim: { color: C.muted, ...T.body },
  dimSmall: { color: C.dim, fontSize: 12.5, lineHeight: 18, textAlign: "center", maxWidth: 320 },
  titleRow: { flexDirection: "row", alignItems: "flex-start", gap: 10 },
  errTitle: { color: C.text, ...T.h2, textAlign: "center" },
  retry: { backgroundColor: C.green, borderRadius: 13, paddingVertical: 13, paddingHorizontal: 26 },
  retryTxt: { color: "#04140c", fontWeight: "800", fontSize: 15 },

  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginTop: 3 },
  hint: { color: C.dim, fontSize: 12, lineHeight: 17, marginTop: 10, paddingHorizontal: 2 },
  donutHint: { color: C.dim, fontSize: 11.5, textAlign: "center", marginTop: 16 },

  paskiTytul: { color: C.text, fontSize: 14.5, fontWeight: "800" },
  paskiOpis: { color: C.dim, fontSize: 11.5, lineHeight: 16, marginTop: 4 },
  paskiRzad: {
    flexDirection: "row", alignItems: "center", gap: 10,
    paddingVertical: 4, paddingHorizontal: 6, borderRadius: 8,
  },
  paskiRzadOn: { backgroundColor: C.cardHi },
  paskiNazwa: { color: C.muted, fontSize: 11.5, width: 104 },
  paskiTor: { flex: 1, height: 14, backgroundColor: C.elev, borderRadius: 4, overflow: "hidden" },
  paskiWypelnienie: { height: 14, borderRadius: 4 },
  paskiProc: { color: C.text, fontSize: 11.5, fontWeight: "700", width: 48, textAlign: "right" },

  insight: {
    backgroundColor: "rgba(91,140,255,.07)", borderColor: "rgba(91,140,255,.22)",
    borderWidth: 1, borderRadius: 15, padding: 14, marginTop: 14,
  },
  insightTxt: { color: C.muted, fontSize: 13, lineHeight: 20 },
  b: { color: C.text, fontWeight: "800" },

  rowCard: { padding: 14, marginBottom: 9 },
  rowCardOn: { borderColor: C.border2, backgroundColor: C.cardHi },
  rowTop: { flexDirection: "row", alignItems: "center", gap: 9 },
  dot: { width: 9, height: 9, borderRadius: 5 },
  rowLabel: { color: C.text, fontSize: 14, fontWeight: "700", flex: 1 },
  rowPct: { color: C.text, fontSize: 14, fontWeight: "800" },
  rowBottom: {
    flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginTop: 9,
  },
  rowValue: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  rowMeta: { color: C.dim, fontSize: 12 },
  tickers: { color: C.muted, fontSize: 11.5, lineHeight: 18, marginTop: 11 },
});
