export type IconName = keyof typeof R;

/** Czy taki rysunek w ogóle mamy. Serwer podaje nazwy ikon w danych
 *  (`premium.py`, `wealth.py`), a serwer i aplikacja wdrażają się osobno —
 *  nowa nazwa może więc trafić do starszej aplikacji. Wtedy lepiej nie
 *  narysować nic niż wypisać użytkownikowi surowy identyfikator. */
export const maIkone = (n?: string | null): n is IconName => !!n && n in R;

/** Grubość kreski dobrana do rozmiaru.
 *
 *  Włos 1,05 px jest właściwy dla rysunku oglądanego od 24 px w górę. W pasku
 *  zakładek ikona ma 17–19 px, a wtedy ten sam włos po przeskalowaniu robi się
 *  cieńszy niż piksel i gaśnie — szczególnie na ekranach o gęstości 2×, gdzie
 *  ląduje pomiędzy pikselami. Dlatego przy małych rozmiarach kreska rośnie. */
const grubosc = (size: number) => (size >= 26 ? 1.05 : size >= 21 ? 1.2 : 1.35);

export default function Icon({
  name, size = 20, color = C.text, opacity,
}: {
  name: IconName;
  size?: number;
  color?: string;
  /** przygaszenie całej ikony — do stanów nieaktywnych, gdzie zmiana koloru
   *  na `C.dim` zabrałaby jej też charakter kreski */
  opacity?: number;
}) {
  const r = R[name];
  const sw = grubosc(size);

  // Kreskowanie to najcieńszy element rysunku i przy małych rozmiarach zlewa się
  // w szarą plamę, która zamazuje obrys. Poniżej 22 px po prostu go nie ma —
  // ikona zostaje czytelna, a że kreskowanie jest cieniowaniem, a nie treścią,
  // nic przez to nie znika.
  const kreskowanie = size >= 22 && r.hatch?.length ? r.hatch : null;

  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" opacity={opacity}>
      <G
        fill="none"
        stroke={color}
        strokeWidth={sw}
        strokeLinecap="butt"
        strokeLinejoin="miter"
        strokeMiterlimit={6}
      >
        {r.d.map((d, i) => <Path key={i} d={d} />)}
        {kreskowanie && (
          <G strokeWidth={sw * 0.72} opacity={0.55}>
            {kreskowanie.map((d, i) => <Path key={`h${i}`} d={d} />)}
          </G>
        )}
      </G>
    </Svg>
  );
}

/** Ikona, której nazwa przyszła z serwera (katalog premium, klasy majątku).
 *
 *  Serwer i aplikacja wdrażają się osobno, więc katalog może wyprzedzić wersję
 *  aplikacji o funkcję z ikoną, której ta wersja jeszcze nie zna. Wtedy nie
 *  rysujemy nic i nie zostawiamy po ikonie dziury — sąsiedni tekst zajmuje jej
 *  miejsce. Alternatywa, czyli wypisanie nieznanej nazwy, pokazałaby
 *  użytkownikowi identyfikator z kodu. */
export function IkonaZSerwera({
  name, size, color, opacity,
}: { name?: string | null; size?: number; color?: string; opacity?: number }) {
  if (!maIkone(name)) return null;
  return <Icon name={name} size={size} color={color} opacity={opacity} />;
}
