/** Raport spółki przed publikacją wyników.
 *
 *  Ekran odpowiada po kolei na cztery pytania, które zadaje się przed earningsami:
 *    1. Kiedy i o czym — data, pora sesji, ile dni zostało.
 *    2. **Ile potrzeba, żeby pobić prognozę** — konsensus EPS i przychodów wraz
 *       z widełkami analityków; to jest próg, powyżej którego mówi się „beat".
 *    3. Czy ta spółka zwykle pobija — historia zaskoczeń i, co ważniejsze,
 *       jak na nie reagował kurs (pobicie prognozy bywa przecenione).
 *    4. Co się dzieje z biznesem — marże i przychód kwartał po kwartale.
 *
 *  Z dołu można wejść w zwykły profil spółki (`CompanyScreen`) — wykres, wskaźniki,
 *  branża. Świadomie nie duplikujemy tam niczego.
 */
import React, { useEffect, useState } from "react";
import {
  ActivityIndicator, Modal, Platform, SafeAreaView, ScrollView, StatusBar,
  StyleSheet, Text, View,
} from "react-native";
import { EarningsReport, getEarningsReport } from "../../api";
import Logo from "../../components/Logo";
import { C, fmtBig, fmtCur, fmtPct, plColor, T } from "../../theme";
import { Card, ErrorBoundary, FadeIn, MetalButton, Press, SectionTitle, Segmented } from "../../ui";
import { MarginChart, qLabel, SurpriseChart } from "./charts";

import Icon from "../../ui/Icon";
const MARGIN_MODES = [
  { id: "quarterly", label: "Kwartalnie" },
  { id: "annual", label: "Rocznie" },
];

const SESSION: Record<string, string> = {
  bmo: "przed otwarciem sesji",
  amc: "po zamknięciu sesji",
  tbd: "godzina nieogłoszona",
};

/** Ile dni do publikacji — „dziś", „jutro", „za 4 dni", „12 dni temu". */
function daysTo(iso: string): string {
  if (!iso) return "";
  const target = new Date(iso + "T00:00:00");
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const d = Math.round((target.getTime() - today.getTime()) / 86400000);
  if (d === 0) return "dziś";
  if (d === 1) return "jutro";
  if (d === -1) return "wczoraj";
  return d > 0 ? `za ${d} dni` : `${-d} dni temu`;
}

const dateLong = (iso: string) => {
  if (!iso) return "";
  try {
    return new Date(iso + "T00:00:00").toLocaleDateString("pl-PL", {
      weekday: "long", day: "numeric", month: "long",
    });
  } catch { return iso; }
};

export default function ReportModal({
  symbol, time, onClose, onOpenProfile,
}: {
  symbol: string | null;
  /** pora sesji z kalendarza — Yahoo tego nie podaje, więc niesiemy z kafla */
  time?: "bmo" | "amc" | "tbd";
  onClose: () => void;
  onOpenProfile: (symbol: string) => void;
}) {
  const [data, setData] = useState<EarningsReport | null>(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [marginMode, setMarginMode] = useState("quarterly");

  //  `current` pilnuje, żeby odpowiedź dla poprzednio otwartej spółki nie wpadła
  //  do raportu następnej — raporty potrafią schodzić kilka sekund, a w tym czasie
  //  da się zamknąć modal i otworzyć inną spółkę.
  useEffect(() => {
    if (!symbol) return;
    let current = true;
    setLoading(true);
    setData(null);
    setErr("");
    getEarningsReport(symbol)
      .then((d) => { if (current) { d?.error ? setErr(d.error) : setData(d); } })
      .catch((e: any) => { if (current) setErr(e?.message || "Nie udało się pobrać raportu"); })
      .finally(() => { if (current) setLoading(false); });
    return () => { current = false; };
  }, [symbol]);

  const cur = data?.currency || "";
  const next = data?.next;
  const margins = data?.margins?.[marginMode as "quarterly" | "annual"] || [];
  const hasMargins = (data?.margins?.quarterly?.length || 0) >= 2
    || (data?.margins?.annual?.length || 0) >= 2;

  return (
    <Modal visible={!!symbol} animationType="slide" onRequestClose={onClose}
           presentationStyle="fullScreen" statusBarTranslucent>
      {/* Modal zasłania cały ekran, więc awaria w środku odcinałaby drogę powrotną —
          bezpiecznik daje tu zawsze wyjście „Zamknij raport". */}
      <ErrorBoundary name="Raport wyników" resetKey={symbol || ""}
                     onDismiss={onClose} dismissLabel="Zamknij raport">
      <SafeAreaView style={s.root}>
        <StatusBar barStyle="light-content" />
        <View style={s.bar}>
          <Press onPress={onClose} style={s.close}><Icon name="zamknij" size={15} color={C.muted} /></Press>
          <Text style={s.barTitle} numberOfLines={1}>{data?.name || symbol}</Text>
        </View>

        {loading ? (
          <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>
        ) : err ? (
          <View style={s.center}>
            <Text style={s.err}>{err}</Text>
            <MetalButton label="Zamknij" onPress={onClose} />
          </View>
        ) : data ? (
          <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
            {/* ---------- nagłówek ---------- */}
            <FadeIn>
              <View style={s.head}>
                <Logo ticker={data.symbol} size={54} radius={14} />
                <View style={{ flex: 1 }}>
                  <Text style={s.sym}>{data.symbol}</Text>
                  <Text style={s.name} numberOfLines={2}>{data.name}</Text>
                </View>
                <View style={{ alignItems: "flex-end" }}>
                  <Text style={s.price}>
                    {data.price != null ? fmtCur(data.price, cur) : "—"}
                  </Text>
                  {data.change_pct != null && (
                    <Text style={[s.change, { color: plColor(data.change_pct) }]}>
                      {fmtPct(data.change_pct)}
                    </Text>
                  )}
                </View>
              </View>
              <View style={s.badges}>
                {data.owned && <Badge tone={C.green} label="W PORTFELU" />}
                {data.watched && <Badge tone={C.red} label="OBSERWOWANA" />}
                {!!data.exchange && <Badge tone={C.dim} label={data.exchange} />}
                {data.market_cap != null && (
                  <Badge tone={C.dim} label={fmtBig(data.market_cap, cur)} />
                )}
              </View>
            </FadeIn>

            {/* ---------- najbliższa publikacja ---------- */}
            {!!next?.date && (
              <FadeIn delay={60}>
                <Card style={s.nextCard}>
                  <View style={s.nextHead}>
                    <View style={{ flex: 1 }}>
                      <Text style={s.micro}>NAJBLIŻSZA PUBLIKACJA</Text>
                      <Text style={s.nextDate}>{dateLong(next.date)}</Text>
                      <Text style={s.nextSub}>
                        {daysTo(next.date)}
                        {time ? ` · ${SESSION[time]}` : ""}
                        {next.estimate ? " · data szacowana" : ""}
                      </Text>
                    </View>
                    <View style={s.countdown}>
                      <Text style={s.countdownNum}>{next.date.slice(8, 10)}</Text>
                      <Text style={s.countdownMon}>
                        {new Date(next.date + "T00:00:00")
                          .toLocaleDateString("pl-PL", { month: "short" }).toUpperCase()}
                      </Text>
                    </View>
                  </View>
                </Card>
              </FadeIn>
            )}

            {/* ---------- próg pobicia prognozy ---------- */}
            <SectionTitle hint="Powyżej tych wartości mówi się o pobiciu prognozy (beat). Widełki to najniższa i najwyższa prognoza wśród analityków.">
              Ile potrzeba, żeby pobić
            </SectionTitle>
            <Card>
              <Threshold
                label="Zysk na akcję (EPS)"
                value={next?.eps} low={next?.eps_low} high={next?.eps_high}
                fmt={(v) => fmtCur(v, cur, 2)}
              />
              <View style={s.sep} />
              <Threshold
                label="Przychody"
                value={next?.revenue} low={next?.revenue_low} high={next?.revenue_high}
                fmt={(v) => fmtBig(v, cur)}
              />
              {!!data.analysts && (
                <Text style={s.foot}>
                  Konsensus liczony z prognoz {data.analysts} analityków.
                  {data.target_price != null
                    ? ` Średnia cena docelowa: ${fmtCur(data.target_price, cur)}.` : ""}
                </Text>
              )}
            </Card>

            {/* ---------- jak zwykle bywa ---------- */}
            {data.stats.quarters > 0 && (
              <>
                <SectionTitle hint={"Z ostatnich kwartałów. „Typowy ruch\" to średnia z bezwzględnych "
                                    + "zmian kursu na sesji po raporcie — pokazuje skalę, na jaką trzeba być gotowym."}>
                  Jak ta spółka zwykle reaguje
                </SectionTitle>
                <View style={s.stats}>
                  <Stat label="Pobiła prognozę"
                        value={data.stats.beat_rate != null ? `${data.stats.beat_rate}%` : "—"}
                        sub={`${data.stats.beats} z ${data.stats.quarters} kwartałów`}
                        tone={(data.stats.beat_rate ?? 0) >= 50 ? C.green : C.amber} />
                  <Stat label="Średnie zaskoczenie"
                        value={data.stats.avg_surprise_pct != null
                          ? fmtPct(data.stats.avg_surprise_pct) : "—"}
                        sub="odchylenie EPS od prognozy"
                        tone={(data.stats.avg_surprise_pct ?? 0) >= 0 ? C.green : C.red} />
                  <Stat label="Typowy ruch"
                        value={data.stats.avg_move_pct != null
                          ? `±${data.stats.avg_move_pct.toFixed(1).replace(".", ",")}%` : "—"}
                        sub={data.stats.max_move_pct != null
                          ? `największy ±${data.stats.max_move_pct.toFixed(1).replace(".", ",")}%` : ""}
                        tone={C.accent} />
                </View>
              </>
            )}

            {/* ---------- historia zaskoczeń ---------- */}
            {data.history.length > 0 && (
              <>
                <SectionTitle hint="Słupek w górę = wynik lepszy od prognozy. Linia pokazuje, jak zachował się kurs — bywa, że pobicie prognozy kończy się spadkiem.">
                  Poprzednie wyniki
                </SectionTitle>
                <Card>
                  <SurpriseChart data={data.history} />
                  <View style={s.tableHead}>
                    <Text style={[s.th, { flex: 1.1 }]}>Kwartał</Text>
                    <Text style={[s.th, s.rightTxt]}>EPS</Text>
                    <Text style={[s.th, s.rightTxt]}>Prognoza</Text>
                    <Text style={[s.th, s.rightTxt]}>Kurs</Text>
                  </View>
                  {[...data.history].reverse().map((h) => (
                    <View key={h.quarter + h.date} style={s.tr}>
                      <View style={{ flex: 1.1 }}>
                        <Text style={s.tdMain}>{qLabel(h.quarter) || h.period || "—"}</Text>
                        {!!h.date && <Text style={s.tdSub}>{h.date}</Text>}
                      </View>
                      <Text style={[s.td, s.rightTxt, {
                        color: (h.surprise_pct ?? 0) >= 0 ? C.green : C.red,
                      }]}>
                        {h.eps != null ? h.eps.toFixed(2).replace(".", ",") : "—"}
                      </Text>
                      <Text style={[s.td, s.rightTxt, { color: C.muted }]}>
                        {h.estimate != null ? h.estimate.toFixed(2).replace(".", ",") : "—"}
                      </Text>
                      <Text style={[s.td, s.rightTxt, {
                        color: h.reaction_pct == null ? C.dim : plColor(h.reaction_pct),
                      }]}>
                        {h.reaction_pct != null ? fmtPct(h.reaction_pct) : "—"}
                      </Text>
                    </View>
                  ))}
                </Card>
              </>
            )}

            {/* ---------- marże ---------- */}
            {hasMargins && (
              <>
                <SectionTitle hint="Marża brutto mówi o sile cenowej, operacyjna o dyscyplinie kosztów, netto o tym, co zostaje właścicielom. Szare słupki w tle to przychód.">
                  Marże i przychód
                </SectionTitle>
                <Card>
                  <View style={{ marginBottom: 12 }}>
                    <Segmented options={MARGIN_MODES} value={marginMode}
                               onChange={setMarginMode} tone="green" />
                  </View>
                  {margins.length >= 2 ? (
                    <MarginChart data={margins} currency={cur} />
                  ) : (
                    <Text style={s.empty}>
                      Brak danych {marginMode === "annual" ? "rocznych" : "kwartalnych"} dla tej spółki.
                    </Text>
                  )}
                </Card>
              </>
            )}

            {/* ---------- prognozy na kolejne okresy ---------- */}
            {data.trend.length > 0 && (
              <>
                <SectionTitle hint={"Okresy liczone od dziś: bieżący kwartał, następny, bieżący i przyszły rok. "
                                    + "Rewizje to zmiany prognoz analityków z ostatnich 30 dni — więcej w górę "
                                    + "niż w dół oznacza rosnące oczekiwania."}>
                  Prognozy analityków
                </SectionTitle>
                <Card padded={false}>
                  {data.trend.map((t, i) => (
                    <View key={t.period} style={[s.trendRow, i === 0 && { borderTopWidth: 0 }]}>
                      <View style={{ flex: 1 }}>
                        <Text style={s.tdMain}>{PERIOD_PL[t.period] || t.period}</Text>
                        <Text style={s.tdSub}>
                          {t.analysts ? `${t.analysts} analityków` : "—"}
                          {t.rev_growth != null ? ` · przychody ${fmtPct(t.rev_growth)}` : ""}
                        </Text>
                      </View>
                      <View style={{ alignItems: "flex-end" }}>
                        <Text style={s.tdMain}>
                          {t.eps_avg != null ? fmtCur(t.eps_avg, cur, 2) : "—"}
                        </Text>
                        {t.eps_growth != null && (
                          <Text style={[s.tdSub, { color: plColor(t.eps_growth) }]}>
                            EPS {fmtPct(t.eps_growth)} r/r
                          </Text>
                        )}
                      </View>
                      {(!!t.up_30d || !!t.down_30d) && (
                        <View style={s.revisions}>
                          <Text style={[s.rev, { color: C.green }]}>▲{t.up_30d || 0}</Text>
                          <Text style={[s.rev, { color: C.red }]}>▼{t.down_30d || 0}</Text>
                        </View>
                      )}
                    </View>
                  ))}
                </Card>
              </>
            )}

            <View style={{ marginTop: 26 }}>
              <MetalButton
                label="Otwórz pełny profil spółki" tone="green" size="lg" full liquid active
                onPress={() => onOpenProfile(data.symbol)}
              />
              <Text style={s.foot}>
                Wykres notowań, wskaźniki z wyjaśnieniami i porównanie z podobnymi spółkami.
              </Text>
            </View>
          </ScrollView>
        ) : null}
      </SafeAreaView>
      </ErrorBoundary>
    </Modal>
  );
}

const PERIOD_PL: Record<string, string> = {
  "0q": "Bieżący kwartał", "+1q": "Następny kwartał",
  "0y": "Bieżący rok", "+1y": "Następny rok", "-1q": "Poprzedni kwartał",
  "+5y": "Za 5 lat", "-5y": "Ostatnie 5 lat",
};

/** Konsensus z widełkami — pasek pokazuje, gdzie leży średnia między skrajnymi prognozami. */
function Threshold({
  label, value, low, high, fmt,
}: {
  label: string; value?: number | null; low?: number | null; high?: number | null;
  fmt: (v: number) => string;
}) {
  const has = value != null;
  const span = low != null && high != null && high > low ? high - low : 0;
  const at = span && has ? ((value! - low!) / span) * 100 : 50;

  return (
    <View>
      <View style={s.thrHead}>
        <Text style={s.thrLabel}>{label}</Text>
        <Text style={s.thrValue}>{has ? fmt(value!) : "—"}</Text>
      </View>
      {!!span && (
        <>
          <View style={s.thrTrack}>
            <View style={[s.thrMark, { left: `${Math.max(0, Math.min(100, at))}%` }]} />
          </View>
          <View style={s.thrEnds}>
            <Text style={s.thrEnd}>min {fmt(low!)}</Text>
            <Text style={s.thrEnd}>max {fmt(high!)}</Text>
          </View>
        </>
      )}
    </View>
  );
}

function Stat({ label, value, sub, tone }: {
  label: string; value: string; sub?: string; tone: string;
}) {
  return (
    <View style={s.stat}>
      <Text style={s.statLabel}>{label}</Text>
      <Text style={[s.statValue, { color: tone }]}>{value}</Text>
      {!!sub && <Text style={s.statSub}>{sub}</Text>}
    </View>
  );
}

function Badge({ tone, label }: { tone: string; label: string }) {
  return (
    <View style={[s.badge, { borderColor: tone + "66", backgroundColor: tone + "14" }]}>
      <Text style={[s.badgeTxt, { color: tone }]}>{label}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg, paddingTop: Platform.OS === "android" ? 26 : 0 },
  bar: {
    flexDirection: "row", alignItems: "center", gap: 12,
    paddingHorizontal: 14, paddingVertical: 10,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  close: {
    width: 34, height: 34, borderRadius: 17, alignItems: "center", justifyContent: "center",
    backgroundColor: C.card, borderWidth: 1, borderColor: C.border,
  },
  closeTxt: { color: C.muted, fontSize: 15, fontWeight: "800" },
  barTitle: { color: C.text, ...T.h2, flex: 1 },
  center: { flex: 1, alignItems: "center", justifyContent: "center", gap: 14, padding: 30 },
  err: { color: C.text, ...T.body, textAlign: "center" },
  wrap: { padding: 18, paddingBottom: 60 },

  head: { flexDirection: "row", alignItems: "center", gap: 13 },
  sym: { color: C.text, ...T.h1 },
  name: { color: C.muted, ...T.small, marginTop: 2 },
  price: { color: C.text, ...T.h2 },
  change: { fontSize: 13, fontWeight: "800", marginTop: 2 },
  badges: { flexDirection: "row", flexWrap: "wrap", gap: 7, marginTop: 12 },
  badge: { borderRadius: 8, borderWidth: 1, paddingHorizontal: 8, paddingVertical: 3.5 },
  badgeTxt: { fontSize: 9.5, fontWeight: "800", letterSpacing: 0.5 },

  nextCard: { marginTop: 18, borderColor: "rgba(47,212,138,.28)" },
  nextHead: { flexDirection: "row", alignItems: "center", gap: 14 },
  micro: { color: C.dim, ...T.micro },
  nextDate: { color: C.text, ...T.h2, marginTop: 4, textTransform: "capitalize" },
  nextSub: { color: C.green, ...T.small, marginTop: 3, fontWeight: "700" },
  countdown: {
    width: 58, height: 58, borderRadius: 15, alignItems: "center", justifyContent: "center",
    backgroundColor: C.greenDim, borderWidth: 1, borderColor: "rgba(47,212,138,.35)",
  },
  countdownNum: { color: C.green, fontSize: 21, fontWeight: "900", letterSpacing: -0.8 },
  countdownMon: { color: C.green, fontSize: 8.5, fontWeight: "800", letterSpacing: 0.8 },

  thrHead: { flexDirection: "row", justifyContent: "space-between", alignItems: "baseline" },
  thrLabel: { color: C.muted, ...T.body },
  thrValue: { color: C.text, fontSize: 19, fontWeight: "900", letterSpacing: -0.5 },
  thrTrack: {
    height: 5, borderRadius: 3, marginTop: 11,
    backgroundColor: "rgba(255,255,255,.07)",
  },
  thrMark: {
    position: "absolute", top: -3, width: 3, height: 11, borderRadius: 2,
    marginLeft: -1.5, backgroundColor: C.green,
  },
  thrEnds: { flexDirection: "row", justifyContent: "space-between", marginTop: 6 },
  thrEnd: { color: C.dim, fontSize: 10.5, fontWeight: "700" },
  sep: { height: 1, backgroundColor: C.border, marginVertical: 16 },
  foot: { color: C.dim, ...T.small, marginTop: 12, lineHeight: 17 },
  empty: { color: C.dim, ...T.small, paddingVertical: 18, textAlign: "center" },

  stats: { flexDirection: "row", gap: 9 },
  stat: {
    flex: 1, backgroundColor: C.card, borderRadius: 15, borderWidth: 1, borderColor: C.border,
    padding: 12,
  },
  statLabel: { color: C.dim, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.4 },
  statValue: { fontSize: 19, fontWeight: "900", letterSpacing: -0.6, marginTop: 6 },
  statSub: { color: C.dim, fontSize: 9.5, fontWeight: "600", marginTop: 3, lineHeight: 12 },

  tableHead: {
    flexDirection: "row", marginTop: 18, paddingBottom: 7,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  th: { color: C.dim, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.4, flex: 0.8 },
  tr: {
    flexDirection: "row", alignItems: "center", paddingVertical: 9,
    borderBottomWidth: 1, borderBottomColor: "rgba(33,41,56,.6)",
  },
  td: { fontSize: 12.5, fontWeight: "700", flex: 0.8 },
  tdMain: { color: C.text, fontSize: 13, fontWeight: "800" },
  tdSub: { color: C.dim, fontSize: 10, fontWeight: "600", marginTop: 2 },
  rightTxt: { textAlign: "right" },

  trendRow: {
    flexDirection: "row", alignItems: "center", gap: 10, padding: 14,
    borderTopWidth: 1, borderTopColor: C.border,
  },
  revisions: { alignItems: "flex-end", gap: 2, minWidth: 34 },
  rev: { fontSize: 10.5, fontWeight: "800" },
});
