/** Pytanie o zgodę na powiadomienia e-mailem — raz, po zalogowaniu.
 *
 *  Po co osobne pytanie, skoro przełącznik jest w ustawieniach bota: w przeglądarce
 *  nie da się wysłać powiadomienia systemowego, więc dla kogoś, kto korzysta
 *  z Portevo na komputerze, e-mail jest JEDYNYM kanałem. Gdyby czekał schowany
 *  w rozwijanej sekcji, nikt by go nie znalazł — a potem „aplikacja nie powiadamia".
 *
 *  Zasady, których to pytanie się trzyma:
 *
 *  * pytamy RAZ. Odpowiedź (również odmowna) zapisuje się jako `email_asked`
 *    po stronie serwera, więc nie wraca na innym urządzeniu;
 *  * pytamy dopiero, gdy jest kogo pytać — konto zalogowane, adres znany,
 *    a serwer ma skonfigurowaną skrzynkę nadawczą. Inaczej obiecywalibyśmy coś,
 *    czego nie umiemy dowieźć;
 *  * „nie teraz" jest równie łatwe jak „tak" i nic nie ukrywa. Zgoda wymuszona
 *    ciasnym przyciskiem kończy się zgłoszeniem spamu, nie czytelnikiem.
 */
import React, { useEffect, useState } from "react";
import { Modal, Platform, Pressable, StyleSheet, Text, View } from "react-native";
import { getPowiadomienia, zapiszPowiadomienia } from "../api";
import { useAuth } from "../auth/AuthContext";
import { C, T } from "../theme";
import { Card } from "../ui";
import Icon from "../ui/Icon";

export default function EmailConsent() {
  const { ready, user, premium } = useAuth();
  const [pokaz, setPokaz] = useState(false);
  const [adres, setAdres] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (!ready || !user) return;
    let aktualne = true;

    // Krótka zwłoka, żeby pytanie nie wyskoczyło w tej samej sekundzie, w której
    // ktoś się loguje — dwa okna naraz to nie rozmowa, tylko zasadzka.
    const t = setTimeout(async () => {
      try {
        const u = await getPowiadomienia();
        if (!aktualne) return;
        if (!u.email_asked && u.email_available && u.email_address) {
          setAdres(u.email_address);
          setPokaz(true);
        }
      } catch {
        /* brak odpowiedzi = nie pytamy; spróbujemy przy następnym uruchomieniu */
      }
    }, 2500);

    return () => { aktualne = false; clearTimeout(t); };
  }, [ready, user]);

  async function odpowiedz(zgoda: boolean) {
    setBusy(true);
    try {
      await zapiszPowiadomienia({ email_enabled: zgoda, email_asked: true });
    } catch {
      /* nie udało się zapisać — pytanie wróci następnym razem, i dobrze */
    } finally {
      setBusy(false);
      setPokaz(false);
    }
  }

  if (!pokaz) return null;

  return (
    <Modal transparent animationType="fade" visible onRequestClose={() => odpowiedz(false)}>
      <View style={s.tlo}>
        <Card style={s.karta}>
          <View style={s.ikona}>
            <Icon name="dzwonek" size={20} color={C.green} />
          </View>

          <Text style={s.tytul}>Mamy Cię powiadamiać e-mailem?</Text>
          <Text style={s.tresc}>
            Napiszemy na <Text style={s.adres}>{adres}</Text>, gdy pojawi się news
            o spółce z Twojego portfela albo gdy któraś z nich publikuje wyniki.
            {Platform.OS === "web"
              ? " W przeglądarce to jedyny sposób, żeby dowiedzieć się o tym bez "
                + "zaglądania do aplikacji."
              : " Poza powiadomieniami na telefonie."}
          </Text>
          <Text style={s.drobne}>
            Wyłączysz to jednym przełącznikiem w zakładce Bot newsów. Nie wysyłamy
            reklam i nie przekazujemy adresu dalej.
            {!premium && " Powiadomienia działają w wersji premium."}
          </Text>

          {/* Zwykłe przyciski z prymitywów — patrz uwaga w PushPrompt.tsx. */}
          <View style={s.przyciski}>
            <Pressable onPress={() => odpowiedz(false)} disabled={busy}
                       style={({ pressed }) => [s.btn, pressed && s.wcisniety]}>
              <Text style={s.btnTxt}>Nie, dziękuję</Text>
            </Pressable>
            <Pressable onPress={() => odpowiedz(true)} disabled={busy}
                       style={({ pressed }) => [s.btn, s.btnGlowny, pressed && s.wcisniety]}>
              <Text style={s.btnGlownyTxt} numberOfLines={1}>
                {busy ? "Zapisuję…" : "Tak, powiadamiajcie"}
              </Text>
            </Pressable>
          </View>
        </Card>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  tlo: {
    flex: 1, backgroundColor: "rgba(4,6,11,.82)",
    alignItems: "center", justifyContent: "center", padding: 22,
  },
  karta: { padding: 20, width: "100%", maxWidth: 420 },
  ikona: {
    width: 38, height: 38, borderRadius: 13, backgroundColor: C.greenDim,
    borderWidth: 1, borderColor: "rgba(47,212,138,.32)",
    alignItems: "center", justifyContent: "center", marginBottom: 14,
  },
  tytul: { color: C.text, ...T.h2, marginBottom: 8 },
  tresc: { color: C.muted, ...T.small, lineHeight: 19.5 },
  adres: { color: C.text, fontWeight: "700" },
  drobne: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 10 },
  przyciski: { flexDirection: "row", gap: 9, marginTop: 18 },
  btn: {
    flex: 1, minHeight: 46, borderRadius: 13, paddingVertical: 12, paddingHorizontal: 10,
    borderWidth: 1, borderColor: C.border2, backgroundColor: C.card,
    alignItems: "center", justifyContent: "center",
  },
  btnGlowny: { flex: 1.25, backgroundColor: C.green, borderColor: C.green },
  btnTxt: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  btnGlownyTxt: { color: "#04140c", fontSize: 13.5, fontWeight: "800" },
  wcisniety: { opacity: 0.7 },
});
