/** Dokumenty prawne w aplikacji: prywatność, regulamin, kontakt.
 *
 *  Recenzent App Store szuka polityki prywatności i wsparcia WEWNĄTRZ aplikacji,
 *  nie tylko pod adresem w formularzu. Treść pobieramy z serwera (`/api/legal/...`),
 *  więc jest identyczna z tą na stronie i poprawia się bez wydawania nowej wersji.
 *
 *  Wydajność: ekran montuje się dopiero po dotknięciu odnośnika, a zapytanie leci
 *  raz na sesję (`cache` niżej). Nic z tego nie chodzi w tle.
 */
import React, { useEffect, useState } from "react";
import {
  ActivityIndicator, Linking, Modal, Pressable, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { getLegal, LegalDoc } from "../api";
import { C, T } from "../theme";
import { Card, MetalButton } from "../ui";

import Icon from "../ui/Icon";
export type LegalSlug = "privacy" | "terms" | "support";

export const LEGAL_TITLE: Record<LegalSlug, string> = {
  privacy: "Polityka prywatności",
  terms: "Regulamin",
  support: "Kontakt i pomoc",
};

/** Publiczne adresy tych samych dokumentów — na wypadek, gdyby serwer nie odpowiedział. */
const PUBLIC_URL: Record<LegalSlug, string> = {
  privacy: "https://www.portevo.pl/prywatnosc",
  terms: "https://www.portevo.pl/regulamin",
  support: "https://www.portevo.pl/kontakt",
};

/** Raz pobrany dokument zostaje w pamięci — powrót do niego jest natychmiastowy. */
const cache = new Map<LegalSlug, LegalDoc>();

export default function LegalScreen({
  slug, onClose,
}: { slug: LegalSlug; onClose: () => void }) {
  const [doc, setDoc] = useState<LegalDoc | null>(cache.get(slug) || null);
  const [err, setErr] = useState("");

  useEffect(() => {
    let zywy = true;
    const gotowy = cache.get(slug);
    if (gotowy) { setDoc(gotowy); setErr(""); return; }
    setDoc(null);
    setErr("");
    getLegal(slug)
      .then((d) => { cache.set(slug, d); if (zywy) setDoc(d); })
      .catch(() => { if (zywy) setErr("Nie udało się pobrać dokumentu. Sprawdź połączenie."); });
    return () => { zywy = false; };
  }, [slug]);

  return (
    <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}>
      <View style={s.root}>
        <View style={s.bar}>
          <Text style={s.barTitle} numberOfLines={1}>{doc?.title || LEGAL_TITLE[slug]}</Text>
          <Pressable onPress={onClose} hitSlop={12} style={s.close}>
            <Icon name="zamknij" size={15} color={C.muted} />
          </Pressable>
        </View>

        {!doc && !err && (
          <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>
        )}

        {!!err && (
          <View style={s.center}>
            <Text style={s.err}>{err}</Text>
            {/* Wyjście awaryjne. Ten ekran bywa jedynym dowodem, że odnośnik do
                regulaminu i polityki prywatności DZIAŁA (wytyczna 3.1.2(c)), więc
                nie wolno mu skończyć na samym komunikacie o błędzie: gdy serwer
                nie odpowie, zostaje ten sam dokument pod publicznym adresem. */}
            <MetalButton
              label="Otwórz w przeglądarce" tone="blue" active full
              style={{ marginTop: 16 }}
              onPress={() => Linking.openURL(PUBLIC_URL[slug]).catch(() => {})}
            />
            <MetalButton label="Zamknij" tone="steel" full style={{ marginTop: 10 }} onPress={onClose} />
          </View>
        )}

        {!!doc && (
          <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
            <Text style={s.lead}>{doc.lead}</Text>
            <Text style={s.upd}>Obowiązuje od {doc.updated}</Text>

            {doc.sections.map((sec) => (
              <View key={sec.h} style={s.sec}>
                <Text style={s.h2}>{sec.h}</Text>
                {sec.p.map((p, i) => <Text key={i} style={s.p}>{p}</Text>)}
                {sec.list.map((li, i) => (
                  <View key={i} style={s.li}>
                    <Text style={s.dot}>•</Text>
                    <Text style={s.liTxt}>{li}</Text>
                  </View>
                ))}
              </View>
            ))}

            {!!doc.url && (
              <Card style={s.linkCard}>
                <Text style={s.linkTxt}>
                  Ten sam dokument w przeglądarce — do zapisania albo wydrukowania.
                </Text>
                <MetalButton label="Otwórz w przeglądarce" tone="steel" full
                             style={{ marginTop: 12 }}
                             onPress={() => Linking.openURL(doc.url).catch(() => {})} />
              </Card>
            )}
          </ScrollView>
        )}
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 24 },
  err: { color: C.muted, ...T.body, textAlign: "center" },
  bar: {
    flexDirection: "row", alignItems: "center", gap: 10,
    paddingHorizontal: 16, paddingVertical: 13,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  barTitle: { flex: 1, color: C.text, ...T.h2 },
  close: {
    width: 32, height: 32, borderRadius: 10, alignItems: "center", justifyContent: "center",
    backgroundColor: C.cardHi,
  },
  closeTxt: { color: C.muted, fontSize: 15, fontWeight: "700" },

  wrap: { padding: 20, paddingBottom: 48, maxWidth: 760, width: "100%", alignSelf: "center" },
  lead: { color: C.text, fontSize: 15.5, lineHeight: 23 },
  upd: { color: C.dim, ...T.small, marginTop: 8 },
  sec: { marginTop: 26, paddingTop: 20, borderTopWidth: 1, borderTopColor: C.border },
  h2: { color: C.text, ...T.h2 },
  p: { color: C.muted, fontSize: 14, lineHeight: 21, marginTop: 9 },
  li: { flexDirection: "row", gap: 9, marginTop: 9 },
  dot: { color: C.green, fontSize: 14, lineHeight: 21 },
  liTxt: { flex: 1, color: C.muted, fontSize: 14, lineHeight: 21 },
  linkCard: { padding: 16, marginTop: 28 },
  linkTxt: { color: C.muted, ...T.small, lineHeight: 18 },
});
