/** „O nas — dlaczego to takie ważne" — rozwijana sekcja sprzedażowo-osobista.
 *
 *  Stoi w dwóch miejscach (na górze paywalla i w profilu), więc jest jednym
 *  komponentem: zmiana tekstu to jedna edycja. Domyślnie zwinięta, żeby nie
 *  spychać reszty ekranu — nagłówek kusi, treść czeka na dotknięcie.
 */
import { LinearGradient } from "expo-linear-gradient";
import React, { useEffect, useRef, useState } from "react";
import { Animated, Easing, Pressable, StyleSheet, Text, View } from "react-native";
import { C, T } from "../theme";
import { FadeIn, MetalButton } from "../ui";

import Icon from "../ui/Icon";
/** Wstęp — to jest to zdanie, po którym czyta się resztę albo zamyka sekcję. */
const LEAD =
  "Jesteśmy małym studiem. Portevo robimy z zamiłowaniem i pasją — po godzinach, "
  + "z uporem i dla ludzi, którzy tak jak my chcieli mieć wreszcie narzędzie zrobione "
  + "po ludzku.";

/** Numerowane punkty zamiast ikonek — mniej krzyku, bardziej jak list od kogoś. */
const POINTS: { title: string; body: string; bodyPremium?: string }[] = [
  {
    title: "Serwery kosztują — i tu wchodzisz Ty",
    body: "Nasłuch rynku przez całą dobę i liczenie Twoich danych to rachunek, który "
      + "przychodzi co miesiąc. Wykupując płatną wersję bardzo nas wspierasz i "
      + "umożliwiasz dalsze działanie projektu, który rozwijamy. To naprawdę tyle — "
      + "nie stoi za nami żaden fundusz, stoisz Ty.",
    bodyPremium: "Nasłuch rynku przez całą dobę i liczenie Twoich danych to rachunek, "
      + "który przychodzi co miesiąc — i który właśnie pomagasz opłacić. Umożliwiasz "
      + "dalsze działanie projektu, który rozwijamy. Nie stoi za nami żaden fundusz, "
      + "stoisz Ty.",
  },
  {
    title: "Będziemy dodawać nowe funkcje",
    body: "Aplikacja nie jest skończona i nie zamierza być. Dokładamy kolejne rzeczy "
      + "krok po kroku, a płatna wersja daje dostęp do wszystkiego, co dojdzie — "
      + "bez dopłat i bez gwiazdek.",
  },
  {
    title: "Piszesz prosto do nas",
    body: "Osobom z wersji płatnej dajemy specjalną możliwość: napisz nam, czego "
      + "brakuje w aplikacji i jakiej funkcji szukasz, a dołożymy wszelkich starań, "
      + "żeby dodać ją jak najszybciej, jeśli tylko będzie to możliwe. Nie zostawimy "
      + "Cię bez informacji — obiecujemy, że odpiszemy w przeciągu 24 godzin.",
  },
];

/** Wersja dla kogoś, kto już zapłacił — to nie jest ta sama rozmowa.
 *  Zamiast prosić o wsparcie, dziękujemy za nie. Stąd róż zamiast złota. */
const ROZ = "#ff7eb6";
const ROZ_GLEB = "#c2185b";

const PODZIEKOWANIE =
  "Masz wersję płatną — i to dzięki Tobie to wszystko stoi. Serio: rachunek za "
  + "serwery opłacają tacy ludzie jak Ty, a każda kolejna funkcja powstaje, bo "
  + "ktoś uznał, że warto nas wesprzeć. Dziękujemy.";

export default function AboutStudio({
  defaultOpen = false, onContact, contactLabel = "Napisz do nas", premium = false,
}: {
  defaultOpen?: boolean;
  /** gdy podane, na dole pojawia się przycisk otwierający wiadomość do twórców */
  onContact?: () => void;
  contactLabel?: string;
  /** widz ma już premium — sekcja zmienia się w podziękowanie */
  premium?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen);
  const rot = useRef(new Animated.Value(defaultOpen ? 1 : 0)).current;

  const akcent = premium ? ROZ : C.gold;
  const ramka = premium
    ? (["rgba(255,126,182,.55)", "rgba(194,24,91,.14)"] as const)
    : (["rgba(255,210,74,.5)", "rgba(255,180,84,.12)"] as const);

  useEffect(() => {
    Animated.timing(rot, {
      toValue: open ? 1 : 0, duration: 240,
      easing: Easing.out(Easing.quad), useNativeDriver: true,
    }).start();
  }, [open]);

  const spin = rot.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "180deg"] });

  return (
    <LinearGradient
      colors={ramka as any}
      start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
      style={s.edge}
    >
      <View style={s.face}>
        <Pressable onPress={() => setOpen((v) => !v)} style={s.head}>
          <View style={[s.spark, premium && s.sparkPrem]}>
            <Icon name={premium ? "serceOn" : "premium"} size={premium ? 18 : 16}
                  color={premium ? ROZ : C.gold} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={s.title}>
              {premium ? "Dziękujemy — naprawdę" : "O nas — dlaczego to takie ważne"}
            </Text>
            <Text style={[s.sub, { color: akcent }]}>
              {open ? "Kilka słów od nas"
                : premium ? "Wspierasz nas — zobacz, co to zmienia"
                : "Przeczytaj — to zajmie chwilę"}
            </Text>
          </View>
          <Animated.Text style={[s.chev, { transform: [{ rotate: spin }] }]}>⌄</Animated.Text>
        </Pressable>

        {open && (
          <FadeIn offset={6}>
            <View style={{ marginTop: 16 }}>
              {premium && (
                <View style={s.dziekiBox}>
                  <View style={s.dziekiSerce}><Icon name="serceOn" size={15} color={ROZ} /></View>
                  <Text style={s.dziekiTxt}>{PODZIEKOWANIE}</Text>
                </View>
              )}

              <Text style={s.lead}>{LEAD}</Text>

              <View style={{ marginTop: 18, gap: 16 }}>
                {POINTS.map((p, i) => (
                  <View key={p.title} style={s.point}>
                    <View style={[s.num, premium && s.numPrem]}>
                      <Text style={[s.numTxt, premium && { color: ROZ }]}>
                        {String(i + 1).padStart(2, "0")}
                      </Text>
                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={s.pTitle}>{p.title}</Text>
                      <Text style={s.pBody}>{(premium && p.bodyPremium) || p.body}</Text>
                    </View>
                  </View>
                ))}
              </View>

              <View style={[s.rule, premium && { backgroundColor: "rgba(255,126,182,.22)" }]} />
              <Text style={[s.thanks, { color: akcent }]}>
                Dzięki, że jesteś z nami. Bez Was ten projekt by nie istniał.
              </Text>
              <Text style={s.sign}>— zespół Portevo</Text>

              {!!onContact && (
                <MetalButton label={contactLabel} tone="amber" accent={premium ? ROZ : undefined}
                             active liquid full
                             style={{ marginTop: 4 }} onPress={onContact} />
              )}
            </View>
          </FadeIn>
        )}
      </View>
    </LinearGradient>
  );
}

const s = StyleSheet.create({
  edge: { borderRadius: 20, padding: 1.5, marginTop: 16 },
  face: { backgroundColor: C.card, borderRadius: 18.5, padding: 17 },
  head: { flexDirection: "row", alignItems: "center", gap: 13 },
  spark: {
    width: 40, height: 40, borderRadius: 12, alignItems: "center", justifyContent: "center",
    backgroundColor: "rgba(255,210,74,.14)", borderWidth: 1, borderColor: "rgba(255,210,74,.4)",
  },
  sparkPrem: {
    backgroundColor: "rgba(255,126,182,.16)", borderColor: "rgba(255,126,182,.45)",
  },

  dziekiBox: {
    flexDirection: "row", gap: 12, alignItems: "flex-start",
    borderRadius: 14, padding: 14, marginBottom: 16,
    backgroundColor: "rgba(255,126,182,.09)", borderWidth: 1,
    borderColor: "rgba(255,126,182,.38)",
  },
  dziekiSerce: { marginTop: 2 },
  dziekiTxt: { color: C.text, flex: 1, fontSize: 13, lineHeight: 20, fontWeight: "600" },
  title: { color: C.text, fontSize: 15.5, fontWeight: "800", letterSpacing: -0.2 },
  sub: { color: C.gold, fontSize: 12, fontWeight: "700", marginTop: 3 },
  chev: { color: C.muted, fontSize: 20, fontWeight: "800", width: 22, textAlign: "center" },

  lead: { color: C.text, fontSize: 13.5, lineHeight: 21 },

  point: { flexDirection: "row", gap: 13, alignItems: "flex-start" },
  num: {
    width: 27, height: 27, borderRadius: 9, alignItems: "center", justifyContent: "center",
    backgroundColor: "rgba(255,210,74,.1)", borderWidth: 1, borderColor: "rgba(255,210,74,.28)",
    marginTop: 1,
  },
  numPrem: {
    backgroundColor: "rgba(255,126,182,.1)", borderColor: "rgba(255,126,182,.3)",
  },
  numTxt: { color: C.gold, fontSize: 11, fontWeight: "800", letterSpacing: 0.3 },
  pTitle: { color: C.text, fontSize: 14, fontWeight: "800", letterSpacing: -0.2 },
  pBody: { color: C.muted, fontSize: 12.8, lineHeight: 19, marginTop: 4 },

  rule: {
    height: 1, backgroundColor: "rgba(255,210,74,.18)", marginTop: 20, marginBottom: 14,
  },
  sign: { color: C.muted, fontSize: 12, fontWeight: "700", marginTop: 5, marginBottom: 4 },

  thanks: { color: C.gold, fontSize: 13, fontWeight: "700", lineHeight: 19 },
});
