/** Zamknięte pozycje — statystyki skuteczności (akcje vs CFD) i lista transakcji. */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, RefreshControl, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { ClosedSummary, ClosedTrade, getClosed, getClosedSummary, TradeStats } from "../api";
import { BrandFooter } from "../components/Brand";
import Logo from "../components/Logo";
import { usePortfolioVersion } from "../refresh";
import { C, fmtNum, fmtPct, plColor, plural, T } from "../theme";
import Icon from "../ui/Icon";
import {
  Bar, Card, FadeIn, LiquidButton, MetalButton, Press, RefreshButton, Row, SectionTitle, Segmented,
} from "../ui";
import { TAB_SPACE } from "../layout";

const SCOPE = [
  { id: "all", label: "Wszystko" },
  { id: "stocks", label: "Akcje / ETF" },
  { id: "cfd", label: "CFD" },
];

/** Kwoty w tej sekcji są w walucie konta (XTB liczy wynik transakcji w walucie rozliczenia). */
const cur = (v: number) => (v >= 0 ? "+" : "") + fmtNum(v, 2);

export default function HistoryScreen() {
  const [sum, setSum] = useState<ClosedSummary | null>(null);
  const [trades, setTrades] = useState<ClosedTrade[] | null>(null);
  const [scope, setScope] = useState("all");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const load = useCallback(async () => {
    setErr("");
    try {
      const [s, t] = await Promise.all([getClosedSummary(), getClosed()]);
      setSum(s);
      setTrades(t);
    } catch (e: any) {
      setErr(e?.message || "Błąd połączenia");
    } finally {
      setLoading(false);
      setBusy(false);
    }
  }, []);

  // Wgranie raportu i zmiana konta dotyczą też tej listy — ekran zostaje
  // zamontowany, więc bez sygnału pokazywałby stan sprzed importu.
  const wersja = usePortfolioVersion();
  useEffect(() => { load(); }, [wersja]);

  if (loading) {
    return <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>;
  }
  if (err) {
    return (
      <View style={s.center}>
        <Text style={s.errTitle}>{err}</Text>
        <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 220 }}
                      onPress={() => { setLoading(true); load(); }} />
      </View>
    );
  }
  if (sum?.empty) {
    return (
      <View style={s.center}>
        <Icon name="teczka" size={42} color={C.dim} />
        <Text style={s.errTitle}>Brak zamkniętych pozycji</Text>
        <Text style={s.dim}>Tu pojawi się historia Twoich transakcji.</Text>
        <LiquidButton label="Odśwież" full={false} style={{ minWidth: 200, marginTop: 6 }}
                      onPress={() => { setLoading(true); load(); }} />
      </View>
    );
  }

  const st: TradeStats = (sum as any)[scope];
  const list = (trades || []).filter((t) =>
    scope === "all" ? true
      : scope === "cfd" ? (t.category || "").toUpperCase() === "CFD"
      : (t.category || "").toUpperCase() !== "CFD");

  return (
    <ScrollView
      contentContainerStyle={s.wrap}
      showsVerticalScrollIndicator={false}
      refreshControl={
        <RefreshControl refreshing={busy} tintColor={C.green}
                        onRefresh={() => { setBusy(true); load(); }} />
      }
    >
      <FadeIn>
        <View style={s.titleRow}>
          <View style={{ flex: 1 }}>
            <Text style={s.h1}>Zamknięte</Text>
            <Text style={s.sub}>Skuteczność Twoich zakończonych transakcji</Text>
          </View>
          <RefreshButton busy={busy} onPress={() => { setBusy(true); load(); }} />
        </View>
      </FadeIn>

      <FadeIn delay={70}>
        <View style={{ marginTop: 16 }}>
          <Segmented options={SCOPE} value={scope} onChange={setScope} />
        </View>
      </FadeIn>

      {st.count === 0 ? (
        <Card style={{ marginTop: 16, padding: 26 }}>
          <Text style={[s.dim, { textAlign: "center" }]}>
            Brak transakcji w tej kategorii.
          </Text>
        </Card>
      ) : (
        <>
          <FadeIn delay={120}>
            <Card style={{ marginTop: 14, padding: 18 }}>
              <Text style={s.cardLabel}>Wynik łączny</Text>
              <Text style={[s.bigResult, { color: plColor(st.profit) }]}>{cur(st.profit)}</Text>
              <Text style={s.cardHint}>
                z {st.count} {plural(st.count, "transakcji", "transakcji", "transakcji")} · w walucie konta
              </Text>

              <View style={s.wlWrap}>
                <View style={s.wlLabels}>
                  <Text style={[s.wlTxt, { color: C.green }]}>
                    {st.wins} {plural(st.wins, "zyskowna", "zyskowne", "zyskownych")}
                  </Text>
                  <Text style={[s.wlTxt, { color: C.red }]}>
                    {st.losses} {plural(st.losses, "stratna", "stratne", "stratnych")}
                  </Text>
                </View>
                <View style={s.wlBar}>
                  <View style={{ flex: Math.max(st.wins, 0.001), backgroundColor: C.green }} />
                  <View style={{ flex: Math.max(st.losses, 0.001), backgroundColor: C.red }} />
                </View>
                <Text style={s.wlPct}>
                  Skuteczność {st.win_rate.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}%
                </Text>
              </View>
            </Card>
          </FadeIn>

          <FadeIn delay={170}>
            <Card style={{ marginTop: 12, paddingHorizontal: 16, paddingVertical: 4 }}>
              <Row k="Średni zysk" v={cur(st.avg_win)} color={C.green} />
              <Row k="Średnia strata" v={cur(st.avg_loss)} color={C.red} />
              <Row
                k="Profit factor"
                v={st.profit_factor == null ? "—" : st.profit_factor.toLocaleString("pl-PL", { maximumFractionDigits: 2 })}
                color={(st.profit_factor ?? 0) >= 1 ? C.green : C.red}
              />
              <Row k="Średni czas trzymania"
                   v={st.avg_days == null ? "—"
                     : `${Math.round(st.avg_days)} ${plural(Math.round(st.avg_days), "dzień", "dni", "dni")}`} />
              <Row k="Najlepsza" v={`${st.best.ticker}  ${cur(st.best.profit)}`} color={C.green} />
              <Row k="Najgorsza" v={`${st.worst.ticker}  ${cur(st.worst.profit)}`} color={C.red} last />
            </Card>
            <Text style={s.explain}>
              <Text style={s.b}>Profit factor</Text> to suma zysków podzielona przez sumę strat.
              Powyżej 1,0 znaczy, że strategia zarabia; im wyżej, tym lepiej.
            </Text>
          </FadeIn>

          {scope === "all" && (
            <>
              <SectionTitle hint="Sumy wyników wszystkich transakcji na danym instrumencie">
                Najlepsze i najgorsze
              </SectionTitle>
              <FadeIn delay={60}>
                <Card style={{ padding: 14 }}>
                  {sum!.top.filter((t) => t.profit > 0).map((t, i) => (
                    <View key={"t" + t.ticker} style={s.rankRow}>
                      <Logo ticker={t.ticker} size={26} />
                      <Text style={s.rankTicker}>{t.ticker}</Text>
                      <View style={{ flex: 1, paddingHorizontal: 10 }}>
                        <Bar pct={Math.abs(t.profit) / Math.abs(sum!.top[0].profit || 1) * 100}
                             color={C.green} delay={i * 60} />
                      </View>
                      <Text style={[s.rankVal, { color: C.green }]}>{cur(t.profit)}</Text>
                    </View>
                  ))}
                  {sum!.flop.filter((t) => t.profit < 0).map((t, i) => (
                    <View key={"f" + t.ticker} style={s.rankRow}>
                      <Logo ticker={t.ticker} size={26} />
                      <Text style={s.rankTicker}>{t.ticker}</Text>
                      <View style={{ flex: 1, paddingHorizontal: 10 }}>
                        <Bar pct={Math.abs(t.profit) / Math.abs(sum!.flop[0].profit || 1) * 100}
                             color={C.red} delay={i * 60} />
                      </View>
                      <Text style={[s.rankVal, { color: C.red }]}>{cur(t.profit)}</Text>
                    </View>
                  ))}
                </Card>
              </FadeIn>
            </>
          )}

          <SectionTitle hint={`${list.length} ${plural(list.length, "transakcja", "transakcje", "transakcji")} · od najnowszej`}>
            Historia transakcji
          </SectionTitle>

          {list.map((t, i) => {
            const pct = t.purchase_value ? (t.profit / t.purchase_value) * 100 : 0;
            const days = (() => {
              try {
                return Math.round(
                  (new Date(t.close_time).getTime() - new Date(t.open_time).getTime()) / 86400000);
              } catch { return null; }
            })();
            return (
              <FadeIn key={`${t.ticker}${t.close_time}${i}`} delay={Math.min(i * 18, 240)} offset={9}>
                <Card style={s.tradeCard}>
                  <Logo ticker={t.ticker} size={34} />
                  <View style={{ flex: 1, marginLeft: 11 }}>
                    <View style={s.tradeTop}>
                      <Text style={s.tradeTicker}>{t.ticker}</Text>
                      {(t.category || "").toUpperCase() === "CFD" && (
                        <View style={s.cfdTag}><Text style={s.cfdTxt}>CFD</Text></View>
                      )}
                      {t.type === "SELL" && (
                        <View style={s.shortTag}><Text style={s.shortTxt}>SHORT</Text></View>
                      )}
                    </View>
                    <Text style={s.tradeName} numberOfLines={1}>{t.instrument}</Text>
                    <Text style={s.tradeMeta}>
                      {t.open_time?.slice(0, 10)} → {t.close_time?.slice(0, 10)}
                      {days != null ? ` · ${days} ${plural(days, "dzień", "dni", "dni")}` : ""}
                    </Text>
                  </View>
                  <View style={{ alignItems: "flex-end" }}>
                    <Text style={[s.tradeProfit, { color: plColor(t.profit) }]}>{cur(t.profit)}</Text>
                    <View style={[s.pctPill, { backgroundColor: pct >= 0 ? C.greenDim : C.redDim }]}>
                      <Text style={[s.pctTxt, { color: plColor(pct) }]}>{fmtPct(pct)}</Text>
                    </View>
                  </View>
                </Card>
              </FadeIn>
            );
          })}
        </>
      )}

      <BrandFooter />
    </ScrollView>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: TAB_SPACE },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 30, gap: 12 },
  dim: { color: C.muted, ...T.body },
  errTitle: { color: C.text, ...T.h2, textAlign: "center" },
  retry: { backgroundColor: C.green, borderRadius: 13, paddingVertical: 13, paddingHorizontal: 26 },
  retryTxt: { color: "#04140c", fontWeight: "800", fontSize: 15 },

  titleRow: { flexDirection: "row", alignItems: "flex-start", gap: 10 },
  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginTop: 3 },

  cardLabel: { color: C.muted, ...T.micro, textTransform: "uppercase" },
  bigResult: { fontSize: 32, fontWeight: "800", letterSpacing: -1, marginTop: 5 },
  cardHint: { color: C.dim, fontSize: 12, marginTop: 3 },

  wlWrap: { marginTop: 18 },
  wlLabels: { flexDirection: "row", justifyContent: "space-between", marginBottom: 7 },
  wlTxt: { fontSize: 12.5, fontWeight: "700" },
  wlBar: { flexDirection: "row", height: 8, borderRadius: 4, overflow: "hidden", gap: 2 },
  wlPct: { color: C.muted, fontSize: 12, marginTop: 8, textAlign: "center" },

  explain: { color: C.dim, fontSize: 12, lineHeight: 18, marginTop: 10, paddingHorizontal: 2 },
  b: { color: C.muted, fontWeight: "800" },

  rankRow: { flexDirection: "row", alignItems: "center", paddingVertical: 7 },
  rankTicker: { color: C.text, fontSize: 12.5, fontWeight: "700", width: 76, marginLeft: 9 },
  rankVal: { fontSize: 12.5, fontWeight: "800", width: 66, textAlign: "right" },

  tradeCard: { flexDirection: "row", alignItems: "center", padding: 12, marginBottom: 8 },
  tradeTop: { flexDirection: "row", alignItems: "center", gap: 6 },
  tradeTicker: { color: C.text, fontWeight: "800", fontSize: 14 },
  cfdTag: {
    backgroundColor: "rgba(167,139,250,.16)", borderRadius: 5, paddingHorizontal: 5, paddingVertical: 1,
  },
  cfdTxt: { color: C.violet, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.4 },
  shortTag: {
    backgroundColor: "rgba(255,180,84,.16)", borderRadius: 5, paddingHorizontal: 5, paddingVertical: 1,
  },
  shortTxt: { color: C.amber, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.4 },
  tradeName: { color: C.muted, fontSize: 11.5, marginTop: 2 },
  tradeMeta: { color: C.dim, fontSize: 10.5, marginTop: 3 },
  tradeProfit: { fontSize: 14, fontWeight: "800" },
  pctPill: { borderRadius: 7, paddingHorizontal: 7, paddingVertical: 2, marginTop: 4 },
  pctTxt: { fontSize: 11, fontWeight: "800" },
});
