/** Narzędzia — przyrządy do konkretnej roboty, rozwijane jedno po drugim.
 *
 *  Każde narzędzie to składana karta: zwinięta zajmuje jeden wiersz i mówi, do czego
 *  służy; rozwinięta zajmuje cały ekran roboty. Dzięki temu lista rośnie z czasem,
 *  a ekran nie zamienia się w ścianę — dokładanie kolejnego przyrządu to jeden wpis
 *  w tablicy niżej.
 */
import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  Animated, Easing, Modal, Platform, Pressable, SafeAreaView, ScrollView,
  StatusBar, StyleSheet, Text, View,
} from "react-native";
import { getPanelInsiderow, getPref, setPref } from "../api";
import { useAuth } from "../auth/AuthContext";
import { BrandFooter } from "../components/Brand";
import PremiumGate, { PreviewBanner, StalePanelBanner } from "../components/PremiumGate";
import { C, T } from "../theme";
import { Card, ErrorBoundary, FadeIn } from "../ui";
import Icon, { IconName } from "../ui/Icon";
import { openTab } from "../tabRouter";
import { openInsiders } from "../insiderRouter";
import CorrelationSection from "./allocation/CorrelationSection";
import RiskSection from "./allocation/RiskSection";
import DividendLab from "./tools/dividends";
import EtfScanner from "./tools/EtfScanner";
import LiveEvents from "./tools/LiveEvents";
import { TAB_SPACE } from "../layout";

const OPEN_PREF = "tools.open";

type Tool = {
  id: string;
  icon: IconName;
  title: string;
  desc: string;
  /** identyfikator funkcji premium — kłódka pojawia się w środku, nie na nagłówku */
  feature?: string;
  /** narzędzie samo zarządza tym, co pokazuje bez premium (np. skaner daje darmową listę) */
  selfGated?: boolean;
  /** otwiera się na cały ekran zamiast rozwijać się w liście.
   *
   *  Dla przyrządów, które same w sobie mają zakładki, filtry i tabele —
   *  upchnięte w rozwiniętą kartę dostają szerokość kolumny z listą narzędzi
   *  i pasek przewijania w pasku przewijania. Pełny ekran daje im tę samą
   *  przestrzeń co Alokacji czy Przeglądowi. */
  fullscreen?: boolean;
  /** zamiast rozwijać treść — przenosi w inne miejsce aplikacji.
   *
   *  Dla przyrządów, które MAJĄ już swoją zakładkę, ale są w niej schowane.
   *  Kopiowanie ekranu w dwa miejsca skończyłoby się dwiema wersjami tego
   *  samego, które z czasem się rozjeżdżają — więc tu stoi tylko drogowskaz. */
  przenies?: () => void;
  render: () => React.ReactNode;
};

const TOOLS: Tool[] = [
  {
    // Bot ma własną zakładkę, ale dzieli ją z kalendarzem wyników i domyślnie
    // otwiera się na Earnings — przez co bywa nieodnaleziony. Tu jest drugie
    // wejście, w miejscu, w którym ludzie szukają narzędzi.
    id: "bot",
    icon: "antena",
    title: "Bot newsów",
    desc: "Nasłuch ESPI, SEC, komunikatów urzędów i serwisów newsowych przez całą dobę. "
        + "AI ocenia każdą wiadomość, a Ty dostajesz powiadomienie, gdy dotyczy spółki "
        + "z Twojego portfela.",
    przenies: () => openTab("bot", "bot"),
    render: () => null,
  },
  {
    // Panel żyje nad całą aplikacją (App.tsx), bo otwiera się też z wykresu
    // spółki i z powiadomienia — tu stoi tylko wejście do niego.
    id: "insajderzy",
    icon: "insajder",
    title: "Insajderzy",
    desc: "Co kupują Nancy Pelosi, Donald Trump, Kongres, rząd USA i prezesi spółek. "
        + "Ranking z wynikami, profile z tym, na co idą ich pieniądze, i twarze "
        + "na wykresach — dokładnie tam, gdzie ktoś kupił.",
    feature: "tools.insiders",
    selfGated: true,
    przenies: () => { openInsiders(); },
    render: () => null,
  },
  {
    id: "dywidendy",
    icon: "dywidendy",
    title: "Inwestowanie dywidendowe",
    desc: "Skaner spółek i funduszy po stopie, serii podwyżek i wskaźniku wypłaty, "
        + "kalendarz dni bez dywidendy oraz kalkulator pokazujący, ile realnie "
        + "wpłynie na konto po podatku.",
    feature: "tools.dividends",
    selfGated: true,
    fullscreen: true,
    render: () => <DividendLab />,
  },
  {
    id: "etf",
    icon: "etf",
    title: "Skaner ETF",
    desc: "Prześwietl fundusz: co jest w środku, ile kosztuje i jak mocno potrafi spaść. "
        + "Filtruj po regionie, branży i walucie, porównuj po kilka naraz.",
    feature: "tools.etf",
    selfGated: true,
    render: () => <EtfScanner />,
  },
  {
    id: "live",
    icon: "live",
    title: "Wystąpienia na żywo",
    desc: "Konferencje, decyzje banków i wystąpienia oglądane na bieżąco: dźwięk zamieniany "
        + "na tekst, a model wyłapuje z niego to, co dotyczy konkretnych spółek.",
    feature: "bot.live",
    render: () => <LiveEvents />,
  },
  {
    id: "risk",
    icon: "ryzyko",
    title: "Rentgen ryzyka",
    desc: "Która pozycja naprawdę rozhuśtuje Twój portfel, jak bardzo jesteś skupiony "
        + "i ile realnie zależy od kursu walut.",
    feature: "alloc.risk",
    render: () => <RiskSection />,
  },
  {
    id: "corr",
    icon: "korelacja",
    title: "Mapa korelacji",
    desc: "Sprawdź, czy Twoje spółki chodzą osobno, czy wszystkie naraz. "
        + "Dziesięć pozycji to nie dywersyfikacja, jeśli reagują na to samo.",
    feature: "alloc.correlation",
    render: () => <CorrelationSection />,
  },
];

export default function ToolsScreen() {
  const [open, setOpen] = useState<string | null>(null);
  const [pelnyEkran, setPelnyEkran] = useState<Tool | null>(null);

  useEffect(() => {
    getPref(OPEN_PREF, "").then((v) => { if (v) setOpen(v); });
    // panel insiderów dociągamy zawczasu — po dotknięciu karty jest już gotowy
    getPanelInsiderow().catch(() => {});
  }, []);

  const toggle = useCallback((id: string) => {
    const narzedzie = TOOLS.find((t) => t.id === id);
    // Drogowskaz: nic nie rozwijamy, tylko przenosimy tam, gdzie ten przyrząd mieszka.
    if (narzedzie?.przenies) { narzedzie.przenies(); return; }
    // Narzędzia pełnoekranowe nie rozwijają się w liście — otwierają się nad nią.
    // Nie zapamiętujemy ich w `OPEN_PREF`, bo wejście do Narzędzi nie powinno
    // witać pełnym ekranem tego, co ktoś oglądał wczoraj.
    if (narzedzie?.fullscreen) { setPelnyEkran(narzedzie); return; }
    setOpen((cur) => {
      const next = cur === id ? null : id;
      setPref(OPEN_PREF, next || "");
      return next;
    });
  }, []);

  return (
    <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}
                keyboardShouldPersistTaps="handled">
      <FadeIn>
        <Text style={s.h1}>Narzędzia</Text>
        <Text style={s.sub}>Przyrządy, które robią jedną rzecz i robią ją dobrze</Text>
      </FadeIn>

      <View style={{ marginTop: 16 }}>
        <StalePanelBanner />
        <PreviewBanner />
      </View>

      {TOOLS.map((t, i) => (
        <FadeIn key={t.id} delay={60 + i * 60}>
          <ToolCard tool={t} open={open === t.id} onToggle={() => toggle(t.id)} />
        </FadeIn>
      ))}

      <Card style={s.soon}>
        <Text style={s.soonTitle}>Kolejne w drodze</Text>
        <Text style={s.soonTxt}>
          Kalkulator podatku od zysków, symulator planu systematycznego i skaner spółek.
          Jeśli czegoś tu brakuje, a używałbyś tego co tydzień — daj znać.
        </Text>
      </Card>

      <BrandFooter />

      <PelnyEkran tool={pelnyEkran} zamknij={() => setPelnyEkran(null)} />
    </ScrollView>
  );
}

/** Narzędzie rozłożone na całym oknie — z własnym nagłówkiem i wyjściem.
 *
 *  `Modal` zamiast zwykłego widoku, bo ekrany aplikacji siedzą w kolumnie
 *  ograniczonej do czytelnej szerokości (`COLUMN_MAX` w App.tsx). Skaner z tabelą
 *  i filtrami potrzebuje więcej i musi wyjść poza tę kolumnę — modal jest jedynym
 *  miejscem, które nie jest jej dzieckiem.
 */
function PelnyEkran({ tool, zamknij }: { tool: Tool | null; zamknij: () => void }) {
  const { locked, paywall, loginOpen } = useAuth();

  // **Okno sprzedażowe i ekran logowania renderują się w `App.tsx`, czyli POZA
  // tym modalem — a modal je zakrywa.** Objaw: przycisk „Zobacz, co daje
  // premium" na telefonie wyglądał na martwy. Nie był: paywall otwierał się
  // pod spodem i nikt go nie widział. Dlatego pełny ekran zamyka się sam, gdy
  // którekolwiek z tych okien zostanie poproszone o otwarcie.
  //
  // Warunek jest ogólny, a nie wpięty w konkretny przycisk — dzięki temu
  // zadziała też dla kolejnych narzędzi i dla kłódek schowanych w ich wnętrzu,
  // o których ten komponent nic nie wie.
  useEffect(() => {
    if (tool && (paywall !== null || loginOpen)) zamknij();
  }, [paywall, loginOpen, tool]);

  if (!tool) return null;
  const isLocked = tool.feature ? locked(tool.feature) : false;

  return (
    <Modal visible animationType="slide" onRequestClose={zamknij}
           transparent={false} presentationStyle="fullScreen">
      {/* Bez tego nagłówek wchodzi pod pasek stanu telefonu i tytuł nakłada się
          na zegarek — powłoka aplikacji ma `SafeAreaView`, ale modal renderuje
          się poza jej drzewem i nic z niego nie dziedziczy. Na Androidzie
          `SafeAreaView` nic nie robi, więc dokładamy wysokość paska ręcznie. */}
      <SafeAreaView style={[s.fsRoot,
                            Platform.OS === "android" && { paddingTop: StatusBar.currentHeight || 0 }]}>
        <View style={s.fsHead}>
          <View style={[s.toolIcon, isLocked && s.toolIconLocked, { width: 38, height: 38 }]}>
            <Icon name={tool.icon} size={21} color={isLocked ? C.amber : C.green} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={s.fsTitle} numberOfLines={1}>{tool.title}</Text>
            <Text style={s.fsSub} numberOfLines={1}>Narzędzia · Portevo</Text>
          </View>
          <Pressable onPress={zamknij} hitSlop={12} style={s.fsClose}
                     accessibilityRole="button" accessibilityLabel="Zamknij narzędzie">
            <Icon name="zamknij" size={17} color={C.muted} />
          </Pressable>
        </View>

        <ScrollView contentContainerStyle={s.fsBody} showsVerticalScrollIndicator={false}
                    keyboardShouldPersistTaps="handled">
          <View style={s.fsColumn}>
            <ErrorBoundary name={tool.title}>
              {tool.feature && !tool.selfGated
                ? <PremiumGate id={tool.feature} minHeight={320}>{tool.render()}</PremiumGate>
                : tool.render()}
            </ErrorBoundary>
          </View>
        </ScrollView>
      </SafeAreaView>
    </Modal>
  );
}

function ToolCard({ tool, open, onToggle }: {
  tool: Tool; open: boolean; onToggle: () => void;
}) {
  const { locked, feature } = useAuth();
  const isLocked = tool.feature ? locked(tool.feature) : false;
  // Podpowiedź o darmowej części. Była w katalogu funkcji od początku
  // (`free_hint` w `bot/premium.py`) i przez cały czas nie wyświetlała się
  // nigdzie — a to jedyne zdanie, które mówi, po co w ogóle tu wchodzić
  // bez premium.
  const wskazowka = (tool.feature && feature(tool.feature)?.free_hint) || "";
  const spin = useRef(new Animated.Value(open ? 1 : 0)).current;

  useEffect(() => {
    Animated.timing(spin, {
      toValue: open ? 1 : 0, duration: 220,
      easing: Easing.out(Easing.cubic), useNativeDriver: true,
    }).start();
  }, [open]);

  return (
    <Card style={[s.tool, open && s.toolOpen, isLocked && s.toolLocked]}>
      <Pressable onPress={onToggle} style={s.toolHead}>
        <View style={[s.toolIcon, isLocked && s.toolIconLocked]}>
          <Icon name={tool.icon} size={19} color={isLocked ? C.amber : C.green} />
        </View>
        <View style={{ flex: 1 }}>
          <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
            <Text style={s.toolTitle}>{tool.title}</Text>
            {/* Narzędzie, które samo pilnuje swoich kłódek, jest w większości
                DARMOWE — plakietka „🔒 PREMIUM" odstraszała od otwarcia czegoś,
                z czego bez opłaty korzysta się w trzech czwartych. Kłódka
                zostaje tam, gdzie faktycznie zamyka całość. */}
            {isLocked && (
              tool.selfGated
                ? <View style={s.pillFree}><Text style={s.pillFreeTxt}>DARMOWE · WIĘCEJ W PREMIUM</Text></View>
                : <View style={s.pill}>
                    <Icon name="klodka" size={9} color="#ffc45c" />
                    <Text style={s.pillTxt}>PREMIUM</Text>
                  </View>
            )}
          </View>
          <Text style={s.toolDesc}>{tool.desc}</Text>
          {isLocked && tool.selfGated && !!wskazowka && (
            <Text style={s.toolFree}>{wskazowka}</Text>
          )}
        </View>
        {tool.fullscreen || tool.przenies ? (
          <Text style={s.chevron}>›</Text>
        ) : (
          <Animated.Text
            style={[s.chevron, {
              transform: [{ rotate: spin.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "180deg"] }) }],
            }]}
          >
            ⌄
          </Animated.Text>
        )}
      </Pressable>

      {open && (
        <View style={s.toolBody}>
          {tool.feature && !tool.selfGated
            ? <PremiumGate id={tool.feature} minHeight={320}>{tool.render()}</PremiumGate>
            : tool.render()}
        </View>
      )}
    </Card>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: TAB_SPACE },

  fsRoot: { flex: 1, backgroundColor: C.bg },
  fsHead: {
    flexDirection: "row", alignItems: "center", gap: 12,
    paddingHorizontal: 16, paddingTop: 14, paddingBottom: 12,
    borderBottomWidth: 1, borderBottomColor: C.border, backgroundColor: C.elev,
  },
  fsTitle: { color: C.text, ...T.h2 },
  fsSub: { color: C.dim, fontSize: 11, marginTop: 2 },
  fsClose: {
    width: 34, height: 34, borderRadius: 10, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center", backgroundColor: C.card,
  },
  fsBody: { padding: 16, paddingBottom: 48 },
  /** Na monitorze treść nie rozlewa się na całą szerokość — 1180 px to tyle,
   *  ile potrzebuje tabela z filtrami, i nie więcej. */
  fsColumn: { width: "100%", maxWidth: 1180, alignSelf: "center" },
  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginTop: 3 },

  tool: { padding: 0, marginBottom: 12, overflow: "hidden" },
  toolOpen: { borderColor: C.border2 },
  toolLocked: { borderColor: "rgba(255,196,92,.3)" },
  toolHead: { flexDirection: "row", alignItems: "center", gap: 13, padding: 16 },
  toolIcon: {
    width: 44, height: 44, borderRadius: 14, alignItems: "center", justifyContent: "center",
    backgroundColor: C.cardHi,
  },
  toolIconLocked: { backgroundColor: "rgba(255,196,92,.13)" },
  toolTitle: { color: C.text, fontSize: 15.5, fontWeight: "800", letterSpacing: -0.2 },
  toolDesc: { color: C.dim, fontSize: 12, lineHeight: 17, marginTop: 5 },
  chevron: { color: C.muted, fontSize: 17, fontWeight: "800", marginTop: -4 },
  toolBody: {
    paddingHorizontal: 14, paddingBottom: 16, paddingTop: 2,
    borderTopWidth: 1, borderTopColor: C.border,
  },

  pill: {
    flexDirection: "row", alignItems: "center", gap: 3.5,
    borderRadius: 999, paddingHorizontal: 8, paddingVertical: 2.5,
    backgroundColor: "rgba(255,196,92,.15)", borderWidth: 1, borderColor: "rgba(255,196,92,.5)",
  },
  pillTxt: { color: "#ffc45c", fontSize: 8.5, fontWeight: "800", letterSpacing: 0.7 },
  /** Zielona, nie bursztynowa — bursztyn oznacza w tej apce kłódkę, a tu
   *  komunikat jest odwrotny: „wejdź, to działa". */
  pillFree: {
    borderRadius: 999, paddingHorizontal: 8, paddingVertical: 2.5,
    backgroundColor: C.greenDim, borderWidth: 1, borderColor: "rgba(47,212,138,.45)",
  },
  pillFreeTxt: { color: C.green, fontSize: 8.5, fontWeight: "800", letterSpacing: 0.7 },
  toolFree: { color: C.green, fontSize: 11.5, lineHeight: 16, marginTop: 6 },

  soon: { padding: 16, marginTop: 6 },
  soonTitle: { color: C.muted, ...T.micro },
  soonTxt: { color: C.dim, fontSize: 12.3, lineHeight: 19, marginTop: 8 },
});
