/** Stan konta i premium dla całej aplikacji.
 *
 *  Jedno miejsce odpowiada na trzy pytania, które zadaje pół ekranów:
 *  kto jest zalogowany, czy ma premium i co pokazać, gdy dotknie kłódki.
 *
 *  Status premium liczy SERWER (`/api/me`), nie telefon. Aplikacja tylko go
 *  wyświetla — inaczej wystarczyłoby podmienić jedną zmienną w pamięci, żeby
 *  odblokować wszystko.
 */
import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import {
  getConfig, getMe, getPanelVersion, getPref, getPremiumCatalog, Me, PremiumCatalog,
  PremiumFeature, refreshMe, REQUIRED_API, setLoginPrompt, setPref, trackPremium,
} from "../api";
import { captureReferralFromUrl, flushPendingReferral } from "../referral";
import { portfolioChanged } from "../refresh";
import * as sb from "./supabase";
import * as sync from "./sync";

/** Klucz preferencji trybu podglądu — zostaje na telefonie, nie synchronizuje się. */
const PREVIEW_PREF = "premium.previewFree";

type Ctx = {
  ready: boolean;
  /** konto Supabase — null, gdy niezalogowany albo logowanie niedostępne */
  user: sb.AuthUser | null;
  me: Me | null;
  premium: boolean;
  catalog: PremiumCatalog | null;
  configured: boolean;
  /** funkcja, dla której ma się otworzyć strona sprzedażowa (null = zamknięta) */
  paywall: string | null;
  showPaywall: (featureId: string) => void;
  hidePaywall: () => void;
  /** ekran logowania — trzymany w kontekście, żeby dało się go otworzyć z dowolnego miejsca */
  loginOpen: boolean;
  openLogin: () => void;
  closeLogin: () => void;
  feature: (id: string) => PremiumFeature | null;
  /** czy tę funkcję trzeba zasłonić kłódką temu użytkownikowi */
  locked: (id: string) => boolean;

  /* ---- tryb podglądu dla konta właściciela ----
   * Właściciel ma premium z definicji, więc bez tego nigdy nie zobaczyłby własnych
   * kłódek i nie miałby jak sprawdzić, co widzi klient. `previewFree` włącza widok
   * darmowy, a `devUnlock` przepuszcza przez konkretną kłódkę na czas sesji —
   * czyli dokładnie to, czego trzeba do testów: obie warstwy naraz. */
  /** panel na komputerze jest starszy niż aplikacja — nowe ekrany nie mają skąd wziąć danych */
  panelStale: boolean;
  /** numer API panelu; null = panel go nie zna, czyli jest sprzed tej wersji */
  panelApi: number | null;

  isDev: boolean;
  previewFree: boolean;
  setPreviewFree: (on: boolean) => void;
  devUnlock: (featureId: string) => void;
  /** czy ta funkcja jest zasłonięta tylko dlatego, że trwa podgląd */
  previewOnly: (featureId: string) => boolean;
  reload: () => Promise<void>;
  signIn: (email: string, pass: string) => Promise<void>;
  signUp: (email: string, pass: string, referralCode?: string) => Promise<boolean>;
  signInGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
};

const AuthCtx = createContext<Ctx | null>(null);

export const useAuth = () => {
  const c = useContext(AuthCtx);
  if (!c) throw new Error("useAuth poza AuthProvider");
  return c;
};

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [ready, setReady] = useState(false);
  const [user, setUser] = useState<sb.AuthUser | null>(null);
  const [me, setMe] = useState<Me | null>(null);
  const [catalog, setCatalog] = useState<PremiumCatalog | null>(null);
  const [paywall, setPaywall] = useState<string | null>(null);
  const [loginOpen, setLoginOpen] = useState(false);
  const [previewFree, setPreviewFreeState] = useState(false);
  const [unlocked, setUnlocked] = useState<string[]>([]);
  const [panelStale, setPanelStale] = useState(false);
  const [panelApi, setPanelApi] = useState<number | null>(null);
  /** czy użytkownik sam ustawił już tryb podglądu — dopóki nie, decydujemy za niego */
  const previewChosen = useRef(false);
  const alive = useRef(true);

  useEffect(() => () => { alive.current = false; }, []);

  // Każda odmowa „musisz być zalogowany" — z dowolnego ekranu — otwiera to samo
  // okno logowania. Dzięki temu przeglądanie jest wolne, a konto pojawia się
  // dokładnie w chwili, w której użytkownik próbuje czegoś, co go wymaga.
  useEffect(() => {
    setLoginPrompt(() => setLoginOpen(true));
    return () => setLoginPrompt(null);
  }, []);

  /** Kod polecający wpisany przed zalogowaniem (okno logowania, link twórcy)
   *  trafia do konta dopiero po zalogowaniu — wcześniej konta po prostu nie ma.
   *  Gdy kod dał premium od twórcy, od razu pobieramy świeży status konta. */
  const wyslijKod = useCallback((userId: string) => {
    flushPendingReferral(userId, sb.currentUser()?.referralCode).then(async (r) => {
      if (!r?.reward_days || !alive.current) return;
      const swiezy = await refreshMe().catch(() => null);
      if (swiezy && alive.current) setMe(swiezy);
    });
  }, []);

  /** Pobiera z serwera stan konta i katalog funkcji. Nigdy nie rzuca — brak
   *  odpowiedzi to po prostu „wersja darmowa i katalog z ostatniego razu". */
  const pull = useCallback(async () => {
    const [v, m, c] = await Promise.all([
      getPanelVersion().catch(() => null),
      getMe().catch(() => null),
      getPremiumCatalog().catch(() => null),
    ]);
    if (!alive.current) return;
    // brak /api/version albo za niski numer = panel sprzed tej wersji aplikacji
    setPanelStale(!v || v.api < REQUIRED_API);
    setPanelApi(v ? v.api : null);
    if (m) setMe(m);
    if (c) setCatalog(c);

    // Właściciel ma premium z definicji, więc bez podglądu nigdy nie zobaczyłby
    // własnych kłódek. Przy pierwszym uruchomieniu włączamy mu go sami — inaczej
    // ekran wygląda identycznie jak przed dołożeniem całej warstwy premium.
    if (m?.owner && !previewChosen.current) {
      previewChosen.current = true;
      const stored = await getPref(PREVIEW_PREF, "");
      if (!stored && alive.current) {
        setPreviewFreeState(true);
        setPref(PREVIEW_PREF, "1");
      }
    }
    // ustawienia ściągamy tylko dla konta — właściciel na własnym serwerze bez
    // konta Supabase nie ma czego synchronizować
    sync.setEnabled(Boolean(m?.user?.id));
    if (m?.user?.id) {
      sync.pull();
      wyslijKod(m.user.id);
    }
  }, [wyslijKod]);

  const reload = useCallback(async () => {
    const u = await sb.restore().catch(() => null);
    if (!alive.current) return;
    setUser(u);
    await pull();
  }, [pull]);

  useEffect(() => {
    getPref(PREVIEW_PREF, "").then((v) => {
      if (v) { previewChosen.current = true; setPreviewFreeState(v === "1"); }
    });
  }, []);

  useEffect(() => {
    (async () => {
      // Link twórcy (`/?kod=KASIA`) zapisujemy PRZED pierwszym `pull` — inaczej
      // zalogowany użytkownik wchodzący z linku minąłby się ze swoim kodem.
      await captureReferralFromUrl();
      // zimny start po logowaniu Google: aplikacja dostaje tokeny w adresie startowym
      const fromLink = await sb.consumeInitialUrl().catch(() => null);
      const u = fromLink || (await sb.restore().catch(() => null));
      if (!alive.current) return;
      setUser(u);
      await pull();
      if (alive.current) setReady(true);
    })();
  }, [pull]);

  const afterLogin = useCallback(async (u: sb.AuthUser | null) => {
    setUser(u);
    // po zalogowaniu status premium musi przyjść świeży, nie z minutowego cache serwera
    const m = await refreshMe().catch(() => null);
    if (!alive.current) return;
    if (m) setMe(m);
    if (m?.user?.id) wyslijKod(m.user.id);
    const c = await getPremiumCatalog().catch(() => null);
    if (alive.current && c) setCatalog(c);
  }, [wyslijKod]);

  // Zalogowanie i wylogowanie zmieniają WŁAŚCICIELA danych: gość ogląda portfel
  // pokazowy, zalogowany — swój. Ekrany zostają zamontowane po pierwszym wejściu,
  // więc bez tego sygnału po zalogowaniu dalej wisiałyby na nich cudze liczby,
  // a po wylogowaniu — własne. Pierwszego ustalenia stanu nie liczymy jako zmiany:
  // ekrany i tak dopiero wtedy pobierają dane.
  const poprzedniWlasciciel = useRef<string | null | undefined>(undefined);
  useEffect(() => {
    if (!ready) return;
    const id = user?.id ?? null;
    if (poprzedniWlasciciel.current === undefined) {
      poprzedniWlasciciel.current = id;
      return;
    }
    if (poprzedniWlasciciel.current === id) return;
    poprzedniWlasciciel.current = id;
    portfolioChanged();
  }, [ready, user?.id]);

  const value = useMemo<Ctx>(() => ({
    ready,
    user,
    me,
    premium: Boolean(me?.premium),
    catalog,
    configured: sb.authConfigured(),
    paywall,

    showPaywall(featureId) {
      trackPremium("lock_click", featureId);
      setPaywall(featureId);
    },
    hidePaywall() { setPaywall(null); },

    loginOpen,
    openLogin() { setLoginOpen(true); },
    closeLogin() { setLoginOpen(false); },

    feature(id) {
      return catalog?.features.find((f) => f.id === id) || null;
    },

    locked(id) {
      const f = catalog?.features.find((x) => x.id === id);
      // dopóki katalog się nie wczytał, nie zasłaniamy nic — migotanie kłódek
      // przy każdym starcie byłoby gorsze niż sekunda odsłoniętej karty
      if (!f || f.status !== "live") return false;
      if (unlocked.includes(id)) return false;          // dev przeklikał tę kłódkę
      if (previewFree && Boolean(me?.owner)) return true;
      return !me?.premium;
    },

    panelStale,
    panelApi,

    // Token panelu ma tylko właściciel — dostaje go raz, ręcznie, z własnego komputera.
    // Dlatego wystarcza za dowód tożsamości i nie uzależnia trybu dewelopera od tego,
    // czy `/api/me` akurat odpowiedziało. Bez tego jedna nieudana odpowiedź serwera
    // chowała przełącznik i nie było jak wrócić.
    isDev: Boolean(me?.owner) || Boolean(getConfig().token),
    previewFree,
    setPreviewFree(on) {
      previewChosen.current = true;
      setPreviewFreeState(on);
      setPref(PREVIEW_PREF, on ? "1" : "0");
      if (!on) setUnlocked([]);                          // wyjście z podglądu czyści wyjątki
    },
    devUnlock(featureId) {
      setUnlocked((u) => (u.includes(featureId) ? u : [...u, featureId]));
      setPaywall(null);
    },
    previewOnly(featureId) {
      const f = catalog?.features.find((x) => x.id === featureId);
      return Boolean(previewFree && me?.owner && f?.status === "live" && !unlocked.includes(featureId));
    },

    reload,

    async signIn(email, pass) { await afterLogin(await sb.signIn(email, pass)); },

    async signUp(email, pass, referralCode) {
      const u = await sb.signUp(email, pass, referralCode);
      if (u) { await afterLogin(u); return true; }
      return false;               // konto powstało, ale czeka na potwierdzenie adresu
    },

    async signInGoogle() {
      const u = await sb.signInGoogle();
      if (u) await afterLogin(u);
    },

    async signOut() {
      await sb.signOut();
      if (!alive.current) return;
      setUser(null);
      await pull();
    },
  }), [ready, user, me, catalog, paywall, loginOpen, previewFree, unlocked, panelStale,
       panelApi, reload, afterLogin, pull]);

  return <AuthCtx.Provider value={value}>{children}</AuthCtx.Provider>;
}
