/** Obowiązkowa informacja o subskrypcji — to, przez co Apple odrzuciło wydanie 1.0.1.
 *
 *  Wytyczna 3.1.2(c) wymaga, żeby NA TYM SAMYM ekranie, na którym stoi przycisk
 *  zakupu, widoczne było komplet informacji:
 *
 *    * nazwa subskrypcji,
 *    * długość okresu rozliczeniowego,
 *    * cena (i cena za jednostkę, jeśli ma to sens),
 *    * DZIAŁAJĄCE odnośniki do regulaminu (EULA) i polityki prywatności.
 *
 *  Recenzent sprawdza to klikając, a nie czytając kod — dlatego odnośniki otwierają
 *  dokument WEWNĄTRZ aplikacji (ten sam ekran, co w zakładce „Więcej”), a nie
 *  przeglądarkę: wyjście do Safari bywa w recenzji uznawane za „link nie działa”,
 *  gdy urządzenie testowe nie ma sieci albo strona wolno się ładuje. Otwarcie w
 *  przeglądarce zostaje jako przycisk wewnątrz samego dokumentu.
 *
 *  Ten sam blok pokazujemy też w wydaniu webowym i androidowym — tam wymogu Apple
 *  nie ma, ale informacja jest tak samo uczciwa, a kod jeden.
 */
import React, { useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import LegalScreen, { LegalSlug } from "../screens/LegalScreen";
import { C } from "../theme";

/** Publiczne adresy dokumentów — awaryjne wyjście, gdyby ekran w apce nie wstał. */
export const TERMS_URL = "https://www.portevo.pl/regulamin";
export const PRIVACY_URL = "https://www.portevo.pl/prywatnosc";

/** Kwota po polsku: 5,99 zł. Ta sama postać, co na kartach planów. */
export function money(v: number, currency = "PLN"): string {
  const n = v.toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return currency === "PLN" ? `${n} zł` : `${n} ${currency}`;
}

/** „mies.” / „rok” z cennika → pełna długość okresu, tak jak chce Apple. */
export function okresSlownie(period: string): string {
  const p = (period || "").toLowerCase();
  if (p.startsWith("mies")) return "1 miesiąc";
  if (p.startsWith("rok") || p.startsWith("rocz")) return "12 miesięcy";
  if (p.startsWith("tyg")) return "7 dni";
  return period || "";
}

export default function SubscriptionTerms({
  planLabel, period, price, unitPrice, store,
}: {
  /** nazwa planu z cennika, np. „Rocznie” */
  planLabel?: string;
  /** okres z cennika: „mies.” albo „rok” */
  period?: string;
  /** cena do pokazania — na iOS prosto ze StoreKit, inaczej z naszego cennika */
  price?: string;
  /** cena w przeliczeniu na miesiąc — Apple wymienia ją jako „price per unit” */
  unitPrice?: string;
  /** true = kupuje Apple; zmienia opis anulowania na ustawienia App Store */
  store: "apple" | "web";
}) {
  const [legal, setLegal] = useState<LegalSlug | null>(null);

  const tytul = planLabel ? `Portevo Premium — ${planLabel.toLowerCase()}` : "Portevo Premium";
  const dlugosc = okresSlownie(period || "");

  return (
    <View style={s.box}>
      {/* Nazwa, okres i cena — trzy pierwsze punkty z listy Apple, wprost, bez skrótów. */}
      <Text style={s.head}>{tytul}</Text>
      <Text style={s.line}>
        Okres rozliczeniowy: {dlugosc || "zgodnie z wybranym planem"}
        {price ? ` · Cena: ${price} za ${dlugosc || "okres"}` : ""}
        {unitPrice ? ` (≈ ${unitPrice} miesięcznie)` : ""}
      </Text>

      <Text style={s.line}>
        {store === "apple"
          ? "Subskrypcja odnawia się automatycznie. Opłatę pobiera Apple z Twojego konta "
            + "App Store w chwili potwierdzenia zakupu i przy każdym odnowieniu, dopóki nie "
            + "wyłączysz odnawiania co najmniej 24 godziny przed końcem bieżącego okresu. "
            + "Odnawianie wyłączysz w Ustawieniach iPhone’a → Twoje imię → Subskrypcje."
          : "Subskrypcja odnawia się automatycznie na kolejny okres, dopóki jej nie wyłączysz. "
            + "Rezygnację zgłaszasz w każdej chwili w zakładce „Więcej”; dostęp zostaje do "
            + "końca opłaconego okresu."}
      </Text>

      {/* Odnośniki — muszą być klikalne i muszą coś otwierać. Duże pole dotyku, bo
          recenzent celuje palcem w telefon, nie kursorem w kod. */}
      <View style={s.links}>
        <Pressable onPress={() => setLegal("terms")} hitSlop={12} style={s.linkBtn}>
          <Text style={s.link}>Regulamin (EULA)</Text>
        </Pressable>
        <Text style={s.sep}>·</Text>
        <Pressable onPress={() => setLegal("privacy")} hitSlop={12} style={s.linkBtn}>
          <Text style={s.link}>Polityka prywatności</Text>
        </Pressable>
      </View>

      {legal && <LegalScreen slug={legal} onClose={() => setLegal(null)} />}
    </View>
  );
}

const s = StyleSheet.create({
  box: { marginTop: 14 },
  head: { color: C.muted, fontSize: 12, fontWeight: "800", textAlign: "center" },
  line: { color: C.dim, fontSize: 11, lineHeight: 16.5, marginTop: 6, textAlign: "center" },
  links: {
    flexDirection: "row", alignItems: "center", justifyContent: "center",
    gap: 8, marginTop: 10,
  },
  linkBtn: { paddingVertical: 6, paddingHorizontal: 4 },
  link: { color: C.accent, fontSize: 12.5, fontWeight: "700", textDecorationLine: "underline" },
  sep: { color: C.dim, fontSize: 12 },
});
