/** Sekcja „Insajderzy" na karcie spółki — kto z wewnątrz kupował i sprzedawał.
 *
 *  Pokazuje się tylko wtedy, gdy są jakiekolwiek zgłoszenia (spółki z GPW czy
 *  fundusze ich nie mają — pusta sekcja byłaby szumem). Bez premium liczby
 *  zostają (ile zakupów, ile sprzedaży), a znikają ludzie: zamiast twarzy
 *  rozmyte kółka, zamiast nazwisk znak zapytania.
 */
import React, { useEffect, useMemo, useRef } from "react";
import { Animated, Pressable, StyleSheet, Text, View } from "react-native";
import { InsiderzySpolki, PersonaInsidera, TransakcjaInsidera } from "../../../api";
import { C } from "../../../theme";
import { Card, FadeIn, Press, SectionTitle } from "../../../ui";
import { Avatar, dzien, kasa, kwota, opis, Przelacznik, useInsiderPrefs, WEJSCIE } from "./shared";

export default function CompanyInsiders({
  data, locked, onPerson, onLocked,
}: {
  data: InsiderzySpolki | null;
  locked: boolean;
  onPerson: (id: string) => void;
  /** dotknięcie czegokolwiek bez premium — przejście do narzędzia */
  onLocked: () => void;
}) {
  const prefs = useInsiderPrefs();
  const sum = data?.summary;

  // W roku nic się nie działo (CD Projekt: ostatnia transakcja zarządu w styczniu
  // 2025)? Wtedy pokazujemy wcześniejsze, zamiast liczników z samymi zerami.
  const wRoku = !!sum && sum.buys + sum.sells > 0;

  /** Osoby z ostatniego roku (albo z całej historii), od najważniejszej. */
  const osoby = useMemo(() => {
    if (!data || locked) return [];
    const rokTemu = wRoku ? new Date(Date.now() - 365 * 86400000).toISOString().slice(0, 10) : "";
    const wg: Record<string, { p: PersonaInsidera; t: TransakcjaInsidera[] }> = {};
    for (const t of data.trades as TransakcjaInsidera[]) {
      if (t.date < rokTemu || !data.persons[t.person]) continue;
      (wg[t.person] ||= { p: data.persons[t.person], t: [] }).t.push(t);
    }
    const suma = (x: TransakcjaInsidera[]) => x.reduce((a, t) => a + (t.hi ?? t.lo ?? 0), 0);
    return Object.values(wg).sort((a, b) =>
      (a.p.rank || 9999) - (b.p.rank || 9999) || suma(b.t) - suma(a.t)).slice(0, 6);
  }, [data, locked, wRoku]);

  if (!data || !sum || !sum.total) return null;
  const obrot = (sum.bought || 0) + (sum.sold || 0);
  const udzialKupna = obrot > 0 ? sum.bought / obrot : sum.buys + sum.sells > 0
    ? sum.buys / (sum.buys + sum.sells) : 0.5;

  return (
    <FadeIn delay={100}>
      <SectionTitle hint={(wRoku ? "Zgłoszenia z ostatnich 12 miesięcy" : "W ostatnim roku bez transakcji — wcześniejsze")
        + (sum?.cur === "PLN" ? " · powiadomienia MAR z raportów ESPI"
                              : " · SEC, Kongres, rząd USA i fundusze")}>
        Insajderzy w tej spółce
      </SectionTitle>
      <Card>
        {wRoku ? (<>
        <View style={s.stats}>
          <Stat label="Zakupy" value={String(sum.buys)} sub={sum.bought ? `≈ ${kasa(sum.bought, sum.cur)}` : ""}
                color={C.green} />
          <Stat label="Sprzedaże" value={String(sum.sells)} sub={sum.sold ? `≈ ${kasa(sum.sold, sum.cur)}` : ""}
                color={C.red} />
          <Stat label="Osoby" value={String(sum.people)}
                sub={sum.last ? `ostatnio ${dzien(sum.last, sum.last.slice(0, 4) !== String(new Date().getFullYear()))}` : ""} />
        </View>
        <Waga udzial={udzialKupna} />
        </>) : (
          <Text style={s.cicho}>
            Ostatnia transakcja insidera: {dzien(sum.last, true)} · {sum.total}{" "}
            {sum.total === 1 ? "transakcja" : "transakcji"} w bazie
          </Text>
        )}

        {locked ? (
          <Pressable onPress={onLocked} style={s.locked}>
            <View style={s.blurRow}>
              {(data.trades as { blur?: string }[]).slice(0, 5).map((t, i) => (
                <Avatar key={i} size={34} locked blur={t.blur} ring="plain"
                        style={{ marginLeft: i ? -10 : 0 }} />
              ))}
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.lockedTitle}>Kto to jest?</Text>
              <Text style={s.lockedTxt}>Nazwiska, kwoty i profile insiderów są w premium.</Text>
            </View>
            <Text style={s.lockedCta}>Zobacz ›</Text>
          </Pressable>
        ) : (
          <View style={{ marginTop: 6 }}>
            {osoby.map(({ p, t }, i) => {
              const ost = t[0];
              const kupil = t.some((x) => x.side === "buy");
              return (
                <Press key={p.id} scaleTo={0.99} onPress={() => onPerson(p.id)}
                       style={[s.person, i === osoby.length - 1 && { borderBottomWidth: 0 }]}>
                  <Avatar person={p} size={38} ring={kupil ? "buy" : "sell"} />
                  <View style={{ flex: 1, minWidth: 0, marginLeft: 10 }}>
                    <Text style={s.name} numberOfLines={1}>{p.name}</Text>
                    <Text style={s.role} numberOfLines={1}>{opis(p, true)}</Text>
                  </View>
                  <View style={{ alignItems: "flex-end", marginLeft: 8 }}>
                    <Text style={[s.last, { color: ost.side === "buy" ? C.green : C.red }]}>
                      {ost.side === "buy" ? "kupno" : "sprzedaż"} · {dzien(ost.date, !wRoku)}
                    </Text>
                    <Text style={s.amt}>{kwota(ost)}{t.length > 1 ? `  +${t.length - 1}` : ""}</Text>
                  </View>
                </Press>
              );
            })}
          </View>
        )}

        <View style={s.toggles}>
          <Przelacznik on={prefs.chart} label="Twarze na wykresie"
                       onPress={() => prefs.setChart(!prefs.chart)} />
          <Przelacznik on={prefs.sells} label="Także sprzedaże"
                       onPress={() => prefs.setSells(!prefs.sells)} />
        </View>
      </Card>
    </FadeIn>
  );
}

function Stat({ label, value, sub, color }: { label: string; value: string; sub?: string; color?: string }) {
  return (
    <View style={s.stat}>
      <Text style={s.statL}>{label}</Text>
      <Text style={[s.statV, color ? { color } : null]}>{value}</Text>
      {!!sub && <Text style={s.statS} numberOfLines={1}>{sub}</Text>}
    </View>
  );
}

/** Pasek kupno/sprzedaż — przewaga kwot, nie liczby transakcji: jedna sprzedaż
 *  prezesa za 50 mln $ waży więcej niż dziesięć zakupów rady po 20 tys. */
function Waga({ udzial }: { udzial: number }) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.timing(a, { toValue: 1, duration: 900, delay: 150, easing: WEJSCIE,
                         useNativeDriver: false }).start();
  }, [udzial]);
  const proc = Math.max(3, Math.min(97, udzial * 100));
  return (
    <View style={{ marginTop: 12 }}>
      <View style={s.track}>
        <Animated.View style={[s.buy, { width: a.interpolate({ inputRange: [0, 1],
                                                              outputRange: ["50%", `${proc}%`] }) }]} />
      </View>
      <View style={s.wagaLabels}>
        <Text style={[s.wagaTxt, { color: C.green }]}>kupno {Math.round(udzial * 100)}%</Text>
        <Text style={[s.wagaTxt, { color: C.red }]}>sprzedaż {Math.round((1 - udzial) * 100)}%</Text>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  stats: { flexDirection: "row", gap: 8 },
  stat: { flex: 1, backgroundColor: C.elev, borderRadius: 12, padding: 10 },
  statL: { color: C.dim, fontSize: 10, fontWeight: "700", letterSpacing: 0.6, textTransform: "uppercase" },
  statV: { color: C.text, fontSize: 19, fontWeight: "800", marginTop: 3 },
  statS: { color: C.dim, fontSize: 10.5, marginTop: 1 },
  track: { height: 7, borderRadius: 4, backgroundColor: C.red, overflow: "hidden" },
  buy: { height: 7, backgroundColor: C.green, borderRightWidth: 2, borderRightColor: C.card },
  wagaLabels: { flexDirection: "row", justifyContent: "space-between", marginTop: 5 },
  wagaTxt: { fontSize: 10.5, fontWeight: "700" },
  locked: {
    flexDirection: "row", alignItems: "center", gap: 12, marginTop: 12, padding: 12,
    borderRadius: 14, borderWidth: 1, borderColor: "rgba(255,196,92,.4)",
    backgroundColor: "rgba(255,196,92,.06)",
  },
  blurRow: { flexDirection: "row" },
  lockedTitle: { color: "#ffc45c", fontSize: 13.5, fontWeight: "800" },
  lockedTxt: { color: C.muted, fontSize: 11.5, marginTop: 2, lineHeight: 16 },
  lockedCta: { color: "#ffc45c", fontSize: 13, fontWeight: "800" },
  person: {
    flexDirection: "row", alignItems: "center", paddingVertical: 10,
    borderBottomWidth: 1, borderBottomColor: "rgba(33,41,56,.7)",
  },
  name: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  role: { color: C.dim, fontSize: 11, marginTop: 2 },
  last: { fontSize: 11.5, fontWeight: "800" },
  amt: { color: C.muted, fontSize: 11, marginTop: 2 },
  toggles: { marginTop: 8, borderTopWidth: 1, borderTopColor: C.border },
  cicho: { color: C.muted, fontSize: 12.5, lineHeight: 18 },
});

