/** Otwieranie karty spółki z dowolnego miejsca aplikacji.
 *
 *  Powód istnienia: kartę spółki chce otwierać także skład funduszu w Skanerze ETF,
 *  ale `CompanyScreen` sam pokazuje prześwietlenie funduszu — import w obie strony
 *  zrobiłby cykl, a zagnieżdżanie okna w oknie kończy się modalem w modalu.
 *
 *  Zamiast tego App.tsx rejestruje tu jedną funkcję i trzyma pojedyncze okno na
 *  samej górze drzewa. Każdy ekran może poprosić o otwarcie, nikt nikogo nie importuje.
 */

type Opener = (symbol: string) => void;

let opener: Opener | null = null;

export function setCompanyOpener(fn: Opener | null) {
  opener = fn;
}

/** Zwraca false, gdy nie ma kto obsłużyć — wołający może wtedy nic nie robić. */
export function openCompany(symbol: string): boolean {
  const s = (symbol || "").trim();
  if (!s || !opener) return false;
  opener(s);
  return true;
}
