/** Tła aplikacji — katalog i przełącznik.
 *
 *  Dodanie kolejnego tła to jeden wpis w `BACKGROUNDS` (plus zdjęcie w
 *  `assets/backgrounds/`, jeśli tło jest oparte na zdjęciu). Reszta apki niczego
 *  o tłach nie wie: `App` rysuje `<AppBackground>` pod ekranami, a ekran „Więcej"
 *  pokazuje `<BackgroundPicker>`.
 *
 *  Wybór trzymamy na telefonie (`getPref`/`setPref`), więc przeżywa restart apki.
 */
import React from "react";
import { StyleSheet, Text, View } from "react-native";
import { C, T } from "../theme";
import { Press } from "../ui";
import AsciiEffect, { AsciiPreset } from "./AsciiEffect";
import AuroraEffect from "./AuroraEffect";
import PaperShaderEffect from "./PaperShaderEffect";
import { rgb } from "./ShaderCanvas";

import Icon from "../ui/Icon";
export const BG_PREF = "background";

/** Tło na start. „Spadające gwiazdy" zamiast gładkiej planszy, żeby apka od
 *  pierwszego uruchomienia wyglądała tak, jak ma wyglądać. Kto raz wybrał inne,
 *  ma je zapisane w `getPref` i tej zmiany nie zauważy. */
export const DEFAULT_BG = "gwiazdy";

/** Kolor tła apki jako podkład każdego shadera — nic nie świeci w próżni. */
const BASE = rgb(C.bg);

/** Wspólny fundament ustawień ASCII — przepisy z 21st.dev różnią się od niego
 *  tylko kilkoma polami, więc reszta nie musi się powtarzać przy każdym tle. */
const ASCII_BASE: Omit<AsciiPreset, "source"> = {
  mode: "characters",
  cellPx: 16,
  cover: true,
  fit: 1,
  offsetY: 0.5,
  contrast: 115,
  brightness: 0,
  saturation: 100,
  grayscale: 92,
  edge: 40,
  coverage: 100,
  invert: false,
  ambient: 0,
  photo: 55,
  ink: "#dbe7ff",
  inkMix: 55,
  tint: "#000000",
  tintOpacity: 45,
  bloom: 60,
  chromatic: 40,
  scanLines: 28,
  vignette: 38,
  filmGrain: 40,
  glitch: 0,
  flicker: 60,
  speed: 9,
  fps: 18,
};

/** Logo Portevo w znakach — w barwach marki, ze zdjęciem prześwitującym spod
 *  siatki. Znaki są tu fakturą na logo, a nie zamiennikiem logo.
 *  Bierzemy sam znak (łódka), bez napisu: litery w siatce znaków i tak się
 *  rozpadały, a szerszy kadr lepiej wypełnia ekran. */
const LOGO: AsciiPreset = {
  ...ASCII_BASE,
  source: require("../../assets/logo-portevo-mark.png"),
  cover: false,
  fit: 0.98,
  offsetY: 0.5,
  cellPx: 12,
  grayscale: 20,
  saturation: 125,
  inkMix: 30,
  tintOpacity: 20,
  ambient: 14,
  photo: 45,
};

/** Miasto — przepis „nm": drobna siatka znaków na panoramie, prawie bez koloru. */
const MIASTO: AsciiPreset = {
  ...ASCII_BASE,
  source: require("../../assets/backgrounds/miasto.jpg"),
  cellPx: 10,
  brightness: 8,
  grayscale: 70,
  inkMix: 45,
  photo: 70,
  bloom: 40,
};

/** Kasa — przepis „All about the Benjamins": bloki dithera, zielona nakładka
 *  i glitch. Zdjęcie jest odwrócone, bo na ciemnej apce mają świecić banknoty,
 *  a nie biała kartka pod nimi. */
const KASA: AsciiPreset = {
  ...ASCII_BASE,
  source: require("../../assets/backgrounds/kasa.jpg"),
  mode: "dither",
  cellPx: 14,
  coverage: 96,
  invert: true,
  grayscale: 0,
  saturation: 130,
  ink: "#00ff66",
  inkMix: 35,
  tint: "#00ff66",
  tintOpacity: 45,
  glitch: 20,
  photo: 50,
};

export type Background = {
  id: string;
  label: string;
  hint: string;
  /** ciemna zasłona nad efektem — bez niej karty i liczby walczą z tłem o uwagę */
  scrim: number;
  render?: (o: { fps?: number; downscale?: number }) => React.ReactNode;
};

export const BACKGROUNDS: Background[] = [
  {
    id: "plain",
    label: "Podstawowe",
    hint: "Gładka, ciemna plansza — najlepiej czytelna i najoszczędniejsza dla baterii.",
    scrim: 0,
  },
  {
    id: "logo",
    label: "Logo w znakach",
    hint: "Logo Portevo przemielone na zera i jedynki, w barwach marki.",
    scrim: 0.3,
    render: (o) => <AsciiEffect preset={LOGO} bg={BASE} {...o} />,
  },
  {
    id: "miasto",
    label: "Miasto",
    hint: "Panorama miasta w drobnej siatce znaków — szarość, winieta, linie obrazu.",
    scrim: 0.34,
    render: (o) => <AsciiEffect preset={MIASTO} bg={BASE} {...o} />,
  },
  {
    id: "kasa",
    label: "Kasa",
    hint: "Banknoty w blokach dithera, zielona poświata i przeskakujące pasy.",
    scrim: 0.38,
    render: (o) => <AsciiEffect preset={KASA} bg={BASE} {...o} />,
  },
  {
    id: "gwiazdy",
    label: "Spadające gwiazdy",
    hint: "Smugi zorzy przelatujące w poprzek ekranu. Najbardziej obciąża telefon.",
    scrim: 0.4,
    render: (o) => <AuroraEffect bg={BASE} {...o} />,
  },
  {
    id: "shader",
    label: "Plamy światła",
    hint: "Karmazyn i morska zieleń oddychające w ciemności, z pierścieniem energii.",
    scrim: 0.36,
    render: (o) => <PaperShaderEffect bg={BASE} {...o} />,
  },
];

export const findBackground = (id: string) =>
  BACKGROUNDS.find((b) => b.id === id) || BACKGROUNDS[0];

/** Warstwa pod całą aplikacją. Nie łapie dotyku — ekrany działają jak zwykle. */
export function AppBackground({ id }: { id: string }) {
  const bg = findBackground(id);
  if (!bg.render) return null;
  return (
    <View style={StyleSheet.absoluteFill} pointerEvents="none">
      {bg.render({})}
      {bg.scrim > 0 && (
        <View style={[StyleSheet.absoluteFill, { backgroundColor: `rgba(8,11,17,${bg.scrim})` }]} />
      )}
    </View>
  );
}

/** Wybór tła w ustawieniach — każdy kafelek pokazuje efekt na żywo.
 *
 *  Podglądy chodzą tylko wtedy, gdy zakładka „Więcej" jest na wierzchu: ekrany
 *  zostają zamontowane po przełączeniu, a sześć kontekstów graficznych mielących
 *  w tle zjadałoby baterię bez powodu. */
export function BackgroundPicker({
  value, onChange, live = true,
}: {
  value: string;
  onChange: (id: string) => void;
  live?: boolean;
}) {
  return (
    <View style={{ gap: 10 }}>
      {BACKGROUNDS.map((b) => {
        const on = b.id === value;
        return (
          <Press key={b.id} onPress={() => onChange(b.id)} scaleTo={0.985}
                 style={[s.card, on && s.cardOn]}>
            <View style={s.preview}>
              {live && b.render ? b.render({ fps: 10, downscale: 2 }) : null}
              {b.render && b.scrim > 0 && (
                <View style={[StyleSheet.absoluteFill,
                              { backgroundColor: `rgba(8,11,17,${bTintOf(b)})` }]} />
              )}
            </View>
            <View style={s.row}>
              <View style={{ flex: 1 }}>
                <Text style={[s.label, on && { color: C.green }]}>{b.label}</Text>
                <Text style={s.hint}>{b.hint}</Text>
              </View>
              <View style={[s.mark, on && s.markOn]}>
                {on && <Icon name="ptaszek" size={11} color={C.text} />}
              </View>
            </View>
          </Press>
        );
      })}
    </View>
  );
}

/** W podglądzie przygaszamy słabiej niż na ekranie — kafelek ma pokazać efekt,
 *  a nie to, jak ładnie chowa się pod treścią. */
const bTintOf = (b: Background) => Math.max(0, b.scrim - 0.18).toFixed(2);

const s = StyleSheet.create({
  card: {
    backgroundColor: C.card, borderColor: C.border, borderWidth: 1, borderRadius: 16,
    overflow: "hidden",
  },
  cardOn: { borderColor: "rgba(47,212,138,.5)" },
  preview: { height: 78, backgroundColor: C.bg, overflow: "hidden" },
  row: { flexDirection: "row", alignItems: "center", padding: 13, gap: 12 },
  label: { color: C.text, ...T.h2, fontSize: 15 },
  hint: { color: C.muted, fontSize: 12, lineHeight: 17, marginTop: 3 },
  mark: {
    width: 24, height: 24, borderRadius: 12, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center",
  },
  markOn: { borderColor: C.green, backgroundColor: C.greenDim },
  markTxt: { color: C.green, fontSize: 13, fontWeight: "800" },
});
