/** Prześwietlenie jednego funduszu — pełna karta z wyjaśnieniami.
 *
 *  Reguła redakcyjna całego ekranu: **każda liczba ma obok siebie zdanie po polsku,
 *  co ona znaczy**. Procent składu przeliczamy na złotówki z tysiąca, opłatę roczną
 *  na realny koszt, zmienność na „ile potrafiło spaść". Ktoś, kto pierwszy raz widzi
 *  ETF, ma po tym ekranie wiedzieć, co kupuje — a nie zobaczyć ładny wykres.
 */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { EtfDetail, EtfHolding, EtfSector, getEtfDetail } from "../../api";
import { openCompany } from "../../companyRouter";
import Logo from "../../components/Logo";
import ChartFullscreen from "../../components/ChartFullscreen";
import { LineChart } from "../../components/MiniChart";
import PortfolioChart from "../../components/PortfolioChart";
import { C, chartColor, fmtCur, T } from "../../theme";
import { Bar, Card, FadeIn, MetalButton } from "../../ui";

import Icon from "../../ui/Icon";
const GOLD = "#ffc45c";

const RANGES = [
  { id: "1m", label: "1M", days: 22 },
  { id: "3m", label: "3M", days: 66 },
  { id: "6m", label: "6M", days: 130 },
  { id: "1r", label: "1R", days: 260 },
];

export default function EtfDetailModal({
  symbol, onClose, onCompare,
}: {
  symbol: string;
  onClose: () => void;
  onCompare?: (symbol: string) => void;
}) {
  const [d, setD] = useState<EtfDetail | null>(null);
  const [err, setErr] = useState("");
  const [range, setRange] = useState("1r");
  const [open, setOpen] = useState<string | null>(null);
  const [full, setFull] = useState(false);

  useEffect(() => {
    let alive = true;
    setD(null); setErr("");
    getEtfDetail(symbol)
      .then((r) => { if (alive) setD(r); })
      .catch((e) => { if (alive) setErr(e?.message || "Nie udało się pobrać danych funduszu"); });
    return () => { alive = false; };
  }, [symbol]);

  const toggle = useCallback((k: string) => setOpen((o) => (o === k ? null : k)), []);

  const days = RANGES.find((r) => r.id === range)?.days || 260;
  const chartValues = (d?.chart.values || []).slice(-days);
  const chartDates = (d?.chart.dates || []).slice(-days);
  const rangeChange = chartValues.length > 1
    ? (chartValues[chartValues.length - 1] / chartValues[0] - 1) * 100 : null;

  return (
    <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}>
      <View style={s.root}>
        <View style={s.bar}>
          <View style={{ flex: 1 }}>
            <Text style={s.barTitle} numberOfLines={1}>{d?.name || symbol}</Text>
            <Text style={s.barSub} numberOfLines={1}>
              {symbol}{d?.exchange ? ` · ${d.exchange}` : ""}
            </Text>
          </View>
          <Pressable onPress={onClose} hitSlop={12} style={s.close}>
            <Icon name="zamknij" size={15} color={C.muted} />
          </Pressable>
        </View>

        {!d && !err && (
          <View style={s.center}>
            <ActivityIndicator color={GOLD} size="large" />
            <Text style={s.loading}>Rozkładam fundusz na czynniki pierwsze…</Text>
          </View>
        )}
        {!!err && <View style={s.center}><Text style={s.errTxt}>{err}</Text></View>}

        {d && (
          <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
            {!!d.error && <Text style={s.warnLine}>{d.error}</Text>}
            {!!d.price_note && <Text style={s.warnLine}>{d.price_note}</Text>}

            {/* ---------------- nagłówek: cena i przynależność */}
            <FadeIn>
              <View style={s.priceRow}>
                <Text style={s.price}>
                  {d.price != null ? fmtCur(d.price, d.currency, 2) : "—"}
                </Text>
                {d.change_pct != null && (
                  <Text style={[s.change, { color: d.change_pct >= 0 ? C.green : C.red }]}>
                    {d.change_pct >= 0 ? "+" : ""}{d.change_pct.toFixed(2)}% dziś
                  </Text>
                )}
              </View>
              {!!d.currency_note && <Text style={s.note}>{d.currency_note}</Text>}

              <View style={s.tags}>
                {!!d.catalog.region_label && <Tag text={d.catalog.region_label} />}
                {!!d.catalog.sector_label && <Tag text={d.catalog.sector_label} />}
                {!!d.catalog.asset_label && <Tag text={d.catalog.asset_label} />}
                {d.catalog.acc != null && (
                  <Tag text={d.catalog.acc ? "Akumulujący" : "Wypłacający"} tone={GOLD} />
                )}
              </View>

              {!!d.catalog.note && <Text style={s.lead}>{d.catalog.note}</Text>}
              {/* fundusze z GPW: Yahoo o nich milczy, więc opis zawartości mamy własny */}
              {!!d.about && <Text style={s.about}>{d.about}</Text>}
            </FadeIn>

            {/* ---------------- wykres */}
            <FadeIn delay={60}>
              <Card style={[s.card, { marginTop: 16 }]}>
                <View style={s.chartHead}>
                  <View>
                    <Text style={s.cardTitle}>Notowania</Text>
                    {rangeChange != null && (
                      <Text style={[s.chartChange, { color: rangeChange >= 0 ? C.green : C.red }]}>
                        {rangeChange >= 0 ? "+" : ""}{rangeChange.toFixed(2)}% w tym okresie
                      </Text>
                    )}
                  </View>
                  <View style={{ flexDirection: "row", gap: 5 }}>
                    {RANGES.map((r) => (
                      <MetalButton key={r.id} label={r.label} size="sm" tone="amber"
                                   active={range === r.id} liquid
                                   onPress={() => setRange(r.id)} />
                    ))}
                    <MetalButton label="⤢" size="sm" tone="amber" round
                                 onPress={() => setFull(true)}
                                 textStyle={{ fontSize: 15, lineHeight: 19 }} />
                  </View>
                </View>
                <View style={{ marginTop: 14 }}>
                  <LineChart
                    values={chartValues}
                    labels={[chartDates[0] || "", chartDates[chartDates.length - 1] || ""]}
                    fmt={(v) => fmtCur(v, d.currency, 0)}
                    color={rangeChange != null && rangeChange < 0 ? C.red : C.green}
                  />
                </View>
              </Card>
            </FadeIn>

            {/* ---------------- wyniki */}
            <FadeIn delay={100}>
              <Card style={[s.card, { marginTop: 11 }]}>
                <Text style={s.cardTitle}>Jak sobie radził</Text>
                <View style={s.perfRow}>
                  <Perf label="1 mies." v={d.performance.m1} />
                  <Perf label="3 mies." v={d.performance.m3} />
                  <Perf label="6 mies." v={d.performance.m6} />
                  <Perf label="12 mies." v={d.performance.y1} />
                  <Perf label="Od stycznia" v={d.performance.ytd} />
                </View>
                <Text style={s.cardHint}>
                  {!!d.profile.index_label && `Fundusz odwzorowuje indeks ${d.profile.index_label}. `}
                  Wyniki liczone w walucie notowania. Twój wynik w złotówkach różni się o
                  zmianę kursu waluty w tym samym okresie.
                </Text>
              </Card>
            </FadeIn>

            {/* ---------------- ryzyko */}
            <FadeIn delay={140}>
              <Card style={[s.card, s.riskCard, { marginTop: 11 }]}>
                <View style={s.riskHead}>
                  <View style={{ flex: 1 }}>
                    <Text style={s.cardTitle}>Ryzyko</Text>
                    <Text style={[s.riskLabel, { color: riskColor(d.risk.score) }]}>
                      {d.risk.label}
                    </Text>
                  </View>
                  <RiskDots score={d.risk.score} />
                </View>
                {!!d.risk.desc && <Text style={s.cardHint}>{d.risk.desc}</Text>}

                <View style={s.riskStats}>
                  <Stat label="Zmienność roczna"
                        value={d.risk.vol_pct != null ? `${d.risk.vol_pct.toFixed(1)}%` : "—"}
                        hint="typowy rozrzut wyniku w skali roku" />
                  <Stat label="Największy spadek"
                        value={d.risk.max_dd_pct != null ? `−${d.risk.max_dd_pct.toFixed(1)}%` : "—"}
                        hint="od szczytu do dołka w ostatnim roku"
                        tone={d.risk.max_dd_pct && d.risk.max_dd_pct > 20 ? C.red : undefined} />
                </View>

                {d.risk.notes.map((n, i) => (
                  <Text key={i} style={s.riskNote}>{n}</Text>
                ))}
              </Card>
            </FadeIn>

            {/* ---------------- koszt */}
            {d.profile.ter_pct != null && (
              <FadeIn delay={170}>
                <Card style={[s.card, { marginTop: 11 }]}>
                  <Text style={s.cardTitle}>Ile Cię to kosztuje</Text>
                  <View style={s.costRow}>
                    <Text style={s.costBig}>{d.profile.ter_pct.toFixed(2)}%</Text>
                    <Text style={s.costUnit}>rocznie</Text>
                  </View>
                  <View style={s.costTable}>
                    {[10000, 50000, 100000].map((amount) => (
                      <View key={amount} style={s.costLine}>
                        <Text style={s.costWhat}>
                          przy {amount.toLocaleString("pl-PL")} zł
                        </Text>
                        <Text style={s.costVal}>
                          ≈ {Math.round(amount * d.profile.ter_pct! / 100).toLocaleString("pl-PL")} zł / rok
                        </Text>
                      </View>
                    ))}
                  </View>
                  <Text style={s.cardHint}>
                    Opłata pobierana jest po cichu z wyceny — nie zobaczysz jej jako osobnej
                    transakcji na rachunku. To jedyny koszt, który ponosisz niezależnie od wyniku.
                  </Text>
                </Card>
              </FadeIn>
            )}

            {/* ---------------- kraje */}
            {d.countries.length > 0 && (
              <FadeIn delay={185}>
                <Card style={[s.card, { marginTop: 11 }]}>
                  <Text style={s.cardTitle}>Gdzie to pracuje</Text>
                  <Text style={s.cardHint}>
                    Kraje giełd, na których notowane są największe pozycje funduszu.
                  </Text>
                  <View style={s.flagRow}>
                    {d.countries.map((cn) => (
                      <View key={cn.code} style={s.flagChip}>
                        <Text style={s.flagIcon}>{cn.flag}</Text>
                        <View>
                          <Text style={s.flagPct}>{cn.pct.toFixed(0)}%</Text>
                          <Text style={s.flagName} numberOfLines={1}>{cn.name}</Text>
                        </View>
                      </View>
                    ))}
                  </View>
                  <View style={s.flagBar}>
                    {d.countries.map((cn, i) => (
                      <View key={cn.code}
                            style={{ flex: cn.pct, backgroundColor: chartColor(i), height: "100%" }} />
                    ))}
                  </View>
                </Card>
              </FadeIn>
            )}

            {/* ---------------- skład */}
            {d.holdings.length > 0 && (
              <FadeIn delay={200}>
                <Card style={[s.card, { marginTop: 11 }]}>
                  <Text style={s.cardTitle}>Co jest w środku</Text>
                  <Text style={s.cardHint}>
                    {d.holdings[0]?.is_asset
                      ? "Ten fundusz nie kupuje spółek — poniżej jest to, co w nim faktycznie siedzi."
                      : <>
                          {d.top10_pct != null
                            ? `Dziesięć największych pozycji to ${d.top10_pct.toFixed(1)}% funduszu. `
                            : ""}
                          Dotknij kółka z logo, żeby otworzyć kartę spółki. Dotknij wiersza obok —
                          zobaczysz, ile Twoich pieniędzy w niej pracuje.
                        </>}
                  </Text>
                  {!!d.holdings_note && <Text style={s.sourceNote}>{d.holdings_note}</Text>}
                  {d.holdings.map((h, i) => (
                    <Holding key={(h.symbol || "rest") + i} h={h} i={i}
                             open={open === `h${i}`} onPress={() => toggle(`h${i}`)} />
                  ))}
                </Card>
              </FadeIn>
            )}

            {/* ---------------- sektory */}
            {d.sectors.length > 0 && (
              <FadeIn delay={230}>
                <Card style={[s.card, { marginTop: 11 }]}>
                  <Text style={s.cardTitle}>Na czym stoi ten fundusz</Text>
                  <Text style={s.cardHint}>
                    Podział na branże. Dotknij, żeby dowiedzieć się, co dana branża robi
                    i kiedy jej się wiedzie.
                  </Text>
                  {d.sectors.map((sec, i) => (
                    <Sector key={sec.id} sec={sec} i={i}
                            open={open === `s${i}`} onPress={() => toggle(`s${i}`)} />
                  ))}
                </Card>
              </FadeIn>
            )}

            {/* ---------------- struktura aktywów */}
            {(d.composition.bond_pct > 1 || d.composition.cash_pct > 1) && (
              <FadeIn delay={250}>
                <Card style={[s.card, { marginTop: 11 }]}>
                  <Text style={s.cardTitle}>Struktura</Text>
                  <View style={{ marginTop: 12, gap: 11 }}>
                    <CompLine label="Akcje" pct={d.composition.stock_pct} color={C.green} />
                    <CompLine label="Obligacje" pct={d.composition.bond_pct} color={C.accent} />
                    <CompLine label="Gotówka" pct={d.composition.cash_pct} color={C.muted} />
                    <CompLine label="Pozostałe" pct={d.composition.other_pct} color={C.violet} />
                  </View>
                </Card>
              </FadeIn>
            )}

            {/* ---------------- wyjaśnienia */}
            {d.explain.length > 0 && (
              <FadeIn delay={280}>
                <Text style={s.sectionTitle}>Zanim kupisz — warto wiedzieć</Text>
                {d.explain.map((e, i) => (
                  <Explain key={i} title={e.title} text={e.text}
                           open={open === `e${i}`} onPress={() => toggle(`e${i}`)} />
                ))}
              </FadeIn>
            )}

            {!!onCompare && (
              <MetalButton label="Dodaj do porównania" tone="amber" active liquid full
                           style={{ marginTop: 18 }}
                           onPress={() => { onCompare(d.symbol); onClose(); }} />
            )}

            <Text style={s.legal}>
              {d.sources?.length
                ? `Dane: ${d.sources.join(" i ")}. `
                : "Dane z Yahoo Finance. "}
              Skład aktualizowany przez dostawcę funduszu z opóźnieniem.
              To materiał informacyjny, nie rekomendacja inwestycyjna.
            </Text>
          </ScrollView>
        )}

        {/* ten sam wykres na cały ekran — z przybliżaniem i przesuwaniem */}
        <ChartFullscreen
          visible={full} onClose={() => setFull(false)}
          title={d?.name || symbol}
          subtitle={[symbol, d?.price != null ? fmtCur(d.price, d.currency, 2) : null]
            .filter(Boolean).join(" · ")}
          hint="Przeciągnij, aby przesunąć wykres · szczypnij (albo kółko myszy), aby przybliżyć · przytrzymaj, aby odczytać wartość"
          controls={
            <View style={{ flexDirection: "row", gap: 5, flexWrap: "wrap" }}>
              {RANGES.map((r) => (
                <MetalButton key={r.id} label={r.label} size="sm" tone="amber"
                             active={range === r.id} liquid onPress={() => setRange(r.id)} />
              ))}
            </View>
          }
        >
          {({ width, height }) => (
            <PortfolioChart
              dates={chartDates} values={chartValues} mode="value" zoomable
              width={width} height={height}
              positive={(rangeChange ?? 0) >= 0}
              fmtValue={(v) => fmtCur(v, d?.currency || "USD", 2)}
            />
          )}
        </ChartFullscreen>
      </View>
    </Modal>
  );
}

/* ------------------------------------------------------------- składowe */

function Tag({ text, tone }: { text: string; tone?: string }) {
  return (
    <View style={[s.tag, tone ? { borderColor: tone + "88", backgroundColor: tone + "1a" } : null]}>
      <Text style={[s.tagTxt, tone ? { color: tone } : null]}>{text}</Text>
    </View>
  );
}

function Perf({ label, v }: { label: string; v: number | null }) {
  return (
    <View style={s.perfCell}>
      <Text style={s.perfLabel}>{label}</Text>
      <Text style={[s.perfVal, { color: v == null ? C.dim : v >= 0 ? C.green : C.red }]}>
        {v == null ? "—" : `${v >= 0 ? "+" : ""}${v.toFixed(1)}%`}
      </Text>
    </View>
  );
}

function Stat({ label, value, hint, tone }: {
  label: string; value: string; hint: string; tone?: string;
}) {
  return (
    <View style={{ flex: 1 }}>
      <Text style={s.statLabel}>{label}</Text>
      <Text style={[s.statVal, tone ? { color: tone } : null]}>{value}</Text>
      <Text style={s.statHint}>{hint}</Text>
    </View>
  );
}

function riskColor(score: number | null) {
  if (score == null) return C.dim;
  return [C.green, C.green, C.amber, "#ff8a3d", C.red][Math.min(4, Math.max(0, score - 1))];
}

/** Pięć kropek — ile zapalonych, taki poziom ryzyka. Czytelne bez czytania. */
function RiskDots({ score }: { score: number | null }) {
  const col = riskColor(score);
  return (
    <View style={{ flexDirection: "row", gap: 5 }}>
      {[1, 2, 3, 4, 5].map((i) => (
        <View key={i} style={[
          s.dot,
          { backgroundColor: score != null && i <= score ? col : "rgba(255,255,255,.10)" },
        ]} />
      ))}
    </View>
  );
}

/** Wiersz składu funduszu.
 *
 *  Dwie strefy dotyku w jednym wierszu: kółko z logo prowadzi do karty spółki,
 *  reszta wiersza rozwija wyjaśnienie „ile z tysiąca". Ostatni wiersz („Pozostałe
 *  spółki") nie prowadzi nigdzie — to worek zbiorczy, nie konkretny walor.
 */
function Holding({ h, i, open, onPress }: {
  h: EtfHolding; i: number; open: boolean; onPress: () => void;
}) {
  const rest = Boolean(h.is_rest);
  const asset = Boolean(h.is_asset);
  const canOpen = !rest && !asset && !!h.symbol;

  return (
    <Pressable onPress={onPress} style={[s.itemRow, rest && s.itemRest]}>
      <View style={s.itemTop}>
        {rest ? (
          <View style={[s.avatar, s.avatarRest]}>
            <Text style={s.avatarRestTxt}>+{Math.max(0, Math.round(h.pct / 3))}</Text>
          </View>
        ) : (
          <Pressable onPress={() => canOpen && openCompany(h.symbol)} hitSlop={6}
                     disabled={!canOpen}>
            <View style={[s.avatar, canOpen && s.avatarLive]}>
              <Logo ticker={h.symbol || h.name} name={h.name} size={32} />
            </View>
          </Pressable>
        )}

        <View style={{ flex: 1 }}>
          <Text style={[s.itemName, rest && { color: C.muted }]} numberOfLines={1}>{h.name}</Text>
          <Text style={s.itemSym}>
            {rest ? "reszta koszyka"
                  : asset ? "cała zawartość funduszu"
                  : (h.symbol || `pozycja ${i + 1}`)}
          </Text>
        </View>
        <Text style={s.itemPct}>{h.pct.toFixed(2)}%</Text>
      </View>

      <View style={{ marginTop: 8 }}>
        <Bar pct={rest || asset ? h.pct : Math.min(100, h.pct * 4)}
             color={rest ? C.dim : chartColor(i)} delay={i * 35} />
      </View>

      {open && (
        <View style={s.itemExplain}>
          <Text style={s.itemExplainTxt}>
            {rest
              ? <>Poza dziesiątką powyżej fundusz trzyma jeszcze <Text style={s.b}>{h.pct.toFixed(1)}%</Text>{" "}
                  kapitału rozsianego po pozostałych spółkach z indeksu. To ta część, dzięki której
                  fundusz jest naprawdę zdywersyfikowany — dostawca nie publikuje jej w całości.</>
              : asset
              ? <>Tu pracuje <Text style={s.b}>całość</Text> wpłaty — z każdego 1000 zł wszystkie
                  1000 zł. Nie ma podziału na spółki ani branże, więc o wyniku decyduje jedna
                  wycena i nic poza nią.</>
              : <>Z każdego <Text style={s.b}>1000 zł</Text> wpłaconego do funduszu około{" "}
                  <Text style={s.b}>{h.per_1000.toFixed(2)} zł</Text> pracuje w tej spółce.
                  Przy 10 000 zł to {(h.per_1000 * 10).toFixed(0)} zł, przy 50 000 zł —{" "}
                  {(h.per_1000 * 50).toFixed(0)} zł.</>}
          </Text>
          {canOpen && (
            <Pressable onPress={() => openCompany(h.symbol)} hitSlop={6} style={{ marginTop: 10 }}>
              <Text style={s.goTxt}>Otwórz kartę {h.symbol} →</Text>
            </Pressable>
          )}
        </View>
      )}
    </Pressable>
  );
}

function Sector({ sec, i, open, onPress }: {
  sec: EtfSector; i: number; open: boolean; onPress: () => void;
}) {
  return (
    <Pressable onPress={onPress} style={s.itemRow}>
      <View style={s.itemTop}>
        <View style={[s.secDot, { backgroundColor: chartColor(i) }]} />
        <Text style={[s.itemName, { flex: 1 }]} numberOfLines={1}>{sec.label}</Text>
        <Text style={s.itemPct}>{sec.pct.toFixed(1)}%</Text>
      </View>
      <View style={{ marginTop: 7 }}>
        <Bar pct={sec.pct} color={chartColor(i)} delay={i * 35} />
      </View>
      {open && !!sec.desc && (
        <Text style={s.itemExplain}>
          {sec.desc}{"\n\n"}
          Ta branża to <Text style={s.b}>{sec.pct.toFixed(1)}%</Text> funduszu — z 10 000 zł
          około {Math.round(100 * sec.pct)} zł.
        </Text>
      )}
    </Pressable>
  );
}

function CompLine({ label, pct, color }: { label: string; pct: number; color: string }) {
  if (!pct || pct < 0.05) return null;
  return (
    <View>
      <View style={{ flexDirection: "row", justifyContent: "space-between", marginBottom: 6 }}>
        <Text style={s.compLabel}>{label}</Text>
        <Text style={s.compPct}>{pct.toFixed(1)}%</Text>
      </View>
      <Bar pct={pct} color={color} />
    </View>
  );
}

/** Sekcja „co to znaczy" — rozwijana, żeby ekran nie był ścianą tekstu. */
function Explain({ title, text, open, onPress }: {
  title: string; text: string; open: boolean; onPress: () => void;
}) {
  return (
    <Pressable onPress={onPress}>
      <Card style={[s.explain, open && s.explainOn]}>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
          <Text style={[s.explainTitle, { flex: 1 }]}>{title}</Text>
          <Text style={[s.explainPlus, open && { color: GOLD }]}>{open ? "−" : "+"}</Text>
        </View>
        {open && <Markdown text={text} />}
      </Card>
    </Pressable>
  );
}

/** Minimalny „markdown": tylko **pogrubienie**. Tyle wystarcza w opisach,
 *  a pełna biblioteka byłaby kolejną zależnością do pilnowania. */
function Markdown({ text }: { text: string }) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return (
    <Text style={s.explainTxt}>
      {parts.map((p, i) =>
        p.startsWith("**") && p.endsWith("**")
          ? <Text key={i} style={s.b}>{p.slice(2, -2)}</Text>
          : <Text key={i}>{p}</Text>)}
    </Text>
  );
}

