/** Portfele i majątek — sekcja, która pojawia się dopiero, gdy jest co pokazywać.
 *
 *  **Warunek widoczności jest tu najważniejszą decyzją.** Kto ma jeden rachunek
 *  i nic poza nim, nie zobaczy tej sekcji w ogóle — bo „Portfele: 1" i „Majątek:
 *  brak" to dwa wiersze mówiące, że nic tu nie ma. Sekcja włącza się dopiero
 *  wtedy, gdy powstała pierwsza rzecz do porównania: drugi portfel albo pierwsze
 *  aktywo spoza rachunku maklerskiego.
 *
 *  Dalej wszystko kręci się wokół jednego rozróżnienia: **skąd wzięła się
 *  liczba.** Złoto wycenia rynek, mieszkanie wyceniłeś ty pół roku temu — to
 *  są dwie zupełnie różne liczby co do wiarygodności i pokazywanie ich tą samą
 *  czcionką byłoby kłamstwem przez przemilczenie. Stąd znaczki „rynek" / „Twoja
 *  wycena" i stąd podpowiedź o inflacji przy starych wycenach.
 */
import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View,
} from "react-native";
import {
  dodajPortfel, dodajWycene, getWealth, przypiszKonto, usunAktywo, usunPortfel,
  WealthAktywo, WealthKonto, WealthOverview, WealthPortfel,
} from "../api";
import { portfolioChanged, usePortfolioVersion } from "../refresh";
import { C, chartColor, fmtNum, fmtPLN, fmtPLN0, plColor, plural, sgnPLN, T } from "../theme";
import { Card, FadeIn, MetalButton, SectionTitle } from "../ui";
import Icon, { maIkone } from "../ui/Icon";
import { Sparkline } from "./MiniChart";

/** Ile najwyżej wierszy majątku pokazujemy w karcie, zanim zwiniemy resztę. */
const WIDOCZNE = 4;

export default function WealthSection({ onZmiana }: { onZmiana?: () => void }) {
  const wersja = usePortfolioVersion();
  const [dane, setDane] = useState<WealthOverview | null>(null);
  const [blad, setBlad] = useState("");
  const [zarzadzaj, setZarzadzaj] = useState(false);
  const [szczegol, setSzczegol] = useState<WealthAktywo | null>(null);

  const wczytaj = useCallback(() => {
    getWealth().then((w) => { setDane(w); setBlad(""); })
      .catch((e) => setBlad(e?.message || ""));
  }, []);

  useEffect(() => { wczytaj(); }, [wczytaj, wersja]);

  const odswiez = useCallback(() => {
    wczytaj();
    // Majątek wchodzi też do Alokacji, więc zmiana tutaj musi dotrzeć dalej niż
    // do tej jednej sekcji.
    portfolioChanged();
    onZmiana?.();
  }, [wczytaj, onZmiana]);

  const aktywa = useMemo(() => {
    if (!dane) return [];
    return [...dane.portfele.flatMap((p) => p.aktywa), ...dane.bez_przypisania.aktywa];
  }, [dane]);

  if (!dane || blad) return null;

  // Grupa = portfel z zawartością. „Bez przypisania" liczy się jako grupa tylko
  // wtedy, gdy naprawdę coś w niej leży.
  const luzem = dane.bez_przypisania;
  const luzemNiepuste = luzem.konta.length > 0 || luzem.aktywa.length > 0;
  const grupy = dane.portfele.length + (luzemNiepuste ? 1 : 0);
  if (grupy < 2 && aktywa.length === 0) return null;

  const razem = dane.razem || 0;
  const udzial = (v: number) => (razem > 0 ? (v / razem) * 100 : 0);

  return (
    <FadeIn delay={120}>
      <View style={s.wrap}>
        <SectionTitle hint="Rachunki maklerskie i wszystko, o czym broker nie wie">
          Twój majątek
        </SectionTitle>

        <Card>
          <Text style={s.razemLabel}>Razem</Text>
          <Text style={s.razem}>{fmtPLN(razem)}</Text>

          {/* pasek podziału: rachunki kontra reszta — jedna kreska mówi to,
              co dwie liczby dopiero po chwili czytania */}
          <View style={s.pasek}>
            {dane.rachunki_razem > 0 && (
              <View style={[s.paskoCz, { flex: dane.rachunki_razem, backgroundColor: C.green }]} />
            )}
            {dane.majatek_razem > 0 && (
              <View style={[s.paskoCz, { flex: dane.majatek_razem, backgroundColor: C.gold }]} />
            )}
          </View>
          <View style={s.legenda}>
            <Legenda kolor={C.green} etykieta="Rachunki" kwota={dane.rachunki_razem}
                     pct={udzial(dane.rachunki_razem)} />
            <Legenda kolor={C.gold} etykieta="Majątek" kwota={dane.majatek_razem}
                     pct={udzial(dane.majatek_razem)} />
          </View>
        </Card>

        {dane.portfele.map((p, i) => (
          <KartaPortfela key={p.id} portfel={p} kolor={p.kolor || chartColor(i)}
                         udzial={udzial(p.wartosc)} zarzadzaj={zarzadzaj}
                         portfele={dane.portfele} onOdswiez={odswiez}
                         onAktywo={setSzczegol} />
        ))}

        {luzemNiepuste && (
          <KartaPortfela
            portfel={{
              id: "", nazwa: dane.portfele.length ? "Bez przypisania" : "Wszystko razem",
              kolor: C.dim, ikona: "", sort: 0, ...luzem,
            }}
            kolor={C.border2} udzial={udzial(luzem.wartosc)} zarzadzaj={zarzadzaj}
            portfele={dane.portfele} onOdswiez={odswiez} onAktywo={setSzczegol}
          />
        )}

        <View style={s.stopkaRzad}>
          <MetalButton label={zarzadzaj ? "Gotowe" : "Zarządzaj portfelami"} size="sm"
                       tone={zarzadzaj ? "green" : "steel"} round
                       onPress={() => setZarzadzaj((z) => !z)} />
        </View>

        {zarzadzaj && <NowyPortfel onDodany={odswiez} />}

        <SzczegolAktywa aktywo={szczegol} zamknij={() => setSzczegol(null)}
                        onZmiana={odswiez} />
      </View>
    </FadeIn>
  );
}

function Legenda({ kolor, etykieta, kwota, pct }: {
  kolor: string; etykieta: string; kwota: number; pct: number;
}) {
  return (
    <View style={s.legRzad}>
      <View style={[s.kropka, { backgroundColor: kolor }]} />
      <Text style={s.legEt}>{etykieta}</Text>
      <Text style={s.legKwota}>{fmtPLN0(kwota)} zł</Text>
      <Text style={s.legPct}>{pct.toFixed(0)}%</Text>
    </View>
  );
}

/* =========================================================== karta portfela */

function KartaPortfela({ portfel, kolor, udzial, zarzadzaj, portfele, onOdswiez, onAktywo }: {
  portfel: WealthPortfel; kolor: string; udzial: number; zarzadzaj: boolean;
  portfele: WealthPortfel[]; onOdswiez: () => void; onAktywo: (a: WealthAktywo) => void;
}) {
  const [rozwin, setRozwin] = useState(false);
  const pozycje = [...portfel.konta, ...portfel.aktywa];
  const widoczne = rozwin ? pozycje : pozycje.slice(0, WIDOCZNE);

  return (
    <Card style={[s.karta, { borderLeftColor: kolor, borderLeftWidth: 3 }]}>
      <View style={s.kartaGlowa}>
        <View style={{ flex: 1 }}>
          <View style={s.kartaTytul}>
            {/* Ikona portfela pochodzi z bazy, więc bywa jeszcze emoji sprzed
                zmiany na rysunki. Znaną nazwę rysujemy, nieznaną wypisujemy —
                zamiast pokazywać komuś surowe „metal" zamiast obrazka. */}
            {maIkone(portfel.ikona)
              ? <Icon name={portfel.ikona} size={16} color={kolor} />
              : !!portfel.ikona && <Text style={s.kartaNazwa}>{portfel.ikona}</Text>}
            <Text style={s.kartaNazwa} numberOfLines={1}>{portfel.nazwa}</Text>
          </View>
          <Text style={s.kartaMeta}>
            {portfel.konta.length > 0 && (
              `${portfel.konta.length} ${plural(portfel.konta.length, "rachunek", "rachunki", "rachunków")}`
            )}
            {portfel.konta.length > 0 && portfel.aktywa.length > 0 ? " · " : ""}
            {portfel.aktywa.length > 0 && (
              `${portfel.aktywa.length} ${plural(portfel.aktywa.length, "aktywo", "aktywa", "aktywów")}`
            )}
            {pozycje.length === 0 ? "pusty — przypisz do niego rachunek" : ""}
          </Text>
        </View>
        <View style={{ alignItems: "flex-end" }}>
          <Text style={s.kartaKwota}>{fmtPLN(portfel.wartosc)}</Text>
          <Text style={s.kartaPct}>{udzial.toFixed(0)}% majątku</Text>
        </View>
      </View>

      {widoczne.map((x: any, i) =>
        "konto" in x
          ? <WierszKonta key={`k${x.konto}`} konto={x} zarzadzaj={zarzadzaj}
                         portfele={portfele} onOdswiez={onOdswiez} />
          : <WierszAktywa key={`a${x.id}`} aktywo={x} onPress={() => onAktywo(x)} />
      )}

      {pozycje.length > WIDOCZNE && (
        <Pressable onPress={() => setRozwin((r) => !r)} hitSlop={8} style={s.wiecej}>
          <Text style={s.wiecejTxt}>
            {rozwin ? "Zwiń" : `Pokaż pozostałe ${pozycje.length - WIDOCZNE}`}
          </Text>
        </Pressable>
      )}

      {zarzadzaj && !!portfel.id && (
        <Pressable onPress={() => usunPortfel(portfel.id).then(onOdswiez).catch(() => {})}
                   hitSlop={8} style={s.usunPortfel}>
          <Text style={s.usunTxt}>Usuń portfel — rachunki i aktywa zostaną</Text>
        </Pressable>
      )}
    </Card>
  );
}

function WierszKonta({ konto, zarzadzaj, portfele, onOdswiez }: {
  konto: WealthKonto; zarzadzaj: boolean; portfele: WealthPortfel[]; onOdswiez: () => void;
}) {
  return (
    <View style={s.wiersz}>
      <View style={[s.ikonaTlo, { backgroundColor: "rgba(47,212,138,.12)" }]}>
        <Icon name="bank" size={17} color={C.green} />
      </View>
      <View style={{ flex: 1 }}>
        <Text style={s.wierszNazwa} numberOfLines={1}>
          {konto.etykieta || konto.konto}
        </Text>
        <Text style={s.wierszMeta} numberOfLines={1}>
          rachunek {konto.broker || "maklerski"} · {konto.waluta}
        </Text>
        {zarzadzaj && (
          <View style={s.przypisz}>
            <Pressable onPress={() => przypiszKonto(konto.konto, null).then(onOdswiez).catch(() => {})}
                       style={[s.mikroChip, !konto.portfel_id && s.mikroChipOn]}>
              <Text style={[s.mikroTxt, !konto.portfel_id && { color: C.green }]}>luzem</Text>
            </Pressable>
            {portfele.map((p) => (
              <Pressable key={p.id}
                         onPress={() => przypiszKonto(konto.konto, p.id).then(onOdswiez).catch(() => {})}
                         style={[s.mikroChip, konto.portfel_id === p.id && s.mikroChipOn]}>
                <Text style={[s.mikroTxt, konto.portfel_id === p.id && { color: C.green }]}
                      numberOfLines={1}>{p.nazwa}</Text>
              </Pressable>
            ))}
          </View>
        )}
      </View>
      <Text style={s.wierszKwota}>{fmtPLN0(konto.wartosc)} zł</Text>
    </View>
  );
}

function WierszAktywa({ aktywo, onPress }: { aktywo: WealthAktywo; onPress: () => void }) {
  const rynek = aktywo.zrodlo === "rynek";
  const seria = (aktywo.historia || []).map((h) => h.wartosc);
  return (
    <Pressable onPress={onPress} style={({ pressed }) => [s.wiersz, pressed && s.wierszTap]}>
      <View style={[s.ikonaTlo, { backgroundColor: rynek ? "rgba(255,210,74,.12)" : C.elev }]}>
        {maIkone(aktywo.ikona) && (
          <Icon name={aktywo.ikona} size={17} color={rynek ? C.gold : C.muted} />
        )}
      </View>
      <View style={{ flex: 1 }}>
        <Text style={s.wierszNazwa} numberOfLines={1}>{aktywo.nazwa}</Text>
        <Text style={s.wierszMeta} numberOfLines={1}>
          {rynek
            ? `${fmtNum(aktywo.ilosc, 4)} × ${fmtNum(aktywo.kurs || 0, 2)} ${aktywo.kurs_waluta || ""}`
            : aktywo.data
              ? `Twoja wycena z ${aktywo.data}`
              : "bez wyceny — wpisz wartość"}
          {aktywo.wycena_stara ? " · warto odświeżyć" : ""}
        </Text>
      </View>
      {seria.length > 1 && <Sparkline values={seria} width={54} height={20} color={C.gold} />}
      <View style={{ alignItems: "flex-end", marginLeft: 8 }}>
        <Text style={s.wierszKwota}>{fmtPLN0(aktywo.wartosc)} zł</Text>
        <View style={[s.zrodlo, rynek && { borderColor: "rgba(255,210,74,.5)" }]}>
          <Text style={[s.zrodloTxt, rynek && { color: C.gold }]}>
            {rynek ? "rynek" : aktywo.zrodlo === "koszt" ? "z zakupu" : "Twoja wycena"}
          </Text>
        </View>
      </View>
    </Pressable>
  );
}

/* =========================================================== nowy portfel */

function NowyPortfel({ onDodany }: { onDodany: () => void }) {
  const [nazwa, setNazwa] = useState("");
  const [busy, setBusy] = useState(false);
  const [blad, setBlad] = useState("");

  const dodaj = async () => {
    if (!nazwa.trim()) return;
    setBusy(true); setBlad("");
    try {
      await dodajPortfel(nazwa.trim());
      setNazwa(""); onDodany();
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się dodać portfela");
    } finally { setBusy(false); }
  };

  return (
    <Card style={{ marginTop: 10 }}>
      <Text style={s.etykieta}>Nowy portfel</Text>
      <View style={s.poleWrap}>
        <TextInput value={nazwa} onChangeText={setNazwa} placeholder="np. Emerytura"
                   placeholderTextColor={C.dim} style={s.pole} autoCorrect={false}
                   onSubmitEditing={dodaj} returnKeyType="done" />
        {busy
          ? <ActivityIndicator color={C.green} size="small" />
          : <Pressable onPress={dodaj} hitSlop={8}>
              <Text style={[s.dodaj, !nazwa.trim() && { color: C.dim }]}>Dodaj</Text>
            </Pressable>}
      </View>
      {!!blad && <Text style={s.blad}>{blad}</Text>}
      <Text style={s.podpis}>
        Portfel to tylko nazwa dla grupy: wrzucasz do niego rachunki i majątek,
        żeby zobaczyć „ile mam na emeryturę" osobno od reszty. Usunięcie nazwy
        nigdy nie kasuje tego, co w niej leżało.
      </Text>
    </Card>
  );
}

/** Okno „nowy portfel" wywoływane z wyboru przy wgrywaniu.
 *
 *  Musi istnieć osobno od sekcji wyżej, bo sekcja pokazuje się dopiero, gdy są
 *  DWIE grupy — a pierwszego portfela trzeba jakoś dodać, zanim cokolwiek jest
 *  do pokazania. Bez tego wejścia funkcja byłaby zamknięta na klucz leżący
 *  w środku.
 */
export function PortfelOkno({ widoczne, zamknij, gotowe }: {
  widoczne: boolean; zamknij: () => void; gotowe?: () => void;
}) {
  const [portfele, setPortfele] = useState<WealthPortfel[]>([]);

  const wczytaj = useCallback(() => {
    getWealth().then((w) => setPortfele(w.portfele)).catch(() => {});
  }, []);
  useEffect(() => { if (widoczne) wczytaj(); }, [widoczne, wczytaj]);

  if (!widoczne) return null;

  return (
    <Modal visible transparent animationType="slide" onRequestClose={zamknij}>
      <View style={s.tlo}>
        <View style={s.okno}>
          <View style={s.glowa}>
            <View style={{ flex: 1 }}>
              <Text style={s.tytul}>Portfele</Text>
              <Text style={s.podtytul}>Grupy, w których liczy się majątek osobno</Text>
            </View>
            <Pressable onPress={zamknij} hitSlop={10} style={s.x}>
              <Icon name="zamknij" size={15} color={C.muted} />
            </Pressable>
          </View>
          <ScrollView contentContainerStyle={s.tresc} keyboardShouldPersistTaps="handled">
            {portfele.map((p) => (
              <View key={p.id} style={s.wiersz}>
                <View style={[s.ikonaTlo, { backgroundColor: C.elev }]}>
                  <Icon name={maIkone(p.ikona) ? p.ikona : "portfel"} size={17} color={C.muted} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={s.wierszNazwa}>{p.nazwa}</Text>
                  <Text style={s.wierszMeta}>
                    {p.konta.length + p.aktywa.length === 0
                      ? "pusty — przypisz rachunki w Przeglądzie"
                      : `${p.konta.length + p.aktywa.length} ${plural(
                        p.konta.length + p.aktywa.length, "pozycja", "pozycje", "pozycji")}`}
                  </Text>
                </View>
                <Text style={s.wierszKwota}>{fmtPLN0(p.wartosc)} zł</Text>
              </View>
            ))}
            <NowyPortfel onDodany={() => { wczytaj(); portfolioChanged(); gotowe?.(); }} />
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

/* =========================================================== szczegół aktywa */

function SzczegolAktywa({ aktywo, zamknij, onZmiana }: {
  aktywo: WealthAktywo | null; zamknij: () => void; onZmiana: () => void;
}) {
  const [nowa, setNowa] = useState("");
  const [busy, setBusy] = useState(false);
  const [potwierdz, setPotwierdz] = useState(false);

  useEffect(() => { setNowa(""); setPotwierdz(false); }, [aktywo?.id]);

  if (!aktywo) return null;
  const rynek = aktywo.zrodlo === "rynek";
  const seria = (aktywo.historia || []).map((h) => h.wartosc);

  const zapiszWycene = async (kwota: number) => {
    if (!(kwota > 0)) return;
    setBusy(true);
    try {
      await dodajWycene(aktywo.id, kwota);
      onZmiana(); zamknij();
    } finally { setBusy(false); }
  };

  return (
    <Modal visible transparent animationType="slide" onRequestClose={zamknij}>
      <View style={s.tlo}>
        <View style={s.okno}>
          <View style={s.glowa}>
            <View style={{ flex: 1 }}>
              <View style={s.kartaTytul}>
                {maIkone(aktywo.ikona) && (
                  <Icon name={aktywo.ikona} size={18} color={rynek ? C.gold : C.muted} />
                )}
                <Text style={s.tytul} numberOfLines={1}>{aktywo.nazwa}</Text>
              </View>
              <Text style={s.podtytul}>{aktywo.kategoria_nazwa}</Text>
            </View>
            <Pressable onPress={zamknij} hitSlop={10} style={s.x}>
              <Icon name="zamknij" size={15} color={C.muted} />
            </Pressable>
          </View>

          <ScrollView contentContainerStyle={s.tresc} keyboardShouldPersistTaps="handled">
            <Text style={s.duzaKwota}>{fmtPLN(aktywo.wartosc)}</Text>
            <Text style={s.duzyOpis}>
              {rynek
                ? `${fmtNum(aktywo.ilosc, 4)} × ${fmtNum(aktywo.kurs || 0, 2)} ${aktywo.kurs_waluta || ""} — wycena z rynku, aktualizuje się sama`
                : aktywo.data ? `Twoja wycena z ${aktywo.data}` : "bez wyceny"}
            </Text>

            {aktywo.zysk !== null && (
              <Text style={[s.zysk, { color: plColor(aktywo.zysk) }]}>
                {sgnPLN(aktywo.zysk)} od zakupu ({fmtPLN0(aktywo.koszt)} zł)
              </Text>
            )}

            {seria.length > 1 && (
              <View style={{ marginTop: 14 }}>
                <Sparkline values={seria} width={280} height={54} color={C.gold} />
                <Text style={s.podpis}>
                  {seria.length} {plural(seria.length, "wycena", "wyceny", "wycen")} — najstarsza
                  z {aktywo.historia[0].data}
                </Text>
              </View>
            )}

            {/* Podpowiedź po inflacji: liczba, którą sam wpisałeś, przeliczona
                na dzisiejszą siłę nabywczą. Nie jest wyceną, dopóki jej nie
                zatwierdzisz — i tak jest tu napisane. */}
            {!!aktywo.szacunek && (
              <View style={s.szacunek}>
                <Text style={s.szacunekTytul}>
                  Po inflacji to dziś około {fmtPLN0(aktywo.szacunek)} zł
                </Text>
                <Text style={s.szacunekOpis}>
                  Twoja wycena ma {aktywo.wycena_dni} dni. Przez ten czas ceny
                  w Polsce urosły o {fmtNum(aktywo.szacunek_pct || 0, 1)}%
                  {aktywo.szacunek_do ? ` (indeks GUS/Eurostat po ${aktywo.szacunek_do})` : ""},
                  więc ta sama wartość realna odpowiada dziś tej kwocie.{" "}
                  <Text style={s.mocny}>To nie jest wycena rynkowa</Text> — Twoje
                  mieszkanie mogło zdrożeć bardziej albo wcale. Jeśli uznasz, że
                  pasuje, zapiszemy ją jako nową wycenę.
                </Text>
                <View style={{ marginTop: 10 }}>
                  <MetalButton label={busy ? "Zapisuję…" : "Przyjmij tę kwotę"} size="sm"
                               tone="green" onPress={() => zapiszWycene(aktywo.szacunek!)} />
                </View>
              </View>
            )}

            {!rynek && (
              <View style={{ marginTop: 16 }}>
                <Text style={s.etykieta}>Nowa wycena</Text>
                <View style={s.poleWrap}>
                  <TextInput value={nowa} onChangeText={setNowa} placeholder="ile jest warte dziś"
                             placeholderTextColor={C.dim} style={s.pole} keyboardType="numeric" />
                  <Text style={s.sufiks}>zł</Text>
                </View>
                <View style={{ marginTop: 10 }}>
                  <MetalButton label={busy ? "Zapisuję…" : "Dopisz wycenę"}
                               tone={nowa.trim() ? "green" : "steel"}
                               onPress={() => zapiszWycene(
                                 Number(nowa.replace(/\s/g, "").replace(",", ".")))} />
                </View>
                <Text style={s.podpis}>
                  Stare wyceny zostają — z nich powstaje wykres wartości w czasie.
                </Text>
              </View>
            )}

            {/* Usuwanie za drugim kliknięciem. Aktywo trzyma historię wycen,
                której nie da się odtworzyć, więc jedno przypadkowe dotknięcie
                nie może jej zabrać. */}
            <Pressable onPress={() => {
              if (!potwierdz) { setPotwierdz(true); return; }
              usunAktywo(aktywo.id).then(() => { onZmiana(); zamknij(); }).catch(() => {});
            }} hitSlop={8} style={s.usunAktywo}>
              <Text style={[s.usunTxt, potwierdz && { color: C.red }]}>
                {potwierdz ? "Na pewno? Dotknij jeszcze raz, żeby usunąć" : "Usuń z majątku"}
              </Text>
            </Pressable>
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

