/** Bezpiecznik ekranu — łapie błąd renderu, zamiast pozwolić mu zgasić całą apkę.
 *
 *  Bez tego pojedynczy wyjątek w dowolnym komponencie odmontowuje całe drzewo Reacta
 *  i zostaje biała (albo czarna) plansza, z której nie da się nic zrobić poza
 *  ubiciem aplikacji. Bezpiecznik zatrzymuje awarię na granicy jednej sekcji:
 *  reszta apki działa dalej, a zepsuty fragment można złożyć od nowa jednym
 *  dotknięciem — `attempt` zmienia `key` dzieci, więc montują się od zera,
 *  ze świeżym stanem.
 *
 *  `resetKey` służy do resetu automatycznego: przy zmianie zakładki albo zakresu
 *  dat nie ma sensu trzymać użytkownika na ekranie błędu sprzed chwili.
 */
import React from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import { C, T } from "../theme";
import Icon from "./Icon";

//  Świadomie same prymitywy React Native i nic z `ui/index` — ekran ratunkowy nie
//  może zależeć od komponentów, które przed chwilą mogły być przyczyną awarii
//  (a przy okazji nie robi cyklu importów z barelem `ui/index`).

type Props = {
  children: React.ReactNode;
  /** nazwa sekcji — trafia do komunikatu i do logu */
  name?: string;
  /** zmiana tej wartości kasuje stan błędu (np. przejście na inną zakładkę) */
  resetKey?: string | number;
  /** dodatkowe wyjście, np. zamknięcie modalu */
  onDismiss?: () => void;
  dismissLabel?: string;
};

type State = { error: Error | null; attempt: number };

export default class ErrorBoundary extends React.Component<Props, State> {
  state: State = { error: null, attempt: 0 };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: { componentStack?: string }) {
    // Log zostaje w konsoli Metro — bez niego diagnoza sprowadza się do zgadywania,
    // bo użytkownik widzi już tylko ekran ratunkowy.
    console.error(`[${this.props.name || "ekran"}] błąd renderu:`, error, info?.componentStack);
  }

  componentDidUpdate(prev: Props) {
    if (prev.resetKey !== this.props.resetKey && this.state.error) {
      this.reset();
    }
  }

  reset = () => {
    this.setState((s) => ({ error: null, attempt: s.attempt + 1 }));
  };

  render() {
    const { error, attempt } = this.state;
    if (!error) {
      return <React.Fragment key={attempt}>{this.props.children}</React.Fragment>;
    }

    return (
      <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
        <View style={s.icon}><Icon name="odswiez" size={19} color={C.green} /></View>
        <Text style={s.title}>Coś się zacięło</Text>
        <Text style={s.body}>
          {this.props.name
            ? `Sekcja „${this.props.name}" nie dała rady się wyświetlić.`
            : "Ten widok nie dał rady się wyświetlić."}
          {" "}Nic nie zostało zepsute — wystarczy złożyć go od nowa.
        </Text>
        <View style={s.actions}>
          <Pressable style={[s.btn, s.btnMain]} onPress={this.reset}>
            <Text style={s.btnMainTxt}>Załaduj od nowa</Text>
          </Pressable>
          {!!this.props.onDismiss && (
            <Pressable style={s.btn} onPress={this.props.onDismiss}>
              <Text style={s.btnTxt}>{this.props.dismissLabel || "Zamknij"}</Text>
            </Pressable>
          )}
        </View>
        <Text style={s.detail} numberOfLines={4}>{String(error?.message || error)}</Text>
      </ScrollView>
    );
  }
}

const s = StyleSheet.create({
  wrap: { flexGrow: 1, alignItems: "center", justifyContent: "center", padding: 30, gap: 12 },
  icon: {
    width: 56, height: 56, borderRadius: 18, alignItems: "center", justifyContent: "center",
    backgroundColor: C.greenDim, borderWidth: 1, borderColor: "rgba(47,212,138,.35)",
  },
  title: { color: C.text, ...T.h1, textAlign: "center" },
  body: { color: C.muted, ...T.body, textAlign: "center", lineHeight: 21, maxWidth: 340 },
  actions: { flexDirection: "row", gap: 10, marginTop: 8, flexWrap: "wrap", justifyContent: "center" },
  btn: {
    borderRadius: 13, paddingVertical: 13, paddingHorizontal: 22,
    borderWidth: 1, borderColor: C.border2, backgroundColor: C.card, minWidth: 150,
    alignItems: "center",
  },
  btnTxt: { color: C.muted, fontSize: 14, fontWeight: "800" },
  btnMain: { borderColor: "rgba(47,212,138,.6)", backgroundColor: C.greenDim },
  btnMainTxt: { color: C.green, fontSize: 14, fontWeight: "800" },
  detail: { color: C.dim, fontSize: 10.5, textAlign: "center", marginTop: 14, maxWidth: 340 },
});
