/** Wgrywanie raportów XTB prosto z telefonu i z przeglądarki.
 *
 *  Bez raportu apka nie ma o czym liczyć, więc ta sekcja pojawia się w dwóch
 *  miejscach: na górze „Więcej" (tryb `compact`) oraz — gdy portfel jest jeszcze
 *  pusty — na pierwszym ekranie, żeby nie trzeba było jej szukać.
 *
 *  Dwie DROGI WYSYŁKI, bo to są dwa różne światy:
 *
 *  * przeglądarka — `input type=file` oddaje gotowy `Blob`, więc wysyłamy go jako
 *    surowe bajty. Wcześniej szedł tędy multipart w kształcie React Native
 *    (`{uri, name, type}`); natywna FormData zamieniała ten obiekt na tekst
 *    „[object Object]" i serwer odpowiadał „nie udało się odczytać pliku".
 *    Wgranie raportu przez stronę było przez to niemożliwe;
 *  * telefon (apka) — multipart, bo RN czyta plik prosto z dysku i nic nie
 *    przechodzi przez tekst. Gdyby zawiódł, lecimy awaryjnie base64.
 *
 *  Formatu nie zgadujemy z nazwy: telefon potrafi podać „document.bin", a i tak
 *  w środku jest poprawny raport — rozstrzyga panel, który patrzy na zawartość.
 *
 *  Wgrywanie jest bezpieczne do powtarzania — operacje mają klucz (konto + numer
 *  operacji), więc ten sam raport wgrany drugi raz nie zdubluje ani jednej pozycji.
 *  Dlatego najprościej za każdym razem brać raport od początku konta.
 */
import { wybierzPlik } from "../filePicker";
import { AiReport, AssetForm } from "./AssetForm";
import ImportChooser, { Wybor } from "./ImportChooser";
import { PortfelOkno } from "./WealthSection";
import * as FileSystem from "expo-file-system/legacy";
import React, { useState, useCallback } from "react";
import { ActivityIndicator, Platform, Pressable, StyleSheet, Text, View } from "react-native";
import { ImportResult, importReport, importReportBytes, importReportFile } from "../api";
import { portfolioChanged } from "../refresh";
import { C, T } from "../theme";
import { Card, LiquidButton } from "../ui";
import ReportHelp, { ReportHelpButton } from "./ReportHelp";

/** Pusty plik to prawie zawsze jedno i to samo: raport leży w chmurze (iCloud
 *  Drive / Dysk Google) i nie został jeszcze ściągnięty na urządzenie. System
 *  oddaje wtedy samą „zapowiedź" pliku — nazwę bez zawartości. */
const PUSTY = "Plik przyszedł pusty. Jeśli trzymasz go w iCloud Drive lub na "
  + "Dysku Google, otwórz go najpierw w aplikacji Pliki i poczekaj, aż zniknie "
  + "ikonka chmurki (plik ściągnie się na telefon) — potem wybierz go tutaj.";

export default function ReportUpload({
  compact = false, onImported,
}: {
  /** wersja do listy ustawień — bez wielkiego nagłówka i tłumaczenia od zera */
  compact?: boolean;
  onImported: () => void;
}) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  /** Okno wyboru staje PRZED wyborem pliku: do portfela wchodzą teraz trzy
   *  różne rzeczy (raport znanego brokera, raport nieznanego, majątek),
   *  a jeden przycisk „wgraj" nie potrafi ich rozróżnić. */
  const [wybor, setWybor] = useState(false);
  const [majatek, setMajatek] = useState<string | null>(null);
  const [portfele, setPortfele] = useState(false);
  const [ai, setAi] = useState(false);
  const [aiZostalo, setAiZostalo] = useState<number | null | undefined>(undefined);
  const [done, setDone] = useState<ImportResult[] | null>(null);
  /** pliki z paczki, których nie dało się wczytać — reszta i tak weszła */
  const [warn, setWarn] = useState<string[]>([]);
  /** samouczek „skąd wziąć raport" — ten sam w obu wariantach komponentu */
  const [help, setHelp] = useState(false);

  const otworzWybor = useCallback(() => {
    setWybor(true);
    // Limit pobieramy dopiero przy otwarciu okna, nie przy wejściu na ekran —
    // większość ludzi nigdy nie kliknie „wgraj", a to jedno żądanie mniej.
    import("../api").then(({ getAiLimit }) =>
      getAiLimit().then((l) => setAiZostalo(l.premium ? null : l.zostalo))
        .catch(() => setAiZostalo(undefined)));
  }, []);

  const obsluzWybor = useCallback((co: Wybor) => {
    setWybor(false);
    if (co === "xtb") {
      // Na iOS zamknięcie Modala i natychmiastowe otwarcie DocumentPickera
      // powoduje cichą kolizję — picker nigdy się nie pojawia, bo system
      // próbuje go zaprezentować, gdy animacja dismiss jeszcze trwa.
      // Dajemy 450 ms na dokończenie animacji zamknięcia okna wyboru.
      if (Platform.OS === "ios") {
        setTimeout(() => pick(), 450);
      } else {
        pick();
      }
    }
    else if (co === "ai") setAi(true);
    else if (co === "portfel") setPortfele(true);
    else if (co === "majatek") setMajatek("");
    else setMajatek("akcje");
  }, []);

  async function pick() {
    setErr("");
    setDone(null);
    setWarn([]);
    try {
      // Kolejkowane wejście do pickera — patrz src/filePicker.ts (kolizja
      // „Different document picking in progress" przy podwójnym tapnięciu).
      const res = await wybierzPlik({
        // „*/*" jest tu celowo pierwsze i samo. Ograniczenie typów wygasza w
        // przeglądarce plików wszystko, czego system nie rozpoznał — a raport
        // ściągnięty na telefon albo leżący w iCloud Drive bardzo często ma typ
        // „nieznany". Filtrowanie po typie odbierało więc dostęp do pliku, który
        // jest zupełnie poprawny. Format i tak rozstrzyga serwer po zawartości.
        type: "*/*",
        // Kopia do cache to jedyny sposób, żeby dostać plik z iCloud Drive:
        // system musi go najpierw ŚCIĄGNĄĆ z chmury na urządzenie.
        copyToCacheDirectory: true,
        multiple: false,
      });
      if (res.canceled || !res.assets?.length) return;
      const file = res.assets[0];
      const name = file.name || "raport.xlsx";
      // Plik z chmury, którego system nie zdążył ściągnąć, ma zero bajtów. Lepiej
      // powiedzieć to od razu niż wysyłać pustkę i tłumaczyć „nierozpoznany format".
      if (file.size === 0) throw new Error(PUSTY);
      setBusy(true);

      let out: Awaited<ReturnType<typeof importReportFile>> | null = null;

      if (Platform.OS === "web") {
        // Przeglądarka: mamy prawdziwy plik (Blob) — idzie surowymi bajtami.
        const blob: Blob = (file as any).file ?? (await (await fetch(file.uri)).blob());
        if (!blob || blob.size === 0) throw new Error(PUSTY);
        out = await importReportBytes(blob, name);
      } else {
        out = await importReportFile(file.uri, name, file.mimeType).catch(() => null);
        if (!out) {
          // Multipart nie doszedł (np. provider oddał plik, którego RN nie umie
          // streamować) — czytamy go sami i wysyłamy jako base64.
          const b64 = await FileSystem.readAsStringAsync(file.uri, { encoding: "base64" })
            .catch(() => "");
          if (!b64) throw new Error(PUSTY);
          out = await importReport(b64, name);
        }
      }
      if (!out.ok) {
        setErr(out.error || "Panel odrzucił plik");
        return;
      }
      setDone(out.results || []);
      setWarn(out.warnings || []);
      // Ekran, w którym stoi ten formularz, odświeża się sam (`onImported`), ale
      // pozostałe zakładki zostają zamontowane ze starymi danymi — dlatego obok
      // idzie sygnał do WSZYSTKICH. Bez niego raport wgrany w „Więcej" nie
      // pojawiał się w Przeglądzie, a wgrany w Przeglądzie nie docierał do Alokacji.
      portfolioChanged();
      onImported();
    } catch (e: any) {
      setErr(e?.message || "Nie udało się wgrać raportu");
    } finally {
      setBusy(false);
    }
  }

  const nowe = (done || []).reduce((s, r) => s + r.ops_new, 0);

  const body = (
    <Card style={compact ? undefined : { marginTop: 4 }}>
      {!compact && (
        <Text style={s.lead}>
          Portevo liczy się z raportów XTB. Pobierz raport w aplikacji brokera
          (Historia → eksport do Excela) i wgraj go tutaj — resztę policzy panel.
          Może być .xlsx, .csv albo cała paczka .zip; plik z iCloud Drive lub Dysku
          Google też przejdzie, o ile jest już ściągnięty na urządzenie.
        </Text>
      )}

      <LiquidButton label={busy ? "Wgrywam…" : "Wybierz raport (.xlsx / .csv / .zip)"}
                    disabled={busy} onPress={otworzWybor}
                    style={{ marginTop: compact ? 0 : 14 }} />

      {!compact && (
        <Text style={{ color: C.dim, fontSize: 10.5, marginTop: 10, textAlign: "center", lineHeight: 15 }}>
          Portevo jest niezależnym oprogramowaniem i nie jest powiązane z brokerem XTB S.A.
        </Text>
      )}

      {busy && (
        <View style={s.busy}>
          <ActivityIndicator color={C.green} />
          <Text style={s.dim}>Czytam plik i przeliczam portfel…</Text>
        </View>
      )}

      {!!err && <Text style={s.err}>{err}</Text>}

      {!!done && (
        <View style={s.done}>
          <Text style={s.doneTitle}>
            {nowe > 0 ? `Dodano ${nowe} nowych operacji` : "Wszystko już było — nic nie doszło"}
          </Text>
          {done.map((r, i) => (
            <Text key={i} style={s.doneRow} numberOfLines={1}>
              {r.file} · konto {r.account} · {r.ops_new}/{r.ops_total} operacji
              {r.closed_new ? ` · ${r.closed_new} zamkniętych pozycji` : ""}
            </Text>
          ))}
        </View>
      )}

      {warn.length > 0 && (
        <View style={s.warn}>
          {warn.map((w, i) => (
            <Text key={i} style={s.warnRow}>Pominięto — {w}</Text>
          ))}
        </View>
      )}

      {/* Druga droga do samouczka — obok znaku zapytania w nagłówku. Ktoś, kto
          utknął dopiero przy wyborze pliku, nie wraca wzrokiem do góry ekranu. */}
      <Pressable onPress={() => setHelp(true)} style={s.helpRow} hitSlop={6}>
        <Text style={s.helpTxt}>Nie wiesz, jak pobrać raport z XTB?</Text>
        <Text style={s.helpLink}>Pokaż krok po kroku ›</Text>
      </Pressable>

      <Text style={s.hint}>
        Możesz wgrywać ten sam okres wielokrotnie — operacje rozpoznają się po numerze,
        więc nic się nie zdubluje. Najbezpieczniej brać raport od początku konta.
      </Text>
    </Card>
  );

  const okno = (
    <>
      {help && <ReportHelp onClose={() => setHelp(false)} />}
      <ImportChooser widoczne={wybor} zamknij={() => setWybor(false)}
                     wybierz={obsluzWybor} aiZostalo={aiZostalo} />
      <AssetForm widoczne={majatek !== null} kategoriaStart={majatek || undefined}
                 zamknij={() => setMajatek(null)} gotowe={onImported} />
      <PortfelOkno widoczne={portfele} zamknij={() => setPortfele(false)} gotowe={onImported} />
      <AiReport widoczne={ai} zamknij={() => setAi(false)} gotowe={onImported} />
    </>
  );

  if (compact) {
    return (
      <>
        <View style={s.nagWrap}>
          <View style={s.nagRzad}>
            <Text style={s.nagTytul}>Wgraj raport</Text>
            <ReportHelpButton onPress={() => setHelp(true)} />
          </View>
          <Text style={s.nagHint}>Raport z XTB — nowe transakcje dopiszą się do starych</Text>
        </View>
        {body}
        {okno}
      </>
    );
  }

  return (
    <View style={s.wrap}>
      <View style={s.nagRzad}>
        <Text style={s.h1}>Zacznij od raportu</Text>
        <ReportHelpButton onPress={() => setHelp(true)} />
      </View>
      <Text style={s.sub}>Bez niego nie ma czego liczyć</Text>
      {body}
      {okno}
    </View>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 10, gap: 4 },
  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginBottom: 14 },

  // nagłówek z „?" — odwzorowuje SectionTitle, ale mieści przycisk obok tytułu
  nagWrap: { marginTop: 26, marginBottom: 11 },
  nagRzad: { flexDirection: "row", alignItems: "center", gap: 9 },
  nagTytul: { color: C.text, ...T.h2 },
  nagHint: { color: C.dim, ...T.small, marginTop: 3, lineHeight: 17 },

  helpRow: {
    flexDirection: "row", alignItems: "center", justifyContent: "space-between",
    gap: 10, marginTop: 14, paddingTop: 13,
    borderTopWidth: 1, borderTopColor: "rgba(33,41,56,.9)",
  },
  helpTxt: { color: C.muted, fontSize: 12.3, flex: 1, lineHeight: 17 },
  helpLink: { color: C.green, fontSize: 12.3, fontWeight: "800" },
  lead: { color: C.muted, ...T.body, lineHeight: 21 },
  busy: { flexDirection: "row", alignItems: "center", gap: 10, marginTop: 14 },
  dim: { color: C.muted, ...T.small },
  err: { color: C.red, fontSize: 13, marginTop: 12, lineHeight: 18 },
  done: {
    marginTop: 14, padding: 12, borderRadius: 12,
    backgroundColor: C.greenDim, borderWidth: 1, borderColor: "rgba(47,212,138,.35)",
  },
  doneTitle: { color: C.green, fontWeight: "800", fontSize: 13.5 },
  doneRow: { color: C.muted, fontSize: 11.5, marginTop: 4 },
  warn: { marginTop: 10, gap: 3 },
  warnRow: { color: C.dim, fontSize: 11, lineHeight: 16 },
  hint: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 14 },
});
